INSERT INTO `assessment_questions` (`id`, `assessment_id`, `question_text`, `type`, `topic`, `options`, `correct_option`, `user_answer`, `is_correct`, `explanation`, `created_at`, `updated_at`) VALUES
(1, 1, 'Dalam aplikasi web modern berbasis React / Vue, apa tujuan utama penggunaan Virtual DOM dibandingkan langsung memanipulasi Real DOM browser?', 'hard_skill', 'Modern Frontend Architecture', '{\"A\":\"Menghitung perbedaan (diffing) di memori dan meminimalkan operasi render reflow\\/repaint pada Real DOM yang mahal\",\"B\":\"Menyimpan seluruh data aplikasi ke dalam LocalStorage secara otomatis\",\"C\":\"Mengamankan web dari serangan SQL Injection dan XSS secara penuh\",\"D\":\"Mempercepat transmisi data TCP antara klien dan server\"}', 'A', 'A', 1, 'Virtual DOM membandingkan snapshot pohon DOM sebelum dan sesudah perubahan state, lalu hanya menerapkan perubahan spesifik pada browser.', '2026-09-20 08:03:16', '2026-09-20 08:34:45'),
(2, 1, 'Pada framework Laravel, apa solusi terbaik untuk mengatasi masalah query performa \"N+1 Problem\" ketika mengambil relasi data mahasiswa beserta daftar portofolionya?', 'hard_skill', 'ORM & Database Performance', '{\"A\":\"Menggunakan Eager Loading dengan method User::with(\'portfolios\')->get()\",\"B\":\"Melakukan query di dalam perulangan foreach blade template\",\"C\":\"Menonaktifkan relasi foreign key pada migrasi database\",\"D\":\"Mengubah tipe basis data menjadi NoSQL MongoDB\"}', 'A', 'C', 0, 'Eager Loading mengambil semua relasi terkait hanya dalam 1-2 query SQL gabungan, mencegah query berulang sebanyak N baris data.', '2026-09-20 08:03:16', '2026-09-20 08:34:45'),
(3, 1, 'Dalam alur kerja Git kolaboratif tim industri, perintah apa yang digunakan untuk mengambil perubahan terbaru dari remote server sekaligus menggabungkannya ke branch kerja saat ini?', 'hard_skill', 'Git Version Control', '{\"A\":\"git pull\",\"B\":\"git push --force\",\"C\":\"git stash drop\",\"D\":\"git reset --hard\"}', 'A', 'C', 0, 'git pull menjalankan kombinasi git fetch (mengambil data dari remote) dan git merge (menggabungkan ke branch lokal).', '2026-09-20 08:03:16', '2026-09-20 08:34:45'),
(4, 1, 'Dalam arsitektur RESTful API modern, metode HTTP manakah yang bersifat idempoten (idempotent) dan digunakan untuk memperbarui seluruh representasi sumber daya (resource)?', 'hard_skill', 'RESTful API Architecture', '{\"A\":\"PUT\",\"B\":\"POST\",\"C\":\"PATCH\",\"D\":\"DELETE\"}', 'A', 'B', 0, 'PUT bersifat idempoten karena pemanggilan berulang kali dengan payload yang sama akan menghasilkan status akhir sumber daya yang identik.', '2026-09-20 08:03:16', '2026-09-20 08:34:45'),
(5, 1, 'Anda menemukan bug kritis di server production tepat 30 menit sebelum jam peluncuran sistem. Sikap profesional rekayasa apa yang paling tepat dilakukan?', 'soft_skill', 'Problem Solving & Insiden Kerja', '{\"A\":\"Mengomunikasikan temuan ke tim\\/stakeholder secara transparan, menganalisis risiko, dan menerapkan hotfix teruji atau menunda peluncuran secara aman\",\"B\":\"Mengabaikan bug tersebut dengan harapan tidak ditemukan oleh pengguna\",\"C\":\"Menyalahkan rekan tim yang menulis modul tersebut di grup publik\",\"D\":\"Melakukan perubahan langsung di server live tanpa membuat cadangan kode dan database\"}', 'A', 'B', 0, 'Integritas teknis dan komunikasi risiko secara objektif merupakan soft-skill paling berharga bagi seorang profesional engineering.', '2026-09-20 08:03:16', '2026-09-20 08:34:45'),
(6, 1, 'Dalam arsitektur container Docker, apa fungsi utama dari file Dockerfile dalam siklus deployment aplikasi web?', 'hard_skill', 'DevOps & Containerization', '{\"A\":\"Berisi instruksi deklaratif untuk membangun Image aplikasi yang terisolasi dan konsisten di berbagai lingkungan\",\"B\":\"Menyimpan password database production secara plaintext\",\"C\":\"Menggantikan fungsi web server Nginx dan Apache\",\"D\":\"Sebagai pengganti compiler bahasa pemrograman\"}', 'A', 'B', 0, 'Dockerfile mendefinisikan layer sistem operasi dasar, dependensi library, dan konfigurasi runtime untuk menghasilkan Docker Image.', '2026-09-20 08:03:16', '2026-09-20 08:34:45'),
(7, 1, 'Ketika query laporan tracer study pada basis data MySQL yang memiliki 500.000 baris data terasa lambat, optimasi indeks apa yang paling tepat dipasang?', 'hard_skill', 'Database Indexing & Optimization', '{\"A\":\"Menambahkan B-Tree Index pada kolom yang sering digunakan di klausa WHERE dan JOIN\",\"B\":\"Menghapus primary key pada tabel\",\"C\":\"Mengubah semua tipe data VARCHAR menjadi TEXT\",\"D\":\"Melakukan query SELECT * tanpa klausa limit\"}', 'A', 'D', 0, 'Index B-Tree mempercepat pencarian data dari kompleksitas O(N) full table scan menjadi O(log N).', '2026-09-20 08:03:16', '2026-09-20 08:34:45'),
(8, 2, 'Anda menemukan bug kritis di server production tepat 30 menit sebelum jam peluncuran sistem. Sikap profesional rekayasa apa yang paling tepat dilakukan?', 'soft_skill', 'Problem Solving & Insiden Kerja', '{\"A\":\"Mengomunikasikan temuan ke tim\\/stakeholder secara transparan, menganalisis risiko, dan menerapkan hotfix teruji atau menunda peluncuran secara aman\",\"B\":\"Mengabaikan bug tersebut dengan harapan tidak ditemukan oleh pengguna\",\"C\":\"Menyalahkan rekan tim yang menulis modul tersebut di grup publik\",\"D\":\"Melakukan perubahan langsung di server live tanpa membuat cadangan kode dan database\"}', 'A', 'A', 1, 'Integritas teknis dan komunikasi risiko secara objektif merupakan soft-skill paling berharga bagi seorang profesional engineering.', '2026-09-20 08:37:08', '2026-09-20 08:37:39'),
(9, 2, 'Dalam aplikasi web modern berbasis React / Vue, apa tujuan utama penggunaan Virtual DOM dibandingkan langsung memanipulasi Real DOM browser?', 'hard_skill', 'Modern Frontend Architecture', '{\"A\":\"Menghitung perbedaan (diffing) di memori dan meminimalkan operasi render reflow\\/repaint pada Real DOM yang mahal\",\"B\":\"Menyimpan seluruh data aplikasi ke dalam LocalStorage secara otomatis\",\"C\":\"Mengamankan web dari serangan SQL Injection dan XSS secara penuh\",\"D\":\"Mempercepat transmisi data TCP antara klien dan server\"}', 'A', 'A', 1, 'Virtual DOM membandingkan snapshot pohon DOM sebelum dan sesudah perubahan state, lalu hanya menerapkan perubahan spesifik pada browser.', '2026-09-20 08:37:08', '2026-09-20 08:37:39'),
(10, 2, 'Ketika query laporan tracer study pada basis data MySQL yang memiliki 500.000 baris data terasa lambat, optimasi indeks apa yang paling tepat dipasang?', 'hard_skill', 'Database Indexing & Optimization', '{\"A\":\"Menambahkan B-Tree Index pada kolom yang sering digunakan di klausa WHERE dan JOIN\",\"B\":\"Menghapus primary key pada tabel\",\"C\":\"Mengubah semua tipe data VARCHAR menjadi TEXT\",\"D\":\"Melakukan query SELECT * tanpa klausa limit\"}', 'A', 'C', 0, 'Index B-Tree mempercepat pencarian data dari kompleksitas O(N) full table scan menjadi O(log N).', '2026-09-20 08:37:08', '2026-09-20 08:37:39'),
(11, 2, 'Pada framework Laravel, apa solusi terbaik untuk mengatasi masalah query performa \"N+1 Problem\" ketika mengambil relasi data mahasiswa beserta daftar portofolionya?', 'hard_skill', 'ORM & Database Performance', '{\"A\":\"Menggunakan Eager Loading dengan method User::with(\'portfolios\')->get()\",\"B\":\"Melakukan query di dalam perulangan foreach blade template\",\"C\":\"Menonaktifkan relasi foreign key pada migrasi database\",\"D\":\"Mengubah tipe basis data menjadi NoSQL MongoDB\"}', 'A', 'C', 0, 'Eager Loading mengambil semua relasi terkait hanya dalam 1-2 query SQL gabungan, mencegah query berulang sebanyak N baris data.', '2026-09-20 08:37:08', '2026-09-20 08:37:39'),
(12, 2, 'Dalam arsitektur RESTful API modern, metode HTTP manakah yang bersifat idempoten (idempotent) dan digunakan untuk memperbarui seluruh representasi sumber daya (resource)?', 'hard_skill', 'RESTful API Architecture', '{\"A\":\"PUT\",\"B\":\"POST\",\"C\":\"PATCH\",\"D\":\"DELETE\"}', 'A', 'A', 1, 'PUT bersifat idempoten karena pemanggilan berulang kali dengan payload yang sama akan menghasilkan status akhir sumber daya yang identik.', '2026-09-20 08:37:08', '2026-09-20 08:37:39'),
(13, 2, 'Dalam alur kerja Git kolaboratif tim industri, perintah apa yang digunakan untuk mengambil perubahan terbaru dari remote server sekaligus menggabungkannya ke branch kerja saat ini?', 'hard_skill', 'Git Version Control', '{\"A\":\"git pull\",\"B\":\"git push --force\",\"C\":\"git stash drop\",\"D\":\"git reset --hard\"}', 'A', 'B', 0, 'git pull menjalankan kombinasi git fetch (mengambil data dari remote) dan git merge (menggabungkan ke branch lokal).', '2026-09-20 08:37:08', '2026-09-20 08:37:39'),
(14, 2, 'Dalam arsitektur container Docker, apa fungsi utama dari file Dockerfile dalam siklus deployment aplikasi web?', 'hard_skill', 'DevOps & Containerization', '{\"A\":\"Berisi instruksi deklaratif untuk membangun Image aplikasi yang terisolasi dan konsisten di berbagai lingkungan\",\"B\":\"Menyimpan password database production secara plaintext\",\"C\":\"Menggantikan fungsi web server Nginx dan Apache\",\"D\":\"Sebagai pengganti compiler bahasa pemrograman\"}', 'A', 'C', 0, 'Dockerfile mendefinisikan layer sistem operasi dasar, dependensi library, dan konfigurasi runtime untuk menghasilkan Docker Image.', '2026-09-20 08:37:08', '2026-09-20 08:37:39'),
(15, 3, 'Klien meminta penambahan 3 fitur kompleks baru di tengah sprint yang sudah berjalan dengan batas waktu deadline yang tidak bisa diundur. Bagaimana respons terbaik Anda?', 'soft_skill', 'Manajemen Ekspektasi & Agile', '{\"A\":\"Mendiskusikan trade-off secara profesional, menetapkan prioritas fitur MVP, dan memindahkan fitur tambahan ke sprint berikutnya\",\"B\":\"Langsung mengiyakan semua permintaan meskipun tahu tim tidak akan sanggup menyelesaikannya\",\"C\":\"Memutus kontak dengan klien dan tidak masuk kerja\",\"D\":\"Menghapus pengujian unit dan standar keamanan demi mengejar waktu\"}', 'A', 'A', 1, 'Pengembang profesional mengelola ruang lingkup secara transparan dengan fokus pada nilai bisnis dan viabilitas teknis.', '2026-09-20 10:28:51', '2026-09-20 10:32:45'),
(16, 3, 'Pada antarmuka input pencarian real-time (auto-complete), teknik apa yang digunakan untuk menunda eksekusi pemanggilan API hingga pengguna berhenti mengetik selama durasi tertentu?', 'hard_skill', 'Frontend Optimization', '{\"A\":\"Debouncing\",\"B\":\"Throttling\",\"C\":\"Server Polling\",\"D\":\"CSS Keyframe Animation\"}', 'A', 'C', 0, 'Debounce me-reset timer setiap kali karakter baru diketik, sehingga request API hanya dikirim saat pengguna jeda sejenak.', '2026-09-20 10:28:51', '2026-09-20 10:32:45'),
(17, 3, 'Ketika melakukan Code Review pada pull request rekan satu tim, Anda menemukan pendekatan kode yang berbeda dengan gaya Anda namun tetap benar dan efisien. Tindakan terbaik Anda adalah:', 'soft_skill', 'Kolaborasi & Code Review', '{\"A\":\"Menyetujui PR jika memenuhi standar arsitektur tim dan uji unit lulus, sambil memberikan saran konstruktif opsional\",\"B\":\"Menolak PR dan memaksakan gaya koding pribadi Anda\",\"C\":\"Mengabaikan PR tersebut tanpa memberikan review selama berhari-hari\",\"D\":\"Mengubah kode rekan kerja secara sepihak tanpa izin\"}', 'A', 'A', 1, 'Code review berfokus pada kualitas, kebenaran, dan keterbacaan kode tim, bukan preferensi gaya personal penguji.', '2026-09-20 10:28:51', '2026-09-20 10:32:45'),
(18, 3, 'Seorang stakeholder non-teknis memberikan kebutuhan aplikasi yang sangat samar: \"Buat sistem yang pintar dan otomatis\". Langkah konkret apa yang harus Anda ambil?', 'soft_skill', 'Komunikasi Kebutuhan Bisnis', '{\"A\":\"Mengajak stakeholder berdiskusi dengan membuat alur use case sederhana, kriteria keberhasilan yang terukur, dan wireframe interaktif\",\"B\":\"Langsung menulis kode rumit berdasarkan asumsi sendiri tanpa konfirmasi\",\"C\":\"Menolak proyek dan mengatakan stakeholder tidak kompeten\",\"D\":\"Menunggu sampai ada dokumen spesifikasi lengkap setebal 100 halaman\"}', 'A', 'A', 1, 'Menerjemahkan ide abstrak menjadi kriteria terukur dan prototipe visual adalah peran kunci perekayasa perangkat lunak.', '2026-09-20 10:28:51', '2026-09-20 10:32:45'),
(19, 3, 'Dalam strategi caching data performa tinggi, pola \"Cache-Aside\" (Lazy Loading) bekerja dengan cara:', 'hard_skill', 'Sistem Caching (Redis/Memcached)', '{\"A\":\"Aplikasi memeriksa cache terlebih dahulu; jika miss, ambil dari database lalu simpan salinannya ke cache\",\"B\":\"Menghapus database utama dan hanya mengandalkan cache RAM\",\"C\":\"Menulis data hanya ke cache tanpa pernah menyimpannya ke database\",\"D\":\"Memuat seluruh tabel database ke cache saat komputer pertama kali dinyalakan\"}', 'A', 'A', 1, 'Cache-aside hanya menyimpan data yang benar-benar di-request pengguna, menjaga efisiensi kapasitas memori cache.', '2026-09-20 10:28:51', '2026-09-20 10:32:45'),
(20, 3, 'Manakah langkah proteksi paling mendasar dan efektif untuk mencegah kerentanan SQL Injection pada aplikasi web?', 'hard_skill', 'Keamanan Perangkat Lunak', '{\"A\":\"Menggunakan Parameterized Queries atau Prepared Statements yang memisahkan instruksi SQL dari data masukan pengguna\",\"B\":\"Menyimpan data password menggunakan enkripsi Base64\",\"C\":\"Mengubah port default web server dari port 80 menjadi port 8080\",\"D\":\"Menonaktifkan firewall pada server database\"}', 'A', 'A', 1, 'Prepared statements memastikan parameter input diperlakukan murni sebagai data literal, bukan sebagai kode SQL executable.', '2026-09-20 10:28:51', '2026-09-20 10:32:45'),
(21, 3, 'Ketika aplikasi web mengalami lonjakan pengiriman email konfirmasi (10.000 email sekaligus), arsitektur apa yang paling tepat digunakan agar antarmuka pengguna tidak macet (non-blocking)?', 'hard_skill', 'Message Broker & Asynchronous Queue', '{\"A\":\"Asynchronous Message Queue (misal: Redis Queue \\/ RabbitMQ) yang diproses oleh background worker\",\"B\":\"Menjalankan loop pengiriman email di controller utama request HTTP\",\"C\":\"Meminta pengguna untuk menunggu loading browser selama 15 menit\",\"D\":\"Mengubah ukuran RAM komputer klien\"}', 'A', 'A', 1, 'Queue menyimpan tugas di antrean pesan dan langsung mengembalikan respon HTTP ke pengguna dalam hitungan milidetik.', '2026-09-20 10:28:51', '2026-09-20 10:32:45'),
(22, 3, 'Kapan arsitektur basis data NoSQL tipe Dokumen (seperti MongoDB) lebih diutamakan dibandingkan SQL Relasional tradisional?', 'hard_skill', 'Database Architecture', '{\"A\":\"Saat skema data bersifat dinamis, tidak terstruktur ketat, dan membutuhkan skalabilitas horizontal cepat\",\"B\":\"Saat membutuhkan integritas transaksi multi-tabel perbankan yang ketat\",\"C\":\"Saat data hanya berjumlah kurang dari 100 baris\",\"D\":\"Saat tidak diperbolehkan menggunakan memori RAM di server\"}', 'A', 'A', 1, 'NoSQL dokumen menyimpan data JSON-like polimorfik tanpa perlu migrasi DDL kaku setiap perubahan struktur kolom.', '2026-09-20 10:28:51', '2026-09-20 10:32:45'),
(23, 3, 'Dalam arsitektur RESTful API modern, metode HTTP manakah yang bersifat idempoten (idempotent) dan digunakan untuk memperbarui seluruh representasi sumber daya (resource)?', 'hard_skill', 'RESTful API Architecture', '{\"A\":\"PUT\",\"B\":\"POST\",\"C\":\"PATCH\",\"D\":\"DELETE\"}', 'A', 'B', 0, 'PUT bersifat idempoten karena pemanggilan berulang kali dengan payload yang sama akan menghasilkan status akhir sumber daya yang identik.', '2026-09-20 10:28:51', '2026-09-20 10:32:45'),
(24, 3, 'Dalam prinsip transaksi ACID pada basis data relasional, apa yang dimaksud dengan sifat \"Atomicity\"?', 'hard_skill', 'Database Transaction (ACID)', '{\"A\":\"Semua operasi dalam satu transaksi harus berhasil sepenuhnya, jika satu gagal maka seluruh transaksi dibatalkan (Rollback)\",\"B\":\"Data disimpan dalam partisi atomik memori cache RAM\",\"C\":\"Setiap tabel harus memiliki minimal 10 indeks kolom\",\"D\":\"Database tidak boleh diakses oleh lebih dari satu pengguna dalam satu detik\"}', 'A', 'D', 0, 'Atomicity menjamin prinsip \"all or nothing\", mencegah inkonsistensi data parsial saat terjadi gangguan server.', '2026-09-20 10:28:51', '2026-09-20 10:32:45'),
(25, 4, 'Anda menemukan bug kritis di server production tepat 30 menit sebelum jam peluncuran sistem. Sikap profesional rekayasa apa yang paling tepat dilakukan?', 'soft_skill', 'Problem Solving & Insiden Kerja', '{\"A\":\"Mengomunikasikan temuan ke tim\\/stakeholder secara transparan, menganalisis risiko, dan menerapkan hotfix teruji atau menunda peluncuran secara aman\",\"B\":\"Mengabaikan bug tersebut dengan harapan tidak ditemukan oleh pengguna\",\"C\":\"Menyalahkan rekan tim yang menulis modul tersebut di grup publik\",\"D\":\"Melakukan perubahan langsung di server live tanpa membuat cadangan kode dan database\"}', 'A', 'A', 1, 'Integritas teknis dan komunikasi risiko secara objektif merupakan soft-skill paling berharga bagi seorang profesional engineering.', '2026-09-20 23:49:38', '2026-09-20 23:50:18'),
(26, 4, 'Struktur standar JSON Web Token (JWT) terdiri dari tiga bagian yang dipisahkan tanda titik (.):', 'hard_skill', 'Autentikasi & Otorisasi Modern', '{\"A\":\"Header.Payload.Signature\",\"B\":\"User.Password.Token\",\"C\":\"Protocol.Domain.Port\",\"D\":\"Encryption.Salt.Hash\"}', 'A', 'A', 1, 'Header berisi tipe token dan algoritma enkripsi, Payload berisi klaim data, dan Signature memverifikasi keaslian token.', '2026-09-20 23:49:38', '2026-09-20 23:50:18'),
(27, 4, 'Dalam arsitektur container Docker, apa fungsi utama dari file Dockerfile dalam siklus deployment aplikasi web?', 'hard_skill', 'DevOps & Containerization', '{\"A\":\"Berisi instruksi deklaratif untuk membangun Image aplikasi yang terisolasi dan konsisten di berbagai lingkungan\",\"B\":\"Menyimpan password database production secara plaintext\",\"C\":\"Menggantikan fungsi web server Nginx dan Apache\",\"D\":\"Sebagai pengganti compiler bahasa pemrograman\"}', 'A', 'A', 1, 'Dockerfile mendefinisikan layer sistem operasi dasar, dependensi library, dan konfigurasi runtime untuk menghasilkan Docker Image.', '2026-09-20 23:49:38', '2026-09-20 23:50:18'),
(28, 4, 'Seorang anggota tim junior tampak kesulitan dan frustrasi menyelesaikan tugas modul autentikasi selama 2 hari berturut-turut. Sikap empati teknis apa yang harus ditunjukkan?', 'soft_skill', 'Mentoring & Kerjasama Tim', '{\"A\":\"Mengajak berdiskusi santai, melakukan sesi pair-programming untuk memecah masalah menjadi sub-tugas yang lebih kecil, dan memberi bimbingan\",\"B\":\"Mengambil alih tugasnya secara diam-diam tanpa menjelaskan apapun\",\"C\":\"Memarahi junior tersebut di depan seluruh anggota tim saat stand-up meeting\",\"D\":\"Membiarkannya sampai deadline lewat agar dia belajar sendiri\"}', 'A', 'A', 1, 'Pair-programming dan bimbingan memecah hambatan teknis sekaligus mempercepat transfer pengetahuan dalam tim.', '2026-09-20 23:49:38', '2026-09-20 23:50:18'),
(29, 4, 'Pada framework Laravel, apa solusi terbaik untuk mengatasi masalah query performa \"N+1 Problem\" ketika mengambil relasi data mahasiswa beserta daftar portofolionya?', 'hard_skill', 'ORM & Database Performance', '{\"A\":\"Menggunakan Eager Loading dengan method User::with(\'portfolios\')->get()\",\"B\":\"Melakukan query di dalam perulangan foreach blade template\",\"C\":\"Menonaktifkan relasi foreign key pada migrasi database\",\"D\":\"Mengubah tipe basis data menjadi NoSQL MongoDB\"}', 'A', 'B', 0, 'Eager Loading mengambil semua relasi terkait hanya dalam 1-2 query SQL gabungan, mencegah query berulang sebanyak N baris data.', '2026-09-20 23:49:38', '2026-09-20 23:50:18'),
(30, 4, 'Setelah insiden downtime sistem berhasil dipulihkan, tim mengadakan rapat \"Blameless Post-Mortem\". Apa tujuan utama dari rapat ini?', 'soft_skill', 'Budaya Teknik & Retrospektif', '{\"A\":\"Mengidentifikasi akar penyebab sistemik (Root Cause) dan merancang mitigasi pencegahan agar insiden serupa tidak terulang\",\"B\":\"Mencari satu orang untuk dijatuhi sanksi dan disalahkan atas insiden\",\"C\":\"Menghapus log error agar reputasi tim tidak terlihat buruk\",\"D\":\"Memperdebatkan siapa yang paling berjasa memulihkan sistem\"}', 'A', 'A', 1, 'Blameless post-mortem mengasumsikan kesalahan terjadi akibat kelemahan sistem dan prosedur, bukan kelalaian jahat individu.', '2026-09-20 23:49:38', '2026-09-20 23:50:18'),
(31, 4, 'Pada sistem operasi Linux server, perintah baris apa yang paling cepat digunakan untuk memantau proses mana yang paling banyak memakan CPU dan memori secara interaktif?', 'hard_skill', 'Linux & Server Administration', '{\"A\":\"top atau htop\",\"B\":\"ls -la\",\"C\":\"chmod 777\",\"D\":\"ping localhost\"}', 'A', 'B', 0, 'Perintah top/htop menampilkan task manager interaktif di terminal dengan urutan penggunaan CPU dan RAM terkini.', '2026-09-20 23:49:38', '2026-09-20 23:50:18'),
(32, 4, 'Teknik apa yang digunakan oleh web browser untuk mempercepat metrik LCP (Largest Contentful Paint) pada halaman web yang memiliki banyak gambar besar?', 'hard_skill', 'Web Performance & Core Web Vitals', '{\"A\":\"Implementasi Lazy Loading (loading=\\\"lazy\\\"), format WebP\\/AVIF modern, dan CDN aset statis\",\"B\":\"Mengubah gambar menjadi file audio\",\"C\":\"Menghapus file CSS styling utama\",\"D\":\"Menjalankan loop JavaScript untuk mengunduh semua gambar bersamaan di thread utama\"}', 'A', 'A', 1, 'Lazy loading menunda download gambar off-screen hingga pengguna menggulir mendekati viewport, membebaskan bandwidth.', '2026-09-20 23:49:38', '2026-09-20 23:50:18'),
(33, 4, 'Untuk mencegah serangan Cross-Site Scripting (Stored XSS) pada kolom komentar pengguna, mekanisme apa yang wajib diimplementasikan sebelum merender konten ke browser?', 'hard_skill', 'Keamanan Web (OWASP)', '{\"A\":\"HTML Entity Encoding \\/ Sanitasi output sehingga tag seperti <script> tidak dieksekusi browser\",\"B\":\"Mengharuskan pengguna mengunggah file zip\",\"C\":\"Menggunakan protokol HTTP\\/2\",\"D\":\"Menghapus session cookie setelah 5 detik\"}', 'A', 'A', 1, 'Encoding mengonversi karakter berbahaya seperti < dan > menjadi &lt; dan &gt; sehingga browser merendernya sebagai teks biasa.', '2026-09-20 23:49:38', '2026-09-20 23:50:18'),
(34, 4, 'Dalam aplikasi web modern berbasis React / Vue, apa tujuan utama penggunaan Virtual DOM dibandingkan langsung memanipulasi Real DOM browser?', 'hard_skill', 'Modern Frontend Architecture', '{\"A\":\"Menghitung perbedaan (diffing) di memori dan meminimalkan operasi render reflow\\/repaint pada Real DOM yang mahal\",\"B\":\"Menyimpan seluruh data aplikasi ke dalam LocalStorage secara otomatis\",\"C\":\"Mengamankan web dari serangan SQL Injection dan XSS secara penuh\",\"D\":\"Mempercepat transmisi data TCP antara klien dan server\"}', 'A', 'B', 0, 'Virtual DOM membandingkan snapshot pohon DOM sebelum dan sesudah perubahan state, lalu hanya menerapkan perubahan spesifik pada browser.', '2026-09-20 23:49:38', '2026-09-20 23:50:18'),
(35, 5, 'Laporan audit keamanan menemukan celah kerentanan kritis kategori High pada dependensi pihak ketiga yang digunakan sistem Anda. Tindakan prioritas tim adalah:', 'soft_skill', 'Manajemen Risiko Keamanan', '{\"A\":\"Mengevaluasi dampak, memperbarui package ke versi patch terbaru di staging, menjalankan automated test suite, dan segera rilis patch ke production\",\"B\":\"Menunda penanganan celah keamanan selama 6 bulan sampai roadmap fitur selesai\",\"C\":\"Menghapus modul keamanan dari sistem agar audit tidak mendeteksi celah lagi\",\"D\":\"Menganggap celah keamanan hanya teori dan tidak mungkin diserang hacker nyata\"}', 'A', 'A', 1, 'Kerentanan kritis pada dependensi harus dimitigasi segera dengan proses verifikasi regresi yang terukur.', '2026-09-21 00:30:40', '2026-09-21 00:31:46'),
(36, 5, 'Pada antarmuka input pencarian real-time (auto-complete), teknik apa yang digunakan untuk menunda eksekusi pemanggilan API hingga pengguna berhenti mengetik selama durasi tertentu?', 'hard_skill', 'Frontend Optimization', '{\"A\":\"Debouncing\",\"B\":\"Throttling\",\"C\":\"Server Polling\",\"D\":\"CSS Keyframe Animation\"}', 'A', 'C', 0, 'Debounce me-reset timer setiap kali karakter baru diketik, sehingga request API hanya dikirim saat pengguna jeda sejenak.', '2026-09-21 00:30:40', '2026-09-21 00:31:46'),
(37, 5, 'Tim backend perlu merilis pembaruan endpoint API yang mengubah format payload response secara signifikan (breaking change). Apa langkah profesional terbaik sebelum perubahan di-deploy?', 'soft_skill', 'Manajemen Rilis & Kolaborasi', '{\"A\":\"Membuat API versioning baru (misal \\/api\\/v2), mengomunikasikan timeline deprecation ke tim mobile\\/frontend, dan menjaga v1 tetap berjalan sementara\",\"B\":\"Langsung mengubah endpoint v1 di production tanpa pemberitahuan apapun\",\"C\":\"Mematikan server mobile secara tiba-tiba agar mereka sadar ada pembaruan\",\"D\":\"Menolak melakukan pembaruan selamanya demi kompatibilitas lama\"}', 'A', 'A', 1, 'Versioning API dan komunikasi transparan melindungi integrasi klien dari kegagalan fungsional yang fatal.', '2026-09-21 00:30:40', '2026-09-21 00:31:46'),
(38, 5, 'Ketika query laporan tracer study pada basis data MySQL yang memiliki 500.000 baris data terasa lambat, optimasi indeks apa yang paling tepat dipasang?', 'hard_skill', 'Database Indexing & Optimization', '{\"A\":\"Menambahkan B-Tree Index pada kolom yang sering digunakan di klausa WHERE dan JOIN\",\"B\":\"Menghapus primary key pada tabel\",\"C\":\"Mengubah semua tipe data VARCHAR menjadi TEXT\",\"D\":\"Melakukan query SELECT * tanpa klausa limit\"}', 'A', 'A', 1, 'Index B-Tree mempercepat pencarian data dari kompleksitas O(N) full table scan menjadi O(log N).', '2026-09-21 00:30:40', '2026-09-21 00:31:46'),
(39, 5, 'Dalam prinsip SOLID, prinsip \"Dependency Inversion Principle\" (DIP) menyatakan bahwa:', 'hard_skill', 'Clean Code & Desain Perangkat Lunak', '{\"A\":\"Modul tingkat tinggi tidak boleh bergantung pada modul tingkat rendah; keduanya harus bergantung pada abstraksi (interface)\",\"B\":\"Semua fungsi harus ditulis dalam satu file class besar\",\"C\":\"Variabel harus dideklarasikan terbalik dari urutan eksekusi\",\"D\":\"Database tidak boleh memiliki relasi tabel antar entitas\"}', 'A', 'A', 1, 'DIP memisahkan implementasi konkret melalui interface sehingga kode mudah diuji (mocking) dan fleksibel diubah.', '2026-09-21 00:30:40', '2026-09-21 00:31:46'),
(40, 5, 'Ketika aplikasi web mengalami lonjakan pengiriman email konfirmasi (10.000 email sekaligus), arsitektur apa yang paling tepat digunakan agar antarmuka pengguna tidak macet (non-blocking)?', 'hard_skill', 'Message Broker & Asynchronous Queue', '{\"A\":\"Asynchronous Message Queue (misal: Redis Queue \\/ RabbitMQ) yang diproses oleh background worker\",\"B\":\"Menjalankan loop pengiriman email di controller utama request HTTP\",\"C\":\"Meminta pengguna untuk menunggu loading browser selama 15 menit\",\"D\":\"Mengubah ukuran RAM komputer klien\"}', 'A', 'A', 1, 'Queue menyimpan tugas di antrean pesan dan langsung mengembalikan respon HTTP ke pengguna dalam hitungan milidetik.', '2026-09-21 00:30:40', '2026-09-21 00:31:46'),
(41, 5, 'Dalam strategi caching data performa tinggi, pola \"Cache-Aside\" (Lazy Loading) bekerja dengan cara:', 'hard_skill', 'Sistem Caching (Redis/Memcached)', '{\"A\":\"Aplikasi memeriksa cache terlebih dahulu; jika miss, ambil dari database lalu simpan salinannya ke cache\",\"B\":\"Menghapus database utama dan hanya mengandalkan cache RAM\",\"C\":\"Menulis data hanya ke cache tanpa pernah menyimpannya ke database\",\"D\":\"Memuat seluruh tabel database ke cache saat komputer pertama kali dinyalakan\"}', 'A', 'A', 1, 'Cache-aside hanya menyimpan data yang benar-benar di-request pengguna, menjaga efisiensi kapasitas memori cache.', '2026-09-21 00:30:40', '2026-09-21 00:31:46'),
(42, 5, 'Dalam arsitektur container Docker, apa fungsi utama dari file Dockerfile dalam siklus deployment aplikasi web?', 'hard_skill', 'DevOps & Containerization', '{\"A\":\"Berisi instruksi deklaratif untuk membangun Image aplikasi yang terisolasi dan konsisten di berbagai lingkungan\",\"B\":\"Menyimpan password database production secara plaintext\",\"C\":\"Menggantikan fungsi web server Nginx dan Apache\",\"D\":\"Sebagai pengganti compiler bahasa pemrograman\"}', 'A', 'A', 1, 'Dockerfile mendefinisikan layer sistem operasi dasar, dependensi library, dan konfigurasi runtime untuk menghasilkan Docker Image.', '2026-09-21 00:30:40', '2026-09-21 00:31:46'),
(43, 5, 'Dalam prinsip transaksi ACID pada basis data relasional, apa yang dimaksud dengan sifat \"Atomicity\"?', 'hard_skill', 'Database Transaction (ACID)', '{\"A\":\"Semua operasi dalam satu transaksi harus berhasil sepenuhnya, jika satu gagal maka seluruh transaksi dibatalkan (Rollback)\",\"B\":\"Data disimpan dalam partisi atomik memori cache RAM\",\"C\":\"Setiap tabel harus memiliki minimal 10 indeks kolom\",\"D\":\"Database tidak boleh diakses oleh lebih dari satu pengguna dalam satu detik\"}', 'A', 'A', 1, 'Atomicity menjamin prinsip \"all or nothing\", mencegah inkonsistensi data parsial saat terjadi gangguan server.', '2026-09-21 00:30:40', '2026-09-21 00:31:46'),
(44, 5, 'Pada framework Laravel, apa solusi terbaik untuk mengatasi masalah query performa \"N+1 Problem\" ketika mengambil relasi data mahasiswa beserta daftar portofolionya?', 'hard_skill', 'ORM & Database Performance', '{\"A\":\"Menggunakan Eager Loading dengan method User::with(\'portfolios\')->get()\",\"B\":\"Melakukan query di dalam perulangan foreach blade template\",\"C\":\"Menonaktifkan relasi foreign key pada migrasi database\",\"D\":\"Mengubah tipe basis data menjadi NoSQL MongoDB\"}', 'A', 'A', 1, 'Eager Loading mengambil semua relasi terkait hanya dalam 1-2 query SQL gabungan, mencegah query berulang sebanyak N baris data.', '2026-09-21 00:30:41', '2026-09-21 00:31:46'),
(45, 5, 'Pada protokol HTTPS, bagaimana proses pertukaran kunci enkripsi terjadi saat proses TLS Handshake awal?', 'hard_skill', 'Jaringan & Kriptografi', '{\"A\":\"Menggunakan kriptografi asimetris (Public\\/Private Key) untuk menyepakati Symmetric Session Key yang efisien\",\"B\":\"Mengirimkan password database secara plaintext\",\"C\":\"Hanya menggunakan algoritma hashing MD5 satu arah\",\"D\":\"Mengabaikan sertifikat SSL jika domain tidak cocok\"}', 'A', 'A', 1, 'TLS menggunakan asimetris untuk autentikasi dan negosiasi kunci, kemudian menggunakan simetris untuk enkripsi data berkecepatan tinggi.', '2026-09-21 00:30:41', '2026-09-21 00:31:46'),
(46, 5, 'Dalam alur kerja Git kolaboratif tim industri, perintah apa yang digunakan untuk mengambil perubahan terbaru dari remote server sekaligus menggabungkannya ke branch kerja saat ini?', 'hard_skill', 'Git Version Control', '{\"A\":\"git pull\",\"B\":\"git push --force\",\"C\":\"git stash drop\",\"D\":\"git reset --hard\"}', 'A', 'A', 1, 'git pull menjalankan kombinasi git fetch (mengambil data dari remote) dan git merge (menggabungkan ke branch lokal).', '2026-09-21 00:30:41', '2026-09-21 00:31:46'),
(47, 5, 'Dalam arsitektur RESTful API modern, metode HTTP manakah yang bersifat idempoten (idempotent) dan digunakan untuk memperbarui seluruh representasi sumber daya (resource)?', 'hard_skill', 'RESTful API Architecture', '{\"A\":\"PUT\",\"B\":\"POST\",\"C\":\"PATCH\",\"D\":\"DELETE\"}', 'A', 'C', 0, 'PUT bersifat idempoten karena pemanggilan berulang kali dengan payload yang sama akan menghasilkan status akhir sumber daya yang identik.', '2026-09-21 00:30:41', '2026-09-21 00:31:46'),
(48, 5, 'Manakah langkah proteksi paling mendasar dan efektif untuk mencegah kerentanan SQL Injection pada aplikasi web?', 'hard_skill', 'Keamanan Perangkat Lunak', '{\"A\":\"Menggunakan Parameterized Queries atau Prepared Statements yang memisahkan instruksi SQL dari data masukan pengguna\",\"B\":\"Menyimpan data password menggunakan enkripsi Base64\",\"C\":\"Mengubah port default web server dari port 80 menjadi port 8080\",\"D\":\"Menonaktifkan firewall pada server database\"}', 'A', 'A', 1, 'Prepared statements memastikan parameter input diperlakukan murni sebagai data literal, bukan sebagai kode SQL executable.', '2026-09-21 00:30:41', '2026-09-21 00:31:46'),
(49, 5, 'Bagaimana strategi tim developer dalam mengelola \"Technical Debt\" (utang teknis) agar aplikasi tetap scalable dalam jangka panjang?', 'soft_skill', 'Manajemen Utang Teknis', '{\"A\":\"Mendokumentasikan technical debt di backlog dan mengalokasikan persentase kapasitas tertentu di tiap sprint untuk refactoring\",\"B\":\"Tidak pernah melakukan refactoring sampai aplikasi benar-benar crash\",\"C\":\"Menulis ulang seluruh aplikasi dari nol setiap kali ada teknologi framework baru\",\"D\":\"Menyembunyikan kode yang berantakan dengan mengabaikan peringatan linter\"}', 'A', 'C', 0, 'Mengalokasikan kapasitas berkala (misal 15-20% per sprint) menjaga keseimbangan antara rilis fitur dan kesehatan basis kode.', '2026-09-21 00:30:41', '2026-09-21 00:31:46'),
(50, 5, 'Seorang stakeholder non-teknis memberikan kebutuhan aplikasi yang sangat samar: \"Buat sistem yang pintar dan otomatis\". Langkah konkret apa yang harus Anda ambil?', 'soft_skill', 'Komunikasi Kebutuhan Bisnis', '{\"A\":\"Mengajak stakeholder berdiskusi dengan membuat alur use case sederhana, kriteria keberhasilan yang terukur, dan wireframe interaktif\",\"B\":\"Langsung menulis kode rumit berdasarkan asumsi sendiri tanpa konfirmasi\",\"C\":\"Menolak proyek dan mengatakan stakeholder tidak kompeten\",\"D\":\"Menunggu sampai ada dokumen spesifikasi lengkap setebal 100 halaman\"}', 'A', 'A', 1, 'Menerjemahkan ide abstrak menjadi kriteria terukur dan prototipe visual adalah peran kunci perekayasa perangkat lunak.', '2026-09-21 00:30:41', '2026-09-21 00:31:46'),
(51, 5, 'Teknologi protokol apa yang paling efisien untuk mengimplementasikan fitur Dashboard Monitoring Real-Time dengan komunikasi dua arah (full-duplex) tanpa overhead polling berulang?', 'hard_skill', 'Komunikasi Real-time', '{\"A\":\"WebSocket\",\"B\":\"HTTP Short Polling\",\"C\":\"FTP Transfer\",\"D\":\"SMTP Mail Service\"}', 'A', 'A', 1, 'WebSocket mempertahankan koneksi TCP tunggal terbuka secara persisten, memungkinkan push data instan dari server ke klien.', '2026-09-21 00:30:41', '2026-09-21 00:31:46'),
(52, 5, 'Ketika melakukan Code Review pada pull request rekan satu tim, Anda menemukan pendekatan kode yang berbeda dengan gaya Anda namun tetap benar dan efisien. Tindakan terbaik Anda adalah:', 'soft_skill', 'Kolaborasi & Code Review', '{\"A\":\"Menyetujui PR jika memenuhi standar arsitektur tim dan uji unit lulus, sambil memberikan saran konstruktif opsional\",\"B\":\"Menolak PR dan memaksakan gaya koding pribadi Anda\",\"C\":\"Mengabaikan PR tersebut tanpa memberikan review selama berhari-hari\",\"D\":\"Mengubah kode rekan kerja secara sepihak tanpa izin\"}', 'A', 'C', 0, 'Code review berfokus pada kualitas, kebenaran, dan keterbacaan kode tim, bukan preferensi gaya personal penguji.', '2026-09-21 00:30:41', '2026-09-21 00:31:46'),
(53, 5, 'Berapa kompleksitas waktu rata-rata algoritma Binary Search untuk mencari suatu data pada larik (array) yang sudah terurut sepanjang N elemen?', 'hard_skill', 'Struktur Data & Algoritma', '{\"A\":\"O(log N)\",\"B\":\"O(N)\",\"C\":\"O(N^2)\",\"D\":\"O(1)\"}', 'A', 'B', 0, 'Binary Search membagi ruang pencarian menjadi separuh pada setiap iterasi, menghasilkan kompleksitas logaritmik O(log N).', '2026-09-21 00:30:41', '2026-09-21 00:31:46'),
(54, 5, 'Pada arsitektur sistem berbasis Microservices, pola arsitektur apa yang digunakan untuk mencegah kegagalan satu service merambat (cascading failure) ke seluruh ekosistem aplikasi?', 'hard_skill', 'Arsitektur Microservices', '{\"A\":\"Circuit Breaker Pattern\",\"B\":\"Singleton Pattern\",\"C\":\"Monolithic Model\",\"D\":\"Direct Synchronous Loop\"}', 'A', 'A', 1, 'Circuit Breaker memutus panggilan sementara ke service yang sedang down/timeout dan memberikan fallback response instan.', '2026-09-21 00:30:41', '2026-09-21 00:31:46'),
(135, 10, 'Klien meminta penambahan 3 fitur kompleks baru di tengah sprint yang sudah berjalan dengan batas waktu deadline yang tidak bisa diundur. Bagaimana respons terbaik Anda?', 'soft_skill', 'Manajemen Ekspektasi & Agile', '{\"A\":\"Mendiskusikan trade-off secara profesional, menetapkan prioritas fitur MVP, dan memindahkan fitur tambahan ke sprint berikutnya\",\"B\":\"Langsung mengiyakan semua permintaan meskipun tahu tim tidak akan sanggup menyelesaikannya\",\"C\":\"Memutus kontak dengan klien dan tidak masuk kerja\",\"D\":\"Menghapus pengujian unit dan standar keamanan demi mengejar waktu\"}', 'A', 'A', 1, 'Pengembang profesional mengelola ruang lingkup secara transparan dengan fokus pada nilai bisnis dan viabilitas teknis.', '2026-09-30 11:08:25', '2026-09-30 11:09:34'),
(136, 10, 'Teknik apa yang digunakan oleh web browser untuk mempercepat metrik LCP (Largest Contentful Paint) pada halaman web yang memiliki banyak gambar besar?', 'hard_skill', 'Web Performance & Core Web Vitals', '{\"A\":\"Implementasi Lazy Loading (loading=\\\"lazy\\\"), format WebP\\/AVIF modern, dan CDN aset statis\",\"B\":\"Mengubah gambar menjadi file audio\",\"C\":\"Menghapus file CSS styling utama\",\"D\":\"Menjalankan loop JavaScript untuk mengunduh semua gambar bersamaan di thread utama\"}', 'A', 'D', 0, 'Lazy loading menunda download gambar off-screen hingga pengguna menggulir mendekati viewport, membebaskan bandwidth.', '2026-09-30 11:08:25', '2026-09-30 11:09:34'),
(137, 10, 'Laporan audit keamanan menemukan celah kerentanan kritis kategori High pada dependensi pihak ketiga yang digunakan sistem Anda. Tindakan prioritas tim adalah:', 'soft_skill', 'Manajemen Risiko Keamanan', '{\"A\":\"Mengevaluasi dampak, memperbarui package ke versi patch terbaru di staging, menjalankan automated test suite, dan segera rilis patch ke production\",\"B\":\"Menunda penanganan celah keamanan selama 6 bulan sampai roadmap fitur selesai\",\"C\":\"Menghapus modul keamanan dari sistem agar audit tidak mendeteksi celah lagi\",\"D\":\"Menganggap celah keamanan hanya teori dan tidak mungkin diserang hacker nyata\"}', 'A', 'A', 1, 'Kerentanan kritis pada dependensi harus dimitigasi segera dengan proses verifikasi regresi yang terukur.', '2026-09-30 11:08:25', '2026-09-30 11:09:34'),
(138, 10, 'Bagaimana strategi tim developer dalam mengelola \"Technical Debt\" (utang teknis) agar aplikasi tetap scalable dalam jangka panjang?', 'soft_skill', 'Manajemen Utang Teknis', '{\"A\":\"Mendokumentasikan technical debt di backlog dan mengalokasikan persentase kapasitas tertentu di tiap sprint untuk refactoring\",\"B\":\"Tidak pernah melakukan refactoring sampai aplikasi benar-benar crash\",\"C\":\"Menulis ulang seluruh aplikasi dari nol setiap kali ada teknologi framework baru\",\"D\":\"Menyembunyikan kode yang berantakan dengan mengabaikan peringatan linter\"}', 'A', 'A', 1, 'Mengalokasikan kapasitas berkala (misal 15-20% per sprint) menjaga keseimbangan antara rilis fitur dan kesehatan basis kode.', '2026-09-30 11:08:25', '2026-09-30 11:09:34'),
(139, 10, 'Dalam alur kerja Git kolaboratif tim industri, perintah apa yang digunakan untuk mengambil perubahan terbaru dari remote server sekaligus menggabungkannya ke branch kerja saat ini?', 'hard_skill', 'Git Version Control', '{\"A\":\"git pull\",\"B\":\"git push --force\",\"C\":\"git stash drop\",\"D\":\"git reset --hard\"}', 'A', 'D', 0, 'git pull menjalankan kombinasi git fetch (mengambil data dari remote) dan git merge (menggabungkan ke branch lokal).', '2026-09-30 11:08:25', '2026-09-30 11:09:34'),
(140, 10, 'Setelah insiden downtime sistem berhasil dipulihkan, tim mengadakan rapat \"Blameless Post-Mortem\". Apa tujuan utama dari rapat ini?', 'soft_skill', 'Budaya Teknik & Retrospektif', '{\"A\":\"Mengidentifikasi akar penyebab sistemik (Root Cause) dan merancang mitigasi pencegahan agar insiden serupa tidak terulang\",\"B\":\"Mencari satu orang untuk dijatuhi sanksi dan disalahkan atas insiden\",\"C\":\"Menghapus log error agar reputasi tim tidak terlihat buruk\",\"D\":\"Memperdebatkan siapa yang paling berjasa memulihkan sistem\"}', 'A', 'A', 1, 'Blameless post-mortem mengasumsikan kesalahan terjadi akibat kelemahan sistem dan prosedur, bukan kelalaian jahat individu.', '2026-09-30 11:08:25', '2026-09-30 11:09:34'),
(141, 10, 'Dalam strategi caching data performa tinggi, pola \"Cache-Aside\" (Lazy Loading) bekerja dengan cara:', 'hard_skill', 'Sistem Caching (Redis/Memcached)', '{\"A\":\"Aplikasi memeriksa cache terlebih dahulu; jika miss, ambil dari database lalu simpan salinannya ke cache\",\"B\":\"Menghapus database utama dan hanya mengandalkan cache RAM\",\"C\":\"Menulis data hanya ke cache tanpa pernah menyimpannya ke database\",\"D\":\"Memuat seluruh tabel database ke cache saat komputer pertama kali dinyalakan\"}', 'A', 'A', 1, 'Cache-aside hanya menyimpan data yang benar-benar di-request pengguna, menjaga efisiensi kapasitas memori cache.', '2026-09-30 11:08:25', '2026-09-30 11:09:34'),
(142, 10, 'Dalam prinsip SOLID, prinsip \"Dependency Inversion Principle\" (DIP) menyatakan bahwa:', 'hard_skill', 'Clean Code & Desain Perangkat Lunak', '{\"A\":\"Modul tingkat tinggi tidak boleh bergantung pada modul tingkat rendah; keduanya harus bergantung pada abstraksi (interface)\",\"B\":\"Semua fungsi harus ditulis dalam satu file class besar\",\"C\":\"Variabel harus dideklarasikan terbalik dari urutan eksekusi\",\"D\":\"Database tidak boleh memiliki relasi tabel antar entitas\"}', 'A', 'A', 1, 'DIP memisahkan implementasi konkret melalui interface sehingga kode mudah diuji (mocking) dan fleksibel diubah.', '2026-09-30 11:08:25', '2026-09-30 11:09:34'),
(143, 10, 'Untuk mencegah serangan Cross-Site Scripting (Stored XSS) pada kolom komentar pengguna, mekanisme apa yang wajib diimplementasikan sebelum merender konten ke browser?', 'hard_skill', 'Keamanan Web (OWASP)', '{\"A\":\"HTML Entity Encoding \\/ Sanitasi output sehingga tag seperti <script> tidak dieksekusi browser\",\"B\":\"Mengharuskan pengguna mengunggah file zip\",\"C\":\"Menggunakan protokol HTTP\\/2\",\"D\":\"Menghapus session cookie setelah 5 detik\"}', 'A', 'A', 1, 'Encoding mengonversi karakter berbahaya seperti < dan > menjadi &lt; dan &gt; sehingga browser merendernya sebagai teks biasa.', '2026-09-30 11:08:25', '2026-09-30 11:09:34'),
(144, 10, 'Anda menemukan bug kritis di server production tepat 30 menit sebelum jam peluncuran sistem. Sikap profesional rekayasa apa yang paling tepat dilakukan?', 'soft_skill', 'Problem Solving & Insiden Kerja', '{\"A\":\"Mengomunikasikan temuan ke tim\\/stakeholder secara transparan, menganalisis risiko, dan menerapkan hotfix teruji atau menunda peluncuran secara aman\",\"B\":\"Mengabaikan bug tersebut dengan harapan tidak ditemukan oleh pengguna\",\"C\":\"Menyalahkan rekan tim yang menulis modul tersebut di grup publik\",\"D\":\"Melakukan perubahan langsung di server live tanpa membuat cadangan kode dan database\"}', 'A', 'A', 1, 'Integritas teknis dan komunikasi risiko secara objektif merupakan soft-skill paling berharga bagi seorang profesional engineering.', '2026-09-30 11:08:25', '2026-09-30 11:09:34'),
(145, 10, 'Ketika aplikasi web mengalami lonjakan pengiriman email konfirmasi (10.000 email sekaligus), arsitektur apa yang paling tepat digunakan agar antarmuka pengguna tidak macet (non-blocking)?', 'hard_skill', 'Message Broker & Asynchronous Queue', '{\"A\":\"Asynchronous Message Queue (misal: Redis Queue \\/ RabbitMQ) yang diproses oleh background worker\",\"B\":\"Menjalankan loop pengiriman email di controller utama request HTTP\",\"C\":\"Meminta pengguna untuk menunggu loading browser selama 15 menit\",\"D\":\"Mengubah ukuran RAM komputer klien\"}', 'A', 'A', 1, 'Queue menyimpan tugas di antrean pesan dan langsung mengembalikan respon HTTP ke pengguna dalam hitungan milidetik.', '2026-09-30 11:08:25', '2026-09-30 11:09:34'),
(146, 10, 'Tim backend perlu merilis pembaruan endpoint API yang mengubah format payload response secara signifikan (breaking change). Apa langkah profesional terbaik sebelum perubahan di-deploy?', 'soft_skill', 'Manajemen Rilis & Kolaborasi', '{\"A\":\"Membuat API versioning baru (misal \\/api\\/v2), mengomunikasikan timeline deprecation ke tim mobile\\/frontend, dan menjaga v1 tetap berjalan sementara\",\"B\":\"Langsung mengubah endpoint v1 di production tanpa pemberitahuan apapun\",\"C\":\"Mematikan server mobile secara tiba-tiba agar mereka sadar ada pembaruan\",\"D\":\"Menolak melakukan pembaruan selamanya demi kompatibilitas lama\"}', 'A', 'A', 1, 'Versioning API dan komunikasi transparan melindungi integrasi klien dari kegagalan fungsional yang fatal.', '2026-09-30 11:08:25', '2026-09-30 11:09:34'),
(147, 10, 'Seorang stakeholder non-teknis memberikan kebutuhan aplikasi yang sangat samar: \"Buat sistem yang pintar dan otomatis\". Langkah konkret apa yang harus Anda ambil?', 'soft_skill', 'Komunikasi Kebutuhan Bisnis', '{\"A\":\"Mengajak stakeholder berdiskusi dengan membuat alur use case sederhana, kriteria keberhasilan yang terukur, dan wireframe interaktif\",\"B\":\"Langsung menulis kode rumit berdasarkan asumsi sendiri tanpa konfirmasi\",\"C\":\"Menolak proyek dan mengatakan stakeholder tidak kompeten\",\"D\":\"Menunggu sampai ada dokumen spesifikasi lengkap setebal 100 halaman\"}', 'A', 'A', 1, 'Menerjemahkan ide abstrak menjadi kriteria terukur dan prototipe visual adalah peran kunci perekayasa perangkat lunak.', '2026-09-30 11:08:25', '2026-09-30 11:09:34'),
(148, 10, 'Pada antarmuka input pencarian real-time (auto-complete), teknik apa yang digunakan untuk menunda eksekusi pemanggilan API hingga pengguna berhenti mengetik selama durasi tertentu?', 'hard_skill', 'Frontend Optimization', '{\"A\":\"Debouncing\",\"B\":\"Throttling\",\"C\":\"Server Polling\",\"D\":\"CSS Keyframe Animation\"}', 'A', 'D', 0, 'Debounce me-reset timer setiap kali karakter baru diketik, sehingga request API hanya dikirim saat pengguna jeda sejenak.', '2026-09-30 11:08:25', '2026-09-30 11:09:34'),
(149, 10, 'Ketika melakukan Code Review pada pull request rekan satu tim, Anda menemukan pendekatan kode yang berbeda dengan gaya Anda namun tetap benar dan efisien. Tindakan terbaik Anda adalah:', 'soft_skill', 'Kolaborasi & Code Review', '{\"A\":\"Menyetujui PR jika memenuhi standar arsitektur tim dan uji unit lulus, sambil memberikan saran konstruktif opsional\",\"B\":\"Menolak PR dan memaksakan gaya koding pribadi Anda\",\"C\":\"Mengabaikan PR tersebut tanpa memberikan review selama berhari-hari\",\"D\":\"Mengubah kode rekan kerja secara sepihak tanpa izin\"}', 'A', 'A', 1, 'Code review berfokus pada kualitas, kebenaran, dan keterbacaan kode tim, bukan preferensi gaya personal penguji.', '2026-09-30 11:08:25', '2026-09-30 11:09:34'),
(150, 10, 'Dalam arsitektur RESTful API modern, metode HTTP manakah yang bersifat idempoten (idempotent) dan digunakan untuk memperbarui seluruh representasi sumber daya (resource)?', 'hard_skill', 'RESTful API Architecture', '{\"A\":\"PUT\",\"B\":\"POST\",\"C\":\"PATCH\",\"D\":\"DELETE\"}', 'A', 'D', 0, 'PUT bersifat idempoten karena pemanggilan berulang kali dengan payload yang sama akan menghasilkan status akhir sumber daya yang identik.', '2026-09-30 11:08:25', '2026-09-30 11:09:34'),
(151, 10, 'Pada sistem operasi Linux server, perintah baris apa yang paling cepat digunakan untuk memantau proses mana yang paling banyak memakan CPU dan memori secara interaktif?', 'hard_skill', 'Linux & Server Administration', '{\"A\":\"top atau htop\",\"B\":\"ls -la\",\"C\":\"chmod 777\",\"D\":\"ping localhost\"}', 'A', 'D', 0, 'Perintah top/htop menampilkan task manager interaktif di terminal dengan urutan penggunaan CPU dan RAM terkini.', '2026-09-30 11:08:25', '2026-09-30 11:09:34'),
(152, 10, 'Pada protokol HTTPS, bagaimana proses pertukaran kunci enkripsi terjadi saat proses TLS Handshake awal?', 'hard_skill', 'Jaringan & Kriptografi', '{\"A\":\"Menggunakan kriptografi asimetris (Public\\/Private Key) untuk menyepakati Symmetric Session Key yang efisien\",\"B\":\"Mengirimkan password database secara plaintext\",\"C\":\"Hanya menggunakan algoritma hashing MD5 satu arah\",\"D\":\"Mengabaikan sertifikat SSL jika domain tidak cocok\"}', 'A', 'A', 1, 'TLS menggunakan asimetris untuk autentikasi dan negosiasi kunci, kemudian menggunakan simetris untuk enkripsi data berkecepatan tinggi.', '2026-09-30 11:08:25', '2026-09-30 11:09:34'),
(153, 10, 'Seorang anggota tim junior tampak kesulitan dan frustrasi menyelesaikan tugas modul autentikasi selama 2 hari berturut-turut. Sikap empati teknis apa yang harus ditunjukkan?', 'soft_skill', 'Mentoring & Kerjasama Tim', '{\"A\":\"Mengajak berdiskusi santai, melakukan sesi pair-programming untuk memecah masalah menjadi sub-tugas yang lebih kecil, dan memberi bimbingan\",\"B\":\"Mengambil alih tugasnya secara diam-diam tanpa menjelaskan apapun\",\"C\":\"Memarahi junior tersebut di depan seluruh anggota tim saat stand-up meeting\",\"D\":\"Membiarkannya sampai deadline lewat agar dia belajar sendiri\"}', 'A', 'A', 1, 'Pair-programming dan bimbingan memecah hambatan teknis sekaligus mempercepat transfer pengetahuan dalam tim.', '2026-09-30 11:08:25', '2026-09-30 11:09:34'),
(154, 10, 'Manakah langkah proteksi paling mendasar dan efektif untuk mencegah kerentanan SQL Injection pada aplikasi web?', 'hard_skill', 'Keamanan Perangkat Lunak', '{\"A\":\"Menggunakan Parameterized Queries atau Prepared Statements yang memisahkan instruksi SQL dari data masukan pengguna\",\"B\":\"Menyimpan data password menggunakan enkripsi Base64\",\"C\":\"Mengubah port default web server dari port 80 menjadi port 8080\",\"D\":\"Menonaktifkan firewall pada server database\"}', 'A', 'A', 1, 'Prepared statements memastikan parameter input diperlakukan murni sebagai data literal, bukan sebagai kode SQL executable.', '2026-09-30 11:08:25', '2026-09-30 11:09:34');
INSERT INTO `assessment_questions` (`id`, `assessment_id`, `question_text`, `type`, `topic`, `options`, `correct_option`, `user_answer`, `is_correct`, `explanation`, `created_at`, `updated_at`) VALUES
(155, 11, 'Struktur standar JSON Web Token (JWT) terdiri dari tiga bagian yang dipisahkan tanda titik (.):', 'hard_skill', 'Autentikasi & Otorisasi Modern', '{\"A\":\"Header.Payload.Signature\",\"B\":\"User.Password.Token\",\"C\":\"Protocol.Domain.Port\",\"D\":\"Encryption.Salt.Hash\"}', 'A', 'A', 1, 'Header berisi tipe token dan algoritma enkripsi, Payload berisi klaim data, dan Signature memverifikasi keaslian token.', '2026-10-05 06:25:23', '2026-10-05 06:26:43'),
(156, 11, 'Anda menemukan bug kritis di server production tepat 30 menit sebelum jam peluncuran sistem. Sikap profesional rekayasa apa yang paling tepat dilakukan?', 'soft_skill', 'Problem Solving & Insiden Kerja', '{\"A\":\"Mengomunikasikan temuan ke tim\\/stakeholder secara transparan, menganalisis risiko, dan menerapkan hotfix teruji atau menunda peluncuran secara aman\",\"B\":\"Mengabaikan bug tersebut dengan harapan tidak ditemukan oleh pengguna\",\"C\":\"Menyalahkan rekan tim yang menulis modul tersebut di grup publik\",\"D\":\"Melakukan perubahan langsung di server live tanpa membuat cadangan kode dan database\"}', 'A', 'A', 1, 'Integritas teknis dan komunikasi risiko secara objektif merupakan soft-skill paling berharga bagi seorang profesional engineering.', '2026-10-05 06:25:23', '2026-10-05 06:26:43'),
(157, 11, 'Ketika query laporan tracer study pada basis data MySQL yang memiliki 500.000 baris data terasa lambat, optimasi indeks apa yang paling tepat dipasang?', 'hard_skill', 'Database Indexing & Optimization', '{\"A\":\"Menambahkan B-Tree Index pada kolom yang sering digunakan di klausa WHERE dan JOIN\",\"B\":\"Menghapus primary key pada tabel\",\"C\":\"Mengubah semua tipe data VARCHAR menjadi TEXT\",\"D\":\"Melakukan query SELECT * tanpa klausa limit\"}', 'A', 'A', 1, 'Index B-Tree mempercepat pencarian data dari kompleksitas O(N) full table scan menjadi O(log N).', '2026-10-05 06:25:23', '2026-10-05 06:26:43'),
(158, 11, 'Teknik apa yang digunakan oleh web browser untuk mempercepat metrik LCP (Largest Contentful Paint) pada halaman web yang memiliki banyak gambar besar?', 'hard_skill', 'Web Performance & Core Web Vitals', '{\"A\":\"Implementasi Lazy Loading (loading=\\\"lazy\\\"), format WebP\\/AVIF modern, dan CDN aset statis\",\"B\":\"Mengubah gambar menjadi file audio\",\"C\":\"Menghapus file CSS styling utama\",\"D\":\"Menjalankan loop JavaScript untuk mengunduh semua gambar bersamaan di thread utama\"}', 'A', 'A', 1, 'Lazy loading menunda download gambar off-screen hingga pengguna menggulir mendekati viewport, membebaskan bandwidth.', '2026-10-05 06:25:23', '2026-10-05 06:26:43'),
(159, 11, 'Tim backend perlu merilis pembaruan endpoint API yang mengubah format payload response secara signifikan (breaking change). Apa langkah profesional terbaik sebelum perubahan di-deploy?', 'soft_skill', 'Manajemen Rilis & Kolaborasi', '{\"A\":\"Membuat API versioning baru (misal \\/api\\/v2), mengomunikasikan timeline deprecation ke tim mobile\\/frontend, dan menjaga v1 tetap berjalan sementara\",\"B\":\"Langsung mengubah endpoint v1 di production tanpa pemberitahuan apapun\",\"C\":\"Mematikan server mobile secara tiba-tiba agar mereka sadar ada pembaruan\",\"D\":\"Menolak melakukan pembaruan selamanya demi kompatibilitas lama\"}', 'A', 'A', 1, 'Versioning API dan komunikasi transparan melindungi integrasi klien dari kegagalan fungsional yang fatal.', '2026-10-05 06:25:23', '2026-10-05 06:26:43'),
(160, 11, 'Manakah langkah proteksi paling mendasar dan efektif untuk mencegah kerentanan SQL Injection pada aplikasi web?', 'hard_skill', 'Keamanan Perangkat Lunak', '{\"A\":\"Menggunakan Parameterized Queries atau Prepared Statements yang memisahkan instruksi SQL dari data masukan pengguna\",\"B\":\"Menyimpan data password menggunakan enkripsi Base64\",\"C\":\"Mengubah port default web server dari port 80 menjadi port 8080\",\"D\":\"Menonaktifkan firewall pada server database\"}', 'A', 'A', 1, 'Prepared statements memastikan parameter input diperlakukan murni sebagai data literal, bukan sebagai kode SQL executable.', '2026-10-05 06:25:23', '2026-10-05 06:26:43'),
(161, 11, 'Seorang stakeholder non-teknis memberikan kebutuhan aplikasi yang sangat samar: \"Buat sistem yang pintar dan otomatis\". Langkah konkret apa yang harus Anda ambil?', 'soft_skill', 'Komunikasi Kebutuhan Bisnis', '{\"A\":\"Mengajak stakeholder berdiskusi dengan membuat alur use case sederhana, kriteria keberhasilan yang terukur, dan wireframe interaktif\",\"B\":\"Langsung menulis kode rumit berdasarkan asumsi sendiri tanpa konfirmasi\",\"C\":\"Menolak proyek dan mengatakan stakeholder tidak kompeten\",\"D\":\"Menunggu sampai ada dokumen spesifikasi lengkap setebal 100 halaman\"}', 'A', 'A', 1, 'Menerjemahkan ide abstrak menjadi kriteria terukur dan prototipe visual adalah peran kunci perekayasa perangkat lunak.', '2026-10-05 06:25:23', '2026-10-05 06:26:43'),
(162, 11, 'Seorang anggota tim junior tampak kesulitan dan frustrasi menyelesaikan tugas modul autentikasi selama 2 hari berturut-turut. Sikap empati teknis apa yang harus ditunjukkan?', 'soft_skill', 'Mentoring & Kerjasama Tim', '{\"A\":\"Mengajak berdiskusi santai, melakukan sesi pair-programming untuk memecah masalah menjadi sub-tugas yang lebih kecil, dan memberi bimbingan\",\"B\":\"Mengambil alih tugasnya secara diam-diam tanpa menjelaskan apapun\",\"C\":\"Memarahi junior tersebut di depan seluruh anggota tim saat stand-up meeting\",\"D\":\"Membiarkannya sampai deadline lewat agar dia belajar sendiri\"}', 'A', 'A', 1, 'Pair-programming dan bimbingan memecah hambatan teknis sekaligus mempercepat transfer pengetahuan dalam tim.', '2026-10-05 06:25:23', '2026-10-05 06:26:43'),
(163, 11, 'Klien meminta penambahan 3 fitur kompleks baru di tengah sprint yang sudah berjalan dengan batas waktu deadline yang tidak bisa diundur. Bagaimana respons terbaik Anda?', 'soft_skill', 'Manajemen Ekspektasi & Agile', '{\"A\":\"Mendiskusikan trade-off secara profesional, menetapkan prioritas fitur MVP, dan memindahkan fitur tambahan ke sprint berikutnya\",\"B\":\"Langsung mengiyakan semua permintaan meskipun tahu tim tidak akan sanggup menyelesaikannya\",\"C\":\"Memutus kontak dengan klien dan tidak masuk kerja\",\"D\":\"Menghapus pengujian unit dan standar keamanan demi mengejar waktu\"}', 'A', 'A', 1, 'Pengembang profesional mengelola ruang lingkup secara transparan dengan fokus pada nilai bisnis dan viabilitas teknis.', '2026-10-05 06:25:23', '2026-10-05 06:26:43'),
(164, 11, 'Dalam arsitektur RESTful API modern, metode HTTP manakah yang bersifat idempoten (idempotent) dan digunakan untuk memperbarui seluruh representasi sumber daya (resource)?', 'hard_skill', 'RESTful API Architecture', '{\"A\":\"PUT\",\"B\":\"POST\",\"C\":\"PATCH\",\"D\":\"DELETE\"}', 'A', 'B', 0, 'PUT bersifat idempoten karena pemanggilan berulang kali dengan payload yang sama akan menghasilkan status akhir sumber daya yang identik.', '2026-10-05 06:25:23', '2026-10-05 06:26:43'),
(165, 11, 'Setelah insiden downtime sistem berhasil dipulihkan, tim mengadakan rapat \"Blameless Post-Mortem\". Apa tujuan utama dari rapat ini?', 'soft_skill', 'Budaya Teknik & Retrospektif', '{\"A\":\"Mengidentifikasi akar penyebab sistemik (Root Cause) dan merancang mitigasi pencegahan agar insiden serupa tidak terulang\",\"B\":\"Mencari satu orang untuk dijatuhi sanksi dan disalahkan atas insiden\",\"C\":\"Menghapus log error agar reputasi tim tidak terlihat buruk\",\"D\":\"Memperdebatkan siapa yang paling berjasa memulihkan sistem\"}', 'A', 'A', 1, 'Blameless post-mortem mengasumsikan kesalahan terjadi akibat kelemahan sistem dan prosedur, bukan kelalaian jahat individu.', '2026-10-05 06:25:23', '2026-10-05 06:26:44'),
(166, 11, 'Untuk mencegah serangan Cross-Site Scripting (Stored XSS) pada kolom komentar pengguna, mekanisme apa yang wajib diimplementasikan sebelum merender konten ke browser?', 'hard_skill', 'Keamanan Web (OWASP)', '{\"A\":\"HTML Entity Encoding \\/ Sanitasi output sehingga tag seperti <script> tidak dieksekusi browser\",\"B\":\"Mengharuskan pengguna mengunggah file zip\",\"C\":\"Menggunakan protokol HTTP\\/2\",\"D\":\"Menghapus session cookie setelah 5 detik\"}', 'A', 'A', 1, 'Encoding mengonversi karakter berbahaya seperti < dan > menjadi &lt; dan &gt; sehingga browser merendernya sebagai teks biasa.', '2026-10-05 06:25:23', '2026-10-05 06:26:44'),
(167, 11, 'Laporan audit keamanan menemukan celah kerentanan kritis kategori High pada dependensi pihak ketiga yang digunakan sistem Anda. Tindakan prioritas tim adalah:', 'soft_skill', 'Manajemen Risiko Keamanan', '{\"A\":\"Mengevaluasi dampak, memperbarui package ke versi patch terbaru di staging, menjalankan automated test suite, dan segera rilis patch ke production\",\"B\":\"Menunda penanganan celah keamanan selama 6 bulan sampai roadmap fitur selesai\",\"C\":\"Menghapus modul keamanan dari sistem agar audit tidak mendeteksi celah lagi\",\"D\":\"Menganggap celah keamanan hanya teori dan tidak mungkin diserang hacker nyata\"}', 'A', 'A', 1, 'Kerentanan kritis pada dependensi harus dimitigasi segera dengan proses verifikasi regresi yang terukur.', '2026-10-05 06:25:23', '2026-10-05 06:26:44'),
(168, 11, 'Dalam prinsip transaksi ACID pada basis data relasional, apa yang dimaksud dengan sifat \"Atomicity\"?', 'hard_skill', 'Database Transaction (ACID)', '{\"A\":\"Semua operasi dalam satu transaksi harus berhasil sepenuhnya, jika satu gagal maka seluruh transaksi dibatalkan (Rollback)\",\"B\":\"Data disimpan dalam partisi atomik memori cache RAM\",\"C\":\"Setiap tabel harus memiliki minimal 10 indeks kolom\",\"D\":\"Database tidak boleh diakses oleh lebih dari satu pengguna dalam satu detik\"}', 'A', 'A', 1, 'Atomicity menjamin prinsip \"all or nothing\", mencegah inkonsistensi data parsial saat terjadi gangguan server.', '2026-10-05 06:25:23', '2026-10-05 06:26:44'),
(169, 11, 'Ketika melakukan Code Review pada pull request rekan satu tim, Anda menemukan pendekatan kode yang berbeda dengan gaya Anda namun tetap benar dan efisien. Tindakan terbaik Anda adalah:', 'soft_skill', 'Kolaborasi & Code Review', '{\"A\":\"Menyetujui PR jika memenuhi standar arsitektur tim dan uji unit lulus, sambil memberikan saran konstruktif opsional\",\"B\":\"Menolak PR dan memaksakan gaya koding pribadi Anda\",\"C\":\"Mengabaikan PR tersebut tanpa memberikan review selama berhari-hari\",\"D\":\"Mengubah kode rekan kerja secara sepihak tanpa izin\"}', 'A', 'A', 1, 'Code review berfokus pada kualitas, kebenaran, dan keterbacaan kode tim, bukan preferensi gaya personal penguji.', '2026-10-05 06:25:23', '2026-10-05 06:26:44'),
(170, 11, 'Dalam prinsip SOLID, prinsip \"Dependency Inversion Principle\" (DIP) menyatakan bahwa:', 'hard_skill', 'Clean Code & Desain Perangkat Lunak', '{\"A\":\"Modul tingkat tinggi tidak boleh bergantung pada modul tingkat rendah; keduanya harus bergantung pada abstraksi (interface)\",\"B\":\"Semua fungsi harus ditulis dalam satu file class besar\",\"C\":\"Variabel harus dideklarasikan terbalik dari urutan eksekusi\",\"D\":\"Database tidak boleh memiliki relasi tabel antar entitas\"}', 'A', 'A', 1, 'DIP memisahkan implementasi konkret melalui interface sehingga kode mudah diuji (mocking) dan fleksibel diubah.', '2026-10-05 06:25:23', '2026-10-05 06:26:44'),
(171, 11, 'Ketika aplikasi web mengalami lonjakan pengiriman email konfirmasi (10.000 email sekaligus), arsitektur apa yang paling tepat digunakan agar antarmuka pengguna tidak macet (non-blocking)?', 'hard_skill', 'Message Broker & Asynchronous Queue', '{\"A\":\"Asynchronous Message Queue (misal: Redis Queue \\/ RabbitMQ) yang diproses oleh background worker\",\"B\":\"Menjalankan loop pengiriman email di controller utama request HTTP\",\"C\":\"Meminta pengguna untuk menunggu loading browser selama 15 menit\",\"D\":\"Mengubah ukuran RAM komputer klien\"}', 'A', 'A', 1, 'Queue menyimpan tugas di antrean pesan dan langsung mengembalikan respon HTTP ke pengguna dalam hitungan milidetik.', '2026-10-05 06:25:23', '2026-10-05 06:26:44'),
(172, 11, 'Pada arsitektur sistem berbasis Microservices, pola arsitektur apa yang digunakan untuk mencegah kegagalan satu service merambat (cascading failure) ke seluruh ekosistem aplikasi?', 'hard_skill', 'Arsitektur Microservices', '{\"A\":\"Circuit Breaker Pattern\",\"B\":\"Singleton Pattern\",\"C\":\"Monolithic Model\",\"D\":\"Direct Synchronous Loop\"}', 'A', 'D', 0, 'Circuit Breaker memutus panggilan sementara ke service yang sedang down/timeout dan memberikan fallback response instan.', '2026-10-05 06:25:23', '2026-10-05 06:26:44'),
(173, 11, 'Dalam arsitektur container Docker, apa fungsi utama dari file Dockerfile dalam siklus deployment aplikasi web?', 'hard_skill', 'DevOps & Containerization', '{\"A\":\"Berisi instruksi deklaratif untuk membangun Image aplikasi yang terisolasi dan konsisten di berbagai lingkungan\",\"B\":\"Menyimpan password database production secara plaintext\",\"C\":\"Menggantikan fungsi web server Nginx dan Apache\",\"D\":\"Sebagai pengganti compiler bahasa pemrograman\"}', 'A', 'A', 1, 'Dockerfile mendefinisikan layer sistem operasi dasar, dependensi library, dan konfigurasi runtime untuk menghasilkan Docker Image.', '2026-10-05 06:25:23', '2026-10-05 06:26:44'),
(174, 11, 'Bagaimana strategi tim developer dalam mengelola \"Technical Debt\" (utang teknis) agar aplikasi tetap scalable dalam jangka panjang?', 'soft_skill', 'Manajemen Utang Teknis', '{\"A\":\"Mendokumentasikan technical debt di backlog dan mengalokasikan persentase kapasitas tertentu di tiap sprint untuk refactoring\",\"B\":\"Tidak pernah melakukan refactoring sampai aplikasi benar-benar crash\",\"C\":\"Menulis ulang seluruh aplikasi dari nol setiap kali ada teknologi framework baru\",\"D\":\"Menyembunyikan kode yang berantakan dengan mengabaikan peringatan linter\"}', 'A', 'A', 1, 'Mengalokasikan kapasitas berkala (misal 15-20% per sprint) menjaga keseimbangan antara rilis fitur dan kesehatan basis kode.', '2026-10-05 06:25:23', '2026-10-05 06:26:44'),
(175, 12, 'Ketika proyek IoT kelompok Anda mengalami kegagalan transmisi data ke MQTT broker di industri saat pengujian lapangan, langkah investigasi awal apa yang paling bijak dan terstruktur?', 'soft_skill', 'Troubleshooting Lapangan', '{\"A\":\"Memeriksa konektivitas jaringan dasar (ping\\/gateway) dan serial monitor log perangkat secara terisolasi\",\"B\":\"Langsung mengganti seluruh mikrokontroler dengan modul yang baru\",\"C\":\"Menghapus seluruh baris kode firmware dan mulai menulis dari awal\",\"D\":\"Menyalahkan tim penyedia server cloud sebelum memeriksa log lokal\"}', 'A', 'A', 1, 'Troubleshooting rekayasa yang profesional selalu mengisolasi variabel masalah dari lapisan paling bawah (koneksi fisik/jaringan) menggunakan log.', '2026-10-05 07:34:34', '2026-10-05 07:35:54'),
(176, 12, 'Saat merakit prototipe papan sirkuit baru di laboratorium, tim mendapati salah satu IC regulator mengeluarkan asap akibat polaritas catu daya terbalik. Sikap kerja standar apa yang harus diambil?', 'soft_skill', 'Keselamatan Kerja & Prosedur Lab', '{\"A\":\"Segera putuskan sumber daya listrik, evaluasi kerusakan, periksa skema proteksi polaritas terbalik, dan catat temuan untuk revisi PCB\",\"B\":\"Menyiram papan sirkuit dengan air saat masih terhubung ke listrik PLN\",\"C\":\"Menyembunyikan komponen yang terbakar dan pura-pura tidak tahu\",\"D\":\"Terus menaikkan voltase daya untuk melihat apa yang akan terjadi selanjutnya\"}', 'A', 'A', 1, 'Keselamatan laboratorium menuntut pemutusan daya segera, identifikasi akar masalah (menambahkan dioda reverse polarity), dan dokumentasi insiden.', '2026-10-05 07:34:34', '2026-10-05 07:35:54'),
(177, 12, 'Fitur perangkat keras mikrokontroler apa yang bertindak sebagai \"penjaga\" untuk melakukan reset otomatis jika firmware mengalami loop tak berujung (hang/freeze)?', 'hard_skill', 'Keandalan Sistem Tertanam', '{\"A\":\"Watchdog Timer (WDT)\",\"B\":\"Real-Time Clock (RTC)\",\"C\":\"Baud Rate Generator\",\"D\":\"Direct Memory Access (DMA)\"}', 'A', 'A', 1, 'Firmware harus secara periodik \"memberi makan\" (refresh) WDT; jika firmware macet dan timer overflow, WDT mereset mikrokontroler ke kondisi awal.', '2026-10-05 07:34:34', '2026-10-05 07:35:54'),
(178, 12, 'Berdasarkan Teorema Sampling Nyquist-Shannon, jika suatu sinyal analog memiliki frekuensi maksimum sebesar 5 kHz, berapa laju pencuplikan (sampling rate) minimum ADC agar tidak terjadi aliasing?', 'hard_skill', 'Pemrosesan Sinyal & ADC', '{\"A\":\"10 kHz (dua kali frekuensi tertinggi sinyal)\",\"B\":\"5 kHz (sama persis dengan frekuensi tertinggi)\",\"C\":\"2.5 kHz (setengah dari frekuensi tertinggi)\",\"D\":\"100 kHz secara mutlak\"}', 'A', 'A', 1, 'Teorema Nyquist mensyaratkan fs >= 2 * fmax agar bentuk gelombang analog asli dapat direkonstruksi secara sempurna.', '2026-10-05 07:34:34', '2026-10-05 07:35:54'),
(179, 12, 'Pada mikrokontroler ESP32, protokol komunikasi apa yang paling tepat digunakan untuk menghubungkan beberapa sensor suhu dalam satu bus dengan hanya menggunakan dua jalur kabel (SDA dan SCL)?', 'hard_skill', 'Protokol Bus Serial', '{\"A\":\"I2C (Inter-Integrated Circuit)\",\"B\":\"SPI (Serial Peripheral Interface)\",\"C\":\"UART (Universal Asynchronous Receiver-Transmitter)\",\"D\":\"Modbus RTU\"}', 'A', 'C', 0, 'I2C hanya memerlukan 2 jalur kabel (SDA untuk data dan SCL untuk clock) dan mendukung multi-device dengan sistem addressing.', '2026-10-05 07:34:34', '2026-10-05 07:35:54'),
(180, 12, 'Dalam perancangan catu daya sistem elektronika, apa keunggulan utama regulator switching tipe Buck Converter dibandingkan regulator linier seri LM7805 saat menurunkan tegangan dari 24V DC ke 5V DC?', 'hard_skill', 'Elektronika Daya & Regulator', '{\"A\":\"Efisiensi konversi daya sangat tinggi (85-95%) sehingga disipasi panas minimal tanpa perlu pendingin besar\",\"B\":\"Buck converter menghasilkan biaya komponen yang selalu lebih murah\",\"C\":\"Buck converter sama sekali tidak menghasilkan noise switching\",\"D\":\"Buck converter hanya bisa digunakan untuk arus di bawah 1 miliampere\"}', 'A', 'A', 1, 'Regulator linier mendisipasikan kelebihan tegangan (24V - 5V = 19V) sebagai panas murni, sementara buck converter bekerja dengan efisiensi tinggi.', '2026-10-05 07:34:34', '2026-10-05 07:35:54'),
(181, 12, 'Klien menginginkan perangkat pelacak hewan ternak berbasis baterai koin kecil dapat menyala selama 5 tahun terus-menerus sambil mengirim data GPS setiap 1 detik. Bagaimana cara menjelaskan realitas teknis kepadanya?', 'soft_skill', 'Manajemen Ekspektasi Klien', '{\"A\":\"Menyajikan lembar kalkulasi power budget (kapasitas baterai mAh vs konsumsi arus modul GPS\\/transmisi) dan menawarkan kompromi duty cycle interval transmisi\",\"B\":\"Menyetujui permintaan klien dan berjanji palsu alat akan tahan 5 tahun\",\"C\":\"Mengatakan klien bodoh karena tidak mengerti hukum fisika\",\"D\":\"Membeli baterai biasa dan menempelkan stiker \\\"Baterai 5 Tahun\\\"\"}', 'A', 'A', 1, 'Edukasi klien dengan kalkulasi ilmiah dan penawaran opsi kompromi (misal: deep sleep dengan transmisi tiap 30 menit) adalah tanda profesionalisme.', '2026-10-05 07:34:34', '2026-10-05 07:35:54'),
(182, 12, 'Pada desain tata letak PCB (Printed Circuit Board), di manakah posisi terbaik untuk meletakkan kapasitor decoupling (bypass capacitor 0.1 uF)?', 'hard_skill', 'Desain PCB & Integritas Sinyal', '{\"A\":\"Sedekat mungkin dengan pin VCC dan GND dari IC\\/mikrokontroler yang bersangkutan\",\"B\":\"Di sudut paling luar dari papan PCB jauh dari IC\",\"C\":\"Dipasang seri dengan jalur antena RF\",\"D\":\"Di bawah konektor baterai\"}', 'A', 'A', 1, 'Menempatkan kapasitor sedekat mungkin meminimalkan induktansi parasitik jalur tembaga, meredam ripple tegangan transien berkecepatan tinggi.', '2026-10-05 07:34:34', '2026-10-05 07:35:54'),
(183, 12, 'Pada ladder diagram PLC, apa perbedaan mendasar antara instruksi Timer On-Delay (TON) dan Timer Off-Delay (TOF)?', 'hard_skill', 'Pemrograman PLC Industri', '{\"A\":\"TON menunda aktifnya output setelah input ON, sedangkan TOF menunda matinya output setelah input OFF\",\"B\":\"TON hanya bekerja pada tegangan AC sedangkan TOF hanya pada DC\",\"C\":\"TON menghitung waktu mundur sedangkan TOF menghitung waktu maju\",\"D\":\"TON tidak memerlukan variabel preset time\"}', 'A', 'A', 1, 'TON menghitung durasi tunda sebelum menyalakan beban; TOF menjaga beban tetap menyala selama durasi tertentu setelah sinyal pemicu hilang.', '2026-10-05 07:34:34', '2026-10-05 07:35:54'),
(184, 12, 'Saat memprogram mikrokontroler dengan FreeRTOS, kondisi apa yang terjadi ketika dua buah Task saling menunggu resource yang sedang dikunci oleh satu sama lain sehingga sistem berhenti merespons?', 'hard_skill', 'RTOS & Embedded Systems', '{\"A\":\"Deadlock\",\"B\":\"Priority Inversion\",\"C\":\"Stack Overflow\",\"D\":\"Memory Leakage\"}', 'A', 'D', 0, 'Deadlock terjadi saat Task A memegang Resource 1 dan menunggu Resource 2, sedangkan Task B memegang Resource 2 dan menunggu Resource 1.', '2026-10-05 07:34:34', '2026-10-05 07:35:54'),
(185, 12, 'Sebuah tim teknisi pemula kesulitan melakukan flashing firmware baru ke perangkat PLC dan modul IoT di pabrik cabang. Cara terbaik membimbing mereka dari kantor pusat adalah:', 'soft_skill', 'Knowledge Transfer & Dokumentasi', '{\"A\":\"Menyediakan panduan visual SOP langkah demi langkah (Standard Operating Procedure), video demonstrasi, dan mengadakan sesi remote support\",\"B\":\"Menyuruh mereka membaca manual teknis 500 halaman dalam bahasa asing tanpa bimbingan\",\"C\":\"Mengatakan bahwa mereka tidak kompeten sebagai teknisi\",\"D\":\"Menghapus hak akses teknisi tersebut dari sistem\"}', 'A', 'A', 1, 'Transfer keahlian yang terstruktur dengan media panduan visual dan pendampingan memperkuat kemandirian operasional tim lapangan.', '2026-10-05 07:34:34', '2026-10-05 07:35:54'),
(186, 12, 'Teknisi lapangan melaporkan bahwa sensor getaran mesin motor industri sering mengirim data yang tidak menentu. Operator menuduh firmware yang bermasalah, sementara programmer menduga sensor kendor. Solusi kolaboratif terbaik adalah:', 'soft_skill', 'Komunikasi & Diagnosa Lapangan', '{\"A\":\"Bersama-sama ke lapangan, mengukur sinyal sensor dengan instrumen osiloskop portabel, memverifikasi mounting fisik, dan membaca raw data serial\",\"B\":\"Saling berdebat di grup chat tanpa ada yang memeriksa kondisi fisik mesin di pabrik\",\"C\":\"Mematikan fitur alarm sensor agar tidak ada laporan gangguan lagi\",\"D\":\"Menyerahkan masalah kepada divisi keuangan perusahaan\"}', 'A', 'A', 1, 'Verifikasi berbasis data riil dan pengukuran instrumen langsung di lapangan memotong spekulasi dan mempercepat penyelesaian akar masalah.', '2026-10-05 07:34:34', '2026-10-05 07:35:54'),
(187, 12, 'Di tengah proses produksi massal perangkat otomasi, pabrik komponen mengumumkan bahwa chip mikrokontroler utama discontinue (EOL). Bagaimana keputusan rekayasa terbaik tim?', 'soft_skill', 'Manajemen Rantai Pasok Hardware', '{\"A\":\"Mencari chip alternatif pin-to-pin compatible atau merancang ulang layout PCB minimal dengan chip yang memiliki ketersediaan pasokan jangka panjang\",\"B\":\"Menghentikan seluruh bisnis perusahaan dan membatalkan pesanan klien secara permanen\",\"C\":\"Membeli komponen bekas rusak dari sumber tidak jelas tanpa verifikasi datasheet\",\"D\":\"Mengabaikan kabar tersebut dan berharap pabrik membuat pengecualian\"}', 'A', 'A', 1, 'Ketahanan desain perangkat keras dinilai dari kemampuan rekayasawan beradaptasi terhadap ketersediaan komponen rantai pasok global.', '2026-10-05 07:34:34', '2026-10-05 07:35:54'),
(188, 12, 'Dalam proyek kolaborasi pembuatan alat IoT, terjadi ketidakcocokan antara hardware engineer dan firmware engineer terkait pin GPIO yang digunakan. Bagaimana cara pencegahan terbaik di masa depan?', 'soft_skill', 'Standardisasi Rekayasa Perangkat Keras', '{\"A\":\"Menyepakati dan membekukan dokumen \\\"Hardware Pinout Map & Register Specification\\\" sebelum pembuatan layout PCB dan penulisan kode dimulai\",\"B\":\"Melarang programmer dan hardware engineer saling berbicara satu sama lain\",\"C\":\"Hanya mempercayai ingatan lisan tanpa membuat dokumentasi tertulis\",\"D\":\"Menyerahkan pemilihan pin secara acak setiap hari\"}', 'A', 'A', 1, 'Dokumen spesifikasi pinout antarmuka adalah kontrak resmi antara tim perancang skematik dan pengembang firmware.', '2026-10-05 07:34:34', '2026-10-05 07:35:54'),
(189, 12, 'Setelah terjadi insiden konveyor otomatis pabrik berhenti mendadak akibat sensor photo-electric tertutup debu tebal, rekomendasi preventif menyeluruh apa yang perlu diberikan ke manajemen pabrik?', 'soft_skill', 'Pemeliharaan Preventif & SOP', '{\"A\":\"Menetapkan jadwal rutin pembersihan sensor pada checklist harian operator dan menambahkan sensor redundan dengan logika peringatan dini degradasi sinyal\",\"B\":\"Melepas semua sensor keselamatan dan mengoperasikan mesin secara manual dengan risiko tinggi\",\"C\":\"Menyalahkan debu pabrik dan menuntut agar seluruh pabrik beroperasi tanpa debu sama sekali\",\"D\":\"Tidak melakukan apapun karena mesin sudah berjalan normal kembali\"}', 'A', 'A', 1, 'Pencegahan jangka panjang melibatkan pemeliharaan preventif berjadwal serta perancangan sistem peringatan dini (predictive maintenance).', '2026-10-05 07:34:34', '2026-10-05 07:35:54'),
(190, 12, 'Pada sistem otomasi industri berbasis PLC (Programmable Logic Controller), instruksi Ladder Diagram apa yang digunakan untuk mengunci output agar tetap aktif meskipun tombol push-button start telah dilepas?', 'hard_skill', 'Logika PLC & Otomasi', '{\"A\":\"Rangkaian Latching (Self-Holding Contact)\",\"B\":\"Timer On-Delay (TON)\",\"C\":\"Counter Up (CTU)\",\"D\":\"Comparator EQU\"}', 'A', 'A', 1, 'Latching memasang kontak normally-open milik coil output secara paralel dengan tombol start untuk menjaga loop sinyal tetap tertutup.', '2026-10-05 07:34:34', '2026-10-05 07:35:54'),
(191, 12, 'Anda melihat rekan teknisi hendak mengukur terminal listrik 380V pada panel distribusi tanpa menggunakan sarung tangan isolasi dan kacamata pelindung. Tindakan Anda adalah:', 'soft_skill', 'K3 & Keselamatan Kelistrikan', '{\"A\":\"Segera menegur dan menghentikannya secara tegas, mengingatkan bahaya busur api (Arc Flash), dan memastikan APD lengkap terpasang\",\"B\":\"Membiarkannya karena merasa itu bukan urusan pribadi Anda\",\"C\":\"Merekam videonya untuk dijadikan lelucon di media sosial\",\"D\":\"Ikut-ikutan mengukur tanpa APD agar dinilai pemberani\"}', 'A', 'A', 1, 'Intervensi keselamatan kerja (K3) adalah kewajiban mutlak setiap individu demi melindungi keselamatan nyawa tim di area bertegangan tinggi.', '2026-10-05 07:34:34', '2026-10-05 07:35:54'),
(192, 12, 'Dalam sistem elektronika otomotif dan robotika canggih, bus komunikasi CAN (Controller Area Network) menggunakan mekanisme arbitrase bus berbasis:', 'hard_skill', 'CAN Bus Protocol', '{\"A\":\"Non-Destructive Bitwise Arbitration berbasis Identifier pesan (prioritas ID terkecil selalu menang)\",\"B\":\"Token ring bergantian berurutan\",\"C\":\"Pengundian acak saat tabrakan paket data (CSMA\\/CD)\",\"D\":\"Master tunggal yang mengendalikan seluruh node secara pasif\"}', 'A', 'A', 1, 'Bit dominan (logika 0) menimpa bit resesif (logika 1); node dengan ID bernilai lebih kecil memiliki prioritas tertinggi tanpa kehilangan frame data.', '2026-10-05 07:34:34', '2026-10-05 07:35:54'),
(193, 12, 'Pada jaringan industri pabrik, protokol komunikasi fisik RS-485 dengan standar Modbus RTU sangat populer digunakan karena keunggulannya dalam hal:', 'hard_skill', 'Instrumentasi & Jaringan Industri', '{\"A\":\"Menggunakan sinyal diferensial seimbang (A & B) yang sangat kebal terhadap noise elektromagnetik hingga jarak 1.200 meter\",\"B\":\"Dapat mengirimkan video 4K tanpa kompresi\",\"C\":\"Tidak memerlukan kabel tembaga\",\"D\":\"Beroperasi pada tegangan 10.000 Volt\"}', 'A', 'A', 1, 'Penerima sinyal diferensial mengukur selisih tegangan antara jalur A dan B, membatalkan noise mode bersama (common-mode noise).', '2026-10-05 07:34:34', '2026-10-05 07:35:54'),
(194, 12, 'Ketika mengukur tegangan output dari rangkaian PWM motor DC menggunakan osiloskop, sinyal yang tampak mengalami noise frekuensi tinggi akibat lonjakan induktif motor. Komponen pasif apa yang wajib dipasang sebagai proteksi flyback?', 'hard_skill', 'Rangkaian Proteksi Elektronika', '{\"A\":\"Dioda Penyearah (Freewheeling\\/Flyback Diode) paralel berlawanan arah dengan beban induktif\",\"B\":\"Kapasitor elektrolit seri dengan tegangan supply\",\"C\":\"Resistor pull-up 10k Ohm ke VCC\",\"D\":\"Induktor tambahan pada pin enable\"}', 'A', 'A', 1, 'Flyback diode menyalurkan energi medan magnet yang tersimpan pada kumparan motor saat saklar transistor mati, mencegah lonjakan tegangan balik (Back-EMF).', '2026-10-05 07:34:34', '2026-10-05 07:35:54'),
(195, 13, 'Dalam prinsip transaksi ACID pada basis data relasional, apa yang dimaksud dengan sifat \"Atomicity\"?', 'hard_skill', 'Database Transaction (ACID)', '{\"A\":\"Semua operasi dalam satu transaksi harus berhasil sepenuhnya, jika satu gagal maka seluruh transaksi dibatalkan (Rollback)\",\"B\":\"Data disimpan dalam partisi atomik memori cache RAM\",\"C\":\"Setiap tabel harus memiliki minimal 10 indeks kolom\",\"D\":\"Database tidak boleh diakses oleh lebih dari satu pengguna dalam satu detik\"}', 'A', 'A', 1, 'Atomicity menjamin prinsip \"all or nothing\", mencegah inkonsistensi data parsial saat terjadi gangguan server.', '2026-10-07 10:28:06', '2026-10-07 10:29:13'),
(196, 13, 'Tim backend perlu merilis pembaruan endpoint API yang mengubah format payload response secara signifikan (breaking change). Apa langkah profesional terbaik sebelum perubahan di-deploy?', 'soft_skill', 'Manajemen Rilis & Kolaborasi', '{\"A\":\"Membuat API versioning baru (misal \\/api\\/v2), mengomunikasikan timeline deprecation ke tim mobile\\/frontend, dan menjaga v1 tetap berjalan sementara\",\"B\":\"Langsung mengubah endpoint v1 di production tanpa pemberitahuan apapun\",\"C\":\"Mematikan server mobile secara tiba-tiba agar mereka sadar ada pembaruan\",\"D\":\"Menolak melakukan pembaruan selamanya demi kompatibilitas lama\"}', 'A', 'A', 1, 'Versioning API dan komunikasi transparan melindungi integrasi klien dari kegagalan fungsional yang fatal.', '2026-10-07 10:28:06', '2026-10-07 10:29:13'),
(197, 13, 'Laporan audit keamanan menemukan celah kerentanan kritis kategori High pada dependensi pihak ketiga yang digunakan sistem Anda. Tindakan prioritas tim adalah:', 'soft_skill', 'Manajemen Risiko Keamanan', '{\"A\":\"Mengevaluasi dampak, memperbarui package ke versi patch terbaru di staging, menjalankan automated test suite, dan segera rilis patch ke production\",\"B\":\"Menunda penanganan celah keamanan selama 6 bulan sampai roadmap fitur selesai\",\"C\":\"Menghapus modul keamanan dari sistem agar audit tidak mendeteksi celah lagi\",\"D\":\"Menganggap celah keamanan hanya teori dan tidak mungkin diserang hacker nyata\"}', 'A', 'A', 1, 'Kerentanan kritis pada dependensi harus dimitigasi segera dengan proses verifikasi regresi yang terukur.', '2026-10-07 10:28:06', '2026-10-07 10:29:13'),
(198, 13, 'Dalam prinsip SOLID, prinsip \"Dependency Inversion Principle\" (DIP) menyatakan bahwa:', 'hard_skill', 'Clean Code & Desain Perangkat Lunak', '{\"A\":\"Modul tingkat tinggi tidak boleh bergantung pada modul tingkat rendah; keduanya harus bergantung pada abstraksi (interface)\",\"B\":\"Semua fungsi harus ditulis dalam satu file class besar\",\"C\":\"Variabel harus dideklarasikan terbalik dari urutan eksekusi\",\"D\":\"Database tidak boleh memiliki relasi tabel antar entitas\"}', 'A', 'A', 1, 'DIP memisahkan implementasi konkret melalui interface sehingga kode mudah diuji (mocking) dan fleksibel diubah.', '2026-10-07 10:28:06', '2026-10-07 10:29:13'),
(199, 13, 'Dalam sistem elektronika otomotif dan robotika canggih, bus komunikasi CAN (Controller Area Network) menggunakan mekanisme arbitrase bus berbasis:', 'hard_skill', 'CAN Bus Protocol', '{\"A\":\"Non-Destructive Bitwise Arbitration berbasis Identifier pesan (prioritas ID terkecil selalu menang)\",\"B\":\"Token ring bergantian berurutan\",\"C\":\"Pengundian acak saat tabrakan paket data (CSMA\\/CD)\",\"D\":\"Master tunggal yang mengendalikan seluruh node secara pasif\"}', 'A', 'A', 1, 'Bit dominan (logika 0) menimpa bit resesif (logika 1); node dengan ID bernilai lebih kecil memiliki prioritas tertinggi tanpa kehilangan frame data.', '2026-10-07 10:28:06', '2026-10-07 10:29:13'),
(200, 13, 'Pada ladder diagram PLC, apa perbedaan mendasar antara instruksi Timer On-Delay (TON) dan Timer Off-Delay (TOF)?', 'hard_skill', 'Pemrograman PLC Industri', '{\"A\":\"TON menunda aktifnya output setelah input ON, sedangkan TOF menunda matinya output setelah input OFF\",\"B\":\"TON hanya bekerja pada tegangan AC sedangkan TOF hanya pada DC\",\"C\":\"TON menghitung waktu mundur sedangkan TOF menghitung waktu maju\",\"D\":\"TON tidak memerlukan variabel preset time\"}', 'A', 'A', 1, 'TON menghitung durasi tunda sebelum menyalakan beban; TOF menjaga beban tetap menyala selama durasi tertentu setelah sinyal pemicu hilang.', '2026-10-07 10:28:06', '2026-10-07 10:29:13'),
(201, 13, 'Manakah langkah proteksi paling mendasar dan efektif untuk mencegah kerentanan SQL Injection pada aplikasi web?', 'hard_skill', 'Keamanan Perangkat Lunak', '{\"A\":\"Menggunakan Parameterized Queries atau Prepared Statements yang memisahkan instruksi SQL dari data masukan pengguna\",\"B\":\"Menyimpan data password menggunakan enkripsi Base64\",\"C\":\"Mengubah port default web server dari port 80 menjadi port 8080\",\"D\":\"Menonaktifkan firewall pada server database\"}', 'A', 'A', 1, 'Prepared statements memastikan parameter input diperlakukan murni sebagai data literal, bukan sebagai kode SQL executable.', '2026-10-07 10:28:06', '2026-10-07 10:29:13'),
(202, 13, 'Seorang stakeholder non-teknis memberikan kebutuhan aplikasi yang sangat samar: \"Buat sistem yang pintar dan otomatis\". Langkah konkret apa yang harus Anda ambil?', 'soft_skill', 'Komunikasi Kebutuhan Bisnis', '{\"A\":\"Mengajak stakeholder berdiskusi dengan membuat alur use case sederhana, kriteria keberhasilan yang terukur, dan wireframe interaktif\",\"B\":\"Langsung menulis kode rumit berdasarkan asumsi sendiri tanpa konfirmasi\",\"C\":\"Menolak proyek dan mengatakan stakeholder tidak kompeten\",\"D\":\"Menunggu sampai ada dokumen spesifikasi lengkap setebal 100 halaman\"}', 'A', 'A', 1, 'Menerjemahkan ide abstrak menjadi kriteria terukur dan prototipe visual adalah peran kunci perekayasa perangkat lunak.', '2026-10-07 10:28:06', '2026-10-07 10:29:13'),
(203, 13, 'Teknisi lapangan melaporkan bahwa sensor getaran mesin motor industri sering mengirim data yang tidak menentu. Operator menuduh firmware yang bermasalah, sementara programmer menduga sensor kendor. Solusi kolaboratif terbaik adalah:', 'soft_skill', 'Komunikasi & Diagnosa Lapangan', '{\"A\":\"Bersama-sama ke lapangan, mengukur sinyal sensor dengan instrumen osiloskop portabel, memverifikasi mounting fisik, dan membaca raw data serial\",\"B\":\"Saling berdebat di grup chat tanpa ada yang memeriksa kondisi fisik mesin di pabrik\",\"C\":\"Mematikan fitur alarm sensor agar tidak ada laporan gangguan lagi\",\"D\":\"Menyerahkan masalah kepada divisi keuangan perusahaan\"}', 'A', 'A', 1, 'Verifikasi berbasis data riil dan pengukuran instrumen langsung di lapangan memotong spekulasi dan mempercepat penyelesaian akar masalah.', '2026-10-07 10:28:06', '2026-10-07 10:29:13'),
(204, 13, 'Dalam proyek kolaborasi pembuatan alat IoT, terjadi ketidakcocokan antara hardware engineer dan firmware engineer terkait pin GPIO yang digunakan. Bagaimana cara pencegahan terbaik di masa depan?', 'soft_skill', 'Standardisasi Rekayasa Perangkat Keras', '{\"A\":\"Menyepakati dan membekukan dokumen \\\"Hardware Pinout Map & Register Specification\\\" sebelum pembuatan layout PCB dan penulisan kode dimulai\",\"B\":\"Melarang programmer dan hardware engineer saling berbicara satu sama lain\",\"C\":\"Hanya mempercayai ingatan lisan tanpa membuat dokumentasi tertulis\",\"D\":\"Menyerahkan pemilihan pin secara acak setiap hari\"}', 'A', 'A', 1, 'Dokumen spesifikasi pinout antarmuka adalah kontrak resmi antara tim perancang skematik dan pengembang firmware.', '2026-10-07 10:28:06', '2026-10-07 10:29:13'),
(205, 13, 'Klien menginginkan perangkat pelacak hewan ternak berbasis baterai koin kecil dapat menyala selama 5 tahun terus-menerus sambil mengirim data GPS setiap 1 detik. Bagaimana cara menjelaskan realitas teknis kepadanya?', 'soft_skill', 'Manajemen Ekspektasi Klien', '{\"A\":\"Menyajikan lembar kalkulasi power budget (kapasitas baterai mAh vs konsumsi arus modul GPS\\/transmisi) dan menawarkan kompromi duty cycle interval transmisi\",\"B\":\"Menyetujui permintaan klien dan berjanji palsu alat akan tahan 5 tahun\",\"C\":\"Mengatakan klien bodoh karena tidak mengerti hukum fisika\",\"D\":\"Membeli baterai biasa dan menempelkan stiker \\\"Baterai 5 Tahun\\\"\"}', 'A', 'A', 1, 'Edukasi klien dengan kalkulasi ilmiah dan penawaran opsi kompromi (misal: deep sleep dengan transmisi tiap 30 menit) adalah tanda profesionalisme.', '2026-10-07 10:28:06', '2026-10-07 10:29:13'),
(206, 13, 'Anda menemukan bug kritis di server production tepat 30 menit sebelum jam peluncuran sistem. Sikap profesional rekayasa apa yang paling tepat dilakukan?', 'soft_skill', 'Problem Solving & Insiden Kerja', '{\"A\":\"Mengomunikasikan temuan ke tim\\/stakeholder secara transparan, menganalisis risiko, dan menerapkan hotfix teruji atau menunda peluncuran secara aman\",\"B\":\"Mengabaikan bug tersebut dengan harapan tidak ditemukan oleh pengguna\",\"C\":\"Menyalahkan rekan tim yang menulis modul tersebut di grup publik\",\"D\":\"Melakukan perubahan langsung di server live tanpa membuat cadangan kode dan database\"}', 'A', 'A', 1, 'Integritas teknis dan komunikasi risiko secara objektif merupakan soft-skill paling berharga bagi seorang profesional engineering.', '2026-10-07 10:28:06', '2026-10-07 10:29:13'),
(207, 13, 'Mengapa pin input digital pada mikrokontroler tidak boleh dibiarkan mengambang (floating pin) tanpa resistor pull-up atau pull-down?', 'hard_skill', 'Perancangan Sirkuit GPIO', '{\"A\":\"Pin akan menangkap noise elektromagnetik lingkungan sehingga status logikanya berfluktuasi secara acak antara 0 dan 1\",\"B\":\"Akan menyebabkan mikrokontroler langsung terbakar seketika\",\"C\":\"Mencegah tegangan suplai naik menjadi dua kali lipat\",\"D\":\"Memaksa mikrokontroler masuk ke mode upload firmware\"}', 'A', 'A', 1, 'Floating pin memiliki impedansi input yang sangat tinggi, sangat rentan terhadap medan statis dan interferensi udara.', '2026-10-07 10:28:06', '2026-10-07 10:29:13'),
(208, 13, 'Dalam bahasa C Embedded untuk pemrograman register hardware mikrokontroler, apa fungsi utama dari kata kunci \"volatile\"?', 'hard_skill', 'Embedded C Programming', '{\"A\":\"Memberitahu compiler agar tidak mengoptimasi variabel tersebut karena nilainya dapat berubah sewaktu-waktu oleh hardware\\/interrupt\",\"B\":\"Menyimpan variabel secara permanen di memori Flash ROM\",\"C\":\"Membuat variabel dapat diakses dari komputer jarak jauh\",\"D\":\"Mengubah tipe data integer menjadi string\"}', 'A', 'A', 1, 'Compiler yang agresif dapat menghilangkan pembacaan ulang register jika dianggap nilainya statis; volatile memaksa compiler membaca ulang dari memori fisik.', '2026-10-07 10:28:06', '2026-10-07 10:29:13'),
(209, 13, 'Ketika aplikasi web mengalami lonjakan pengiriman email konfirmasi (10.000 email sekaligus), arsitektur apa yang paling tepat digunakan agar antarmuka pengguna tidak macet (non-blocking)?', 'hard_skill', 'Message Broker & Asynchronous Queue', '{\"A\":\"Asynchronous Message Queue (misal: Redis Queue \\/ RabbitMQ) yang diproses oleh background worker\",\"B\":\"Menjalankan loop pengiriman email di controller utama request HTTP\",\"C\":\"Meminta pengguna untuk menunggu loading browser selama 15 menit\",\"D\":\"Mengubah ukuran RAM komputer klien\"}', 'A', 'A', 1, 'Queue menyimpan tugas di antrean pesan dan langsung mengembalikan respon HTTP ke pengguna dalam hitungan milidetik.', '2026-10-07 10:28:06', '2026-10-07 10:29:13'),
(210, 13, 'Pada protokol HTTPS, bagaimana proses pertukaran kunci enkripsi terjadi saat proses TLS Handshake awal?', 'hard_skill', 'Jaringan & Kriptografi', '{\"A\":\"Menggunakan kriptografi asimetris (Public\\/Private Key) untuk menyepakati Symmetric Session Key yang efisien\",\"B\":\"Mengirimkan password database secara plaintext\",\"C\":\"Hanya menggunakan algoritma hashing MD5 satu arah\",\"D\":\"Mengabaikan sertifikat SSL jika domain tidak cocok\"}', 'A', 'A', 1, 'TLS menggunakan asimetris untuk autentikasi dan negosiasi kunci, kemudian menggunakan simetris untuk enkripsi data berkecepatan tinggi.', '2026-10-07 10:28:06', '2026-10-07 10:29:13'),
(211, 13, 'Klien meminta penambahan 3 fitur kompleks baru di tengah sprint yang sudah berjalan dengan batas waktu deadline yang tidak bisa diundur. Bagaimana respons terbaik Anda?', 'soft_skill', 'Manajemen Ekspektasi & Agile', '{\"A\":\"Mendiskusikan trade-off secara profesional, menetapkan prioritas fitur MVP, dan memindahkan fitur tambahan ke sprint berikutnya\",\"B\":\"Langsung mengiyakan semua permintaan meskipun tahu tim tidak akan sanggup menyelesaikannya\",\"C\":\"Memutus kontak dengan klien dan tidak masuk kerja\",\"D\":\"Menghapus pengujian unit dan standar keamanan demi mengejar waktu\"}', 'A', 'A', 1, 'Pengembang profesional mengelola ruang lingkup secara transparan dengan fokus pada nilai bisnis dan viabilitas teknis.', '2026-10-07 10:28:06', '2026-10-07 10:29:13'),
(212, 13, 'Setelah terjadi insiden konveyor otomatis pabrik berhenti mendadak akibat sensor photo-electric tertutup debu tebal, rekomendasi preventif menyeluruh apa yang perlu diberikan ke manajemen pabrik?', 'soft_skill', 'Pemeliharaan Preventif & SOP', '{\"A\":\"Menetapkan jadwal rutin pembersihan sensor pada checklist harian operator dan menambahkan sensor redundan dengan logika peringatan dini degradasi sinyal\",\"B\":\"Melepas semua sensor keselamatan dan mengoperasikan mesin secara manual dengan risiko tinggi\",\"C\":\"Menyalahkan debu pabrik dan menuntut agar seluruh pabrik beroperasi tanpa debu sama sekali\",\"D\":\"Tidak melakukan apapun karena mesin sudah berjalan normal kembali\"}', 'A', 'A', 1, 'Pencegahan jangka panjang melibatkan pemeliharaan preventif berjadwal serta perancangan sistem peringatan dini (predictive maintenance).', '2026-10-07 10:28:06', '2026-10-07 10:29:13'),
(213, 13, 'Kapan arsitektur basis data NoSQL tipe Dokumen (seperti MongoDB) lebih diutamakan dibandingkan SQL Relasional tradisional?', 'hard_skill', 'Database Architecture', '{\"A\":\"Saat skema data bersifat dinamis, tidak terstruktur ketat, dan membutuhkan skalabilitas horizontal cepat\",\"B\":\"Saat membutuhkan integritas transaksi multi-tabel perbankan yang ketat\",\"C\":\"Saat data hanya berjumlah kurang dari 100 baris\",\"D\":\"Saat tidak diperbolehkan menggunakan memori RAM di server\"}', 'A', 'A', 1, 'NoSQL dokumen menyimpan data JSON-like polimorfik tanpa perlu migrasi DDL kaku setiap perubahan struktur kolom.', '2026-10-07 10:28:06', '2026-10-07 10:29:13'),
(214, 13, 'Ketika proyek IoT kelompok Anda mengalami kegagalan transmisi data ke MQTT broker di industri saat pengujian lapangan, langkah investigasi awal apa yang paling bijak dan terstruktur?', 'soft_skill', 'Troubleshooting Lapangan', '{\"A\":\"Memeriksa konektivitas jaringan dasar (ping\\/gateway) dan serial monitor log perangkat secara terisolasi\",\"B\":\"Langsung mengganti seluruh mikrokontroler dengan modul yang baru\",\"C\":\"Menghapus seluruh baris kode firmware dan mulai menulis dari awal\",\"D\":\"Menyalahkan tim penyedia server cloud sebelum memeriksa log lokal\"}', 'A', 'A', 1, 'Troubleshooting rekayasa yang profesional selalu mengisolasi variabel masalah dari lapisan paling bawah (koneksi fisik/jaringan) menggunakan log.', '2026-10-07 10:28:06', '2026-10-07 10:29:13'),
(215, 14, 'Pada sistem operasi Linux server, perintah baris apa yang paling cepat digunakan untuk memantau proses mana yang paling banyak memakan CPU dan memori secara interaktif?', 'hard_skill', 'Linux & Server Administration', '{\"A\":\"ping localhost\",\"B\":\"ls -la\",\"C\":\"top atau htop\",\"D\":\"chmod 777\"}', 'C', 'A', 0, 'Perintah top/htop menampilkan task manager interaktif di terminal dengan urutan penggunaan CPU dan RAM terkini.', '2026-10-07 10:33:41', '2026-10-07 10:34:49'),
(216, 14, 'Seorang anggota tim junior tampak kesulitan dan frustrasi menyelesaikan tugas modul autentikasi selama 2 hari berturut-turut. Sikap empati teknis apa yang harus ditunjukkan?', 'soft_skill', 'Mentoring & Kerjasama Tim', '{\"A\":\"Mengajak berdiskusi santai, melakukan sesi pair-programming untuk memecah masalah menjadi sub-tugas yang lebih kecil, dan memberi bimbingan\",\"B\":\"Membiarkannya sampai deadline lewat agar dia belajar sendiri\",\"C\":\"Mengambil alih tugasnya secara diam-diam tanpa menjelaskan apapun\",\"D\":\"Memarahi junior tersebut di depan seluruh anggota tim saat stand-up meeting\"}', 'A', 'A', 1, 'Pair-programming dan bimbingan memecah hambatan teknis sekaligus mempercepat transfer pengetahuan dalam tim.', '2026-10-07 10:33:41', '2026-10-07 10:34:49'),
(217, 14, 'Sebuah tim teknisi pemula kesulitan melakukan flashing firmware baru ke perangkat PLC dan modul IoT di pabrik cabang. Cara terbaik membimbing mereka dari kantor pusat adalah:', 'soft_skill', 'Knowledge Transfer & Dokumentasi', '{\"A\":\"Menghapus hak akses teknisi tersebut dari sistem\",\"B\":\"Menyuruh mereka membaca manual teknis 500 halaman dalam bahasa asing tanpa bimbingan\",\"C\":\"Mengatakan bahwa mereka tidak kompeten sebagai teknisi\",\"D\":\"Menyediakan panduan visual SOP langkah demi langkah (Standard Operating Procedure), video demonstrasi, dan mengadakan sesi remote support\"}', 'D', 'D', 1, 'Transfer keahlian yang terstruktur dengan media panduan visual dan pendampingan memperkuat kemandirian operasional tim lapangan.', '2026-10-07 10:33:41', '2026-10-07 10:34:49'),
(218, 14, 'Pada antarmuka input pencarian real-time (auto-complete), teknik apa yang digunakan untuk menunda eksekusi pemanggilan API hingga pengguna berhenti mengetik selama durasi tertentu?', 'hard_skill', 'Frontend Optimization', '{\"A\":\"Server Polling\",\"B\":\"Throttling\",\"C\":\"CSS Keyframe Animation\",\"D\":\"Debouncing\"}', 'D', 'B', 0, 'Debounce me-reset timer setiap kali karakter baru diketik, sehingga request API hanya dikirim saat pengguna jeda sejenak.', '2026-10-07 10:33:41', '2026-10-07 10:34:49'),
(219, 14, 'Saat merakit prototipe papan sirkuit baru di laboratorium, tim mendapati salah satu IC regulator mengeluarkan asap akibat polaritas catu daya terbalik. Sikap kerja standar apa yang harus diambil?', 'soft_skill', 'Keselamatan Kerja & Prosedur Lab', '{\"A\":\"Terus menaikkan voltase daya untuk melihat apa yang akan terjadi selanjutnya\",\"B\":\"Segera putuskan sumber daya listrik, evaluasi kerusakan, periksa skema proteksi polaritas terbalik, dan catat temuan untuk revisi PCB\",\"C\":\"Menyiram papan sirkuit dengan air saat masih terhubung ke listrik PLN\",\"D\":\"Menyembunyikan komponen yang terbakar dan pura-pura tidak tahu\"}', 'B', 'A', 0, 'Keselamatan laboratorium menuntut pemutusan daya segera, identifikasi akar masalah (menambahkan dioda reverse polarity), dan dokumentasi insiden.', '2026-10-07 10:33:41', '2026-10-07 10:34:49'),
(220, 14, 'Teknologi protokol apa yang paling efisien untuk mengimplementasikan fitur Dashboard Monitoring Real-Time dengan komunikasi dua arah (full-duplex) tanpa overhead polling berulang?', 'hard_skill', 'Komunikasi Real-time', '{\"A\":\"SMTP Mail Service\",\"B\":\"WebSocket\",\"C\":\"HTTP Short Polling\",\"D\":\"FTP Transfer\"}', 'B', 'C', 0, 'WebSocket mempertahankan koneksi TCP tunggal terbuka secara persisten, memungkinkan push data instan dari server ke klien.', '2026-10-07 10:33:41', '2026-10-07 10:34:49'),
(221, 14, 'Ketika melakukan Code Review pada pull request rekan satu tim, Anda menemukan pendekatan kode yang berbeda dengan gaya Anda namun tetap benar dan efisien. Tindakan terbaik Anda adalah:', 'soft_skill', 'Kolaborasi & Code Review', '{\"A\":\"Menyetujui PR jika memenuhi standar arsitektur tim dan uji unit lulus, sambil memberikan saran konstruktif opsional\",\"B\":\"Menolak PR dan memaksakan gaya koding pribadi Anda\",\"C\":\"Mengabaikan PR tersebut tanpa memberikan review selama berhari-hari\",\"D\":\"Mengubah kode rekan kerja secara sepihak tanpa izin\"}', 'A', 'B', 0, 'Code review berfokus pada kualitas, kebenaran, dan keterbacaan kode tim, bukan preferensi gaya personal penguji.', '2026-10-07 10:33:41', '2026-10-07 10:34:49'),
(222, 14, 'Berapa kompleksitas waktu rata-rata algoritma Binary Search untuk mencari suatu data pada larik (array) yang sudah terurut sepanjang N elemen?', 'hard_skill', 'Struktur Data & Algoritma', '{\"A\":\"O(log N)\",\"B\":\"O(N^2)\",\"C\":\"O(N)\",\"D\":\"O(1)\"}', 'A', 'A', 1, 'Binary Search membagi ruang pencarian menjadi separuh pada setiap iterasi, menghasilkan kompleksitas logaritmik O(log N).', '2026-10-07 10:33:41', '2026-10-07 10:34:49');
INSERT INTO `assessment_questions` (`id`, `assessment_id`, `question_text`, `type`, `topic`, `options`, `correct_option`, `user_answer`, `is_correct`, `explanation`, `created_at`, `updated_at`) VALUES
(223, 14, 'Di tengah proses produksi massal perangkat otomasi, pabrik komponen mengumumkan bahwa chip mikrokontroler utama discontinue (EOL). Bagaimana keputusan rekayasa terbaik tim?', 'soft_skill', 'Manajemen Rantai Pasok Hardware', '{\"A\":\"Mencari chip alternatif pin-to-pin compatible atau merancang ulang layout PCB minimal dengan chip yang memiliki ketersediaan pasokan jangka panjang\",\"B\":\"Mengabaikan kabar tersebut dan berharap pabrik membuat pengecualian\",\"C\":\"Membeli komponen bekas rusak dari sumber tidak jelas tanpa verifikasi datasheet\",\"D\":\"Menghentikan seluruh bisnis perusahaan dan membatalkan pesanan klien secara permanen\"}', 'A', 'A', 1, 'Ketahanan desain perangkat keras dinilai dari kemampuan rekayasawan beradaptasi terhadap ketersediaan komponen rantai pasok global.', '2026-10-07 10:33:41', '2026-10-07 10:34:49'),
(224, 14, 'Ketika proyek IoT kelompok Anda mengalami kegagalan transmisi data ke MQTT broker di industri saat pengujian lapangan, langkah investigasi awal apa yang paling bijak dan terstruktur?', 'soft_skill', 'Troubleshooting Lapangan', '{\"A\":\"Memeriksa konektivitas jaringan dasar (ping\\/gateway) dan serial monitor log perangkat secara terisolasi\",\"B\":\"Menghapus seluruh baris kode firmware dan mulai menulis dari awal\",\"C\":\"Langsung mengganti seluruh mikrokontroler dengan modul yang baru\",\"D\":\"Menyalahkan tim penyedia server cloud sebelum memeriksa log lokal\"}', 'A', 'A', 1, 'Troubleshooting rekayasa yang profesional selalu mengisolasi variabel masalah dari lapisan paling bawah (koneksi fisik/jaringan) menggunakan log.', '2026-10-07 10:33:41', '2026-10-07 10:34:49'),
(225, 14, 'Teknik apa yang digunakan oleh web browser untuk mempercepat metrik LCP (Largest Contentful Paint) pada halaman web yang memiliki banyak gambar besar?', 'hard_skill', 'Web Performance & Core Web Vitals', '{\"A\":\"Mengubah gambar menjadi file audio\",\"B\":\"Menghapus file CSS styling utama\",\"C\":\"Menjalankan loop JavaScript untuk mengunduh semua gambar bersamaan di thread utama\",\"D\":\"Implementasi Lazy Loading (loading=\\\"lazy\\\"), format WebP\\/AVIF modern, dan CDN aset statis\"}', 'D', 'D', 1, 'Lazy loading menunda download gambar off-screen hingga pengguna menggulir mendekati viewport, membebaskan bandwidth.', '2026-10-07 10:33:41', '2026-10-07 10:34:49'),
(226, 14, 'Untuk mencegah serangan Cross-Site Scripting (Stored XSS) pada kolom komentar pengguna, mekanisme apa yang wajib diimplementasikan sebelum merender konten ke browser?', 'hard_skill', 'Keamanan Web (OWASP)', '{\"A\":\"Mengharuskan pengguna mengunggah file zip\",\"B\":\"Menghapus session cookie setelah 5 detik\",\"C\":\"Menggunakan protokol HTTP\\/2\",\"D\":\"HTML Entity Encoding \\/ Sanitasi output sehingga tag seperti <script> tidak dieksekusi browser\"}', 'D', 'D', 1, 'Encoding mengonversi karakter berbahaya seperti < dan > menjadi &lt; dan &gt; sehingga browser merendernya sebagai teks biasa.', '2026-10-07 10:33:41', '2026-10-07 10:34:49'),
(227, 14, 'Bagaimana strategi tim developer dalam mengelola \"Technical Debt\" (utang teknis) agar aplikasi tetap scalable dalam jangka panjang?', 'soft_skill', 'Manajemen Utang Teknis', '{\"A\":\"Mendokumentasikan technical debt di backlog dan mengalokasikan persentase kapasitas tertentu di tiap sprint untuk refactoring\",\"B\":\"Menulis ulang seluruh aplikasi dari nol setiap kali ada teknologi framework baru\",\"C\":\"Tidak pernah melakukan refactoring sampai aplikasi benar-benar crash\",\"D\":\"Menyembunyikan kode yang berantakan dengan mengabaikan peringatan linter\"}', 'A', 'A', 1, 'Mengalokasikan kapasitas berkala (misal 15-20% per sprint) menjaga keseimbangan antara rilis fitur dan kesehatan basis kode.', '2026-10-07 10:33:41', '2026-10-07 10:34:49'),
(228, 14, 'Dalam protokol komunikasi MQTT yang sering digunakan pada IoT, peran apa yang berfungsi sebagai perantara penerima dan penyalur pesan antara publisher dan subscriber?', 'hard_skill', 'Protokol Komunikasi IoT', '{\"A\":\"Edge Gateway Node\",\"B\":\"Payload Serializer\",\"C\":\"MQTT Broker\",\"D\":\"DNS Server\"}', 'C', 'A', 0, 'MQTT Broker bertanggung jawab menerima semua pesan dari publisher, menyaring berdasarkan topik, dan mengirimkan ke semua subscriber yang berlangganan.', '2026-10-07 10:33:41', '2026-10-07 10:34:49'),
(229, 14, 'Anda melihat rekan teknisi hendak mengukur terminal listrik 380V pada panel distribusi tanpa menggunakan sarung tangan isolasi dan kacamata pelindung. Tindakan Anda adalah:', 'soft_skill', 'K3 & Keselamatan Kelistrikan', '{\"A\":\"Segera menegur dan menghentikannya secara tegas, mengingatkan bahaya busur api (Arc Flash), dan memastikan APD lengkap terpasang\",\"B\":\"Ikut-ikutan mengukur tanpa APD agar dinilai pemberani\",\"C\":\"Membiarkannya karena merasa itu bukan urusan pribadi Anda\",\"D\":\"Merekam videonya untuk dijadikan lelucon di media sosial\"}', 'A', 'A', 1, 'Intervensi keselamatan kerja (K3) adalah kewajiban mutlak setiap individu demi melindungi keselamatan nyawa tim di area bertegangan tinggi.', '2026-10-07 10:33:41', '2026-10-07 10:34:49'),
(230, 14, 'Setelah insiden downtime sistem berhasil dipulihkan, tim mengadakan rapat \"Blameless Post-Mortem\". Apa tujuan utama dari rapat ini?', 'soft_skill', 'Budaya Teknik & Retrospektif', '{\"A\":\"Mencari satu orang untuk dijatuhi sanksi dan disalahkan atas insiden\",\"B\":\"Memperdebatkan siapa yang paling berjasa memulihkan sistem\",\"C\":\"Menghapus log error agar reputasi tim tidak terlihat buruk\",\"D\":\"Mengidentifikasi akar penyebab sistemik (Root Cause) dan merancang mitigasi pencegahan agar insiden serupa tidak terulang\"}', 'D', 'D', 1, 'Blameless post-mortem mengasumsikan kesalahan terjadi akibat kelemahan sistem dan prosedur, bukan kelalaian jahat individu.', '2026-10-07 10:33:41', '2026-10-07 10:34:49'),
(231, 14, 'Dalam alur kerja Git kolaboratif tim industri, perintah apa yang digunakan untuk mengambil perubahan terbaru dari remote server sekaligus menggabungkannya ke branch kerja saat ini?', 'hard_skill', 'Git Version Control', '{\"A\":\"git stash drop\",\"B\":\"git push --force\",\"C\":\"git reset --hard\",\"D\":\"git pull\"}', 'D', 'A', 0, 'git pull menjalankan kombinasi git fetch (mengambil data dari remote) dan git merge (menggabungkan ke branch lokal).', '2026-10-07 10:33:41', '2026-10-07 10:34:49'),
(232, 14, 'Rumus frekuensi cutoff (fc) untuk rangkaian filter pasif pelewat rendah (Low-Pass Filter) orde-1 yang terdiri dari satu Resistor R dan satu Kapasitor C adalah:', 'hard_skill', 'Analisis Rangkaian Elektronika', '{\"A\":\"fc = 1 \\/ (2 * \\u03c0 * R * C)\",\"B\":\"fc = R \\/ (2 * \\u03c0 * C)\",\"C\":\"fc = C \\/ (R * 2 * \\u03c0)\",\"D\":\"fc = 2 * \\u03c0 * R * C\"}', 'A', 'C', 0, 'Frekuensi cutoff -3dB terjadi ketika reaktansi kapasitif Xc sama dengan nilai resistansi R.', '2026-10-07 10:33:41', '2026-10-07 10:34:49'),
(233, 14, 'Berdasarkan Teorema Sampling Nyquist-Shannon, jika suatu sinyal analog memiliki frekuensi maksimum sebesar 5 kHz, berapa laju pencuplikan (sampling rate) minimum ADC agar tidak terjadi aliasing?', 'hard_skill', 'Pemrosesan Sinyal & ADC', '{\"A\":\"2.5 kHz (setengah dari frekuensi tertinggi)\",\"B\":\"10 kHz (dua kali frekuensi tertinggi sinyal)\",\"C\":\"100 kHz secara mutlak\",\"D\":\"5 kHz (sama persis dengan frekuensi tertinggi)\"}', 'B', 'B', 1, 'Teorema Nyquist mensyaratkan fs >= 2 * fmax agar bentuk gelombang analog asli dapat direkonstruksi secara sempurna.', '2026-10-07 10:33:41', '2026-10-07 10:34:49'),
(234, 14, 'Pada desain tata letak PCB (Printed Circuit Board), di manakah posisi terbaik untuk meletakkan kapasitor decoupling (bypass capacitor 0.1 uF)?', 'hard_skill', 'Desain PCB & Integritas Sinyal', '{\"A\":\"Di sudut paling luar dari papan PCB jauh dari IC\",\"B\":\"Sedekat mungkin dengan pin VCC dan GND dari IC\\/mikrokontroler yang bersangkutan\",\"C\":\"Dipasang seri dengan jalur antena RF\",\"D\":\"Di bawah konektor baterai\"}', 'B', 'D', 0, 'Menempatkan kapasitor sedekat mungkin meminimalkan induktansi parasitik jalur tembaga, meredam ripple tegangan transien berkecepatan tinggi.', '2026-10-07 10:33:41', '2026-10-07 10:34:49'),
(235, 15, 'Pada framework Laravel, apa solusi terbaik untuk mengatasi masalah query performa \"N+1 Problem\" ketika mengambil relasi data mahasiswa beserta daftar portofolionya?', 'hard_skill', 'ORM & Database Performance', '{\"A\":\"Mengubah tipe basis data menjadi NoSQL MongoDB\",\"B\":\"Menggunakan Eager Loading dengan method User::with(\'portfolios\')->get()\",\"C\":\"Melakukan query di dalam perulangan foreach blade template\",\"D\":\"Menonaktifkan relasi foreign key pada migrasi database\"}', 'B', 'B', 1, 'Eager Loading mengambil semua relasi terkait hanya dalam 1-2 query SQL gabungan, mencegah query berulang sebanyak N baris data.', '2026-10-07 12:50:44', '2026-10-07 12:51:50'),
(236, 15, 'Ketika mengukur tegangan output dari rangkaian PWM motor DC menggunakan osiloskop, sinyal yang tampak mengalami noise frekuensi tinggi akibat lonjakan induktif motor. Komponen pasif apa yang wajib dipasang sebagai proteksi flyback?', 'hard_skill', 'Rangkaian Proteksi Elektronika', '{\"A\":\"Resistor pull-up 10k Ohm ke VCC\",\"B\":\"Dioda Penyearah (Freewheeling\\/Flyback Diode) paralel berlawanan arah dengan beban induktif\",\"C\":\"Kapasitor elektrolit seri dengan tegangan supply\",\"D\":\"Induktor tambahan pada pin enable\"}', 'B', 'B', 1, 'Flyback diode menyalurkan energi medan magnet yang tersimpan pada kumparan motor saat saklar transistor mati, mencegah lonjakan tegangan balik (Back-EMF).', '2026-10-07 12:50:44', '2026-10-07 12:51:51'),
(237, 15, 'Fitur perangkat keras mikrokontroler apa yang bertindak sebagai \"penjaga\" untuk melakukan reset otomatis jika firmware mengalami loop tak berujung (hang/freeze)?', 'hard_skill', 'Keandalan Sistem Tertanam', '{\"A\":\"Baud Rate Generator\",\"B\":\"Real-Time Clock (RTC)\",\"C\":\"Watchdog Timer (WDT)\",\"D\":\"Direct Memory Access (DMA)\"}', 'C', 'D', 0, 'Firmware harus secara periodik \"memberi makan\" (refresh) WDT; jika firmware macet dan timer overflow, WDT mereset mikrokontroler ke kondisi awal.', '2026-10-07 12:50:44', '2026-10-07 12:51:51'),
(238, 15, 'Dalam arsitektur container Docker, apa fungsi utama dari file Dockerfile dalam siklus deployment aplikasi web?', 'hard_skill', 'DevOps & Containerization', '{\"A\":\"Sebagai pengganti compiler bahasa pemrograman\",\"B\":\"Menyimpan password database production secara plaintext\",\"C\":\"Menggantikan fungsi web server Nginx dan Apache\",\"D\":\"Berisi instruksi deklaratif untuk membangun Image aplikasi yang terisolasi dan konsisten di berbagai lingkungan\"}', 'D', 'D', 1, 'Dockerfile mendefinisikan layer sistem operasi dasar, dependensi library, dan konfigurasi runtime untuk menghasilkan Docker Image.', '2026-10-07 12:50:44', '2026-10-07 12:51:51'),
(239, 15, 'Untuk melindungi port input mikrokontroler dari sengatan Electrostatic Discharge (ESD) saat port dihubungkan oleh pengguna di lapangan, komponen apa yang dipasang?', 'hard_skill', 'Proteksi Sirkuit & EMC', '{\"A\":\"Kawat jumper tembaga tanpa hambatan\",\"B\":\"Resistor variabel potensiometer\",\"C\":\"Kapasitor elektrolit 1000 uF\",\"D\":\"Dioda TVS (Transient Voltage Suppressor) klem ke GND\"}', 'D', 'D', 1, 'Dioda TVS merespons dalam hitungan pikodetik untuk menyalurkan lonjakan tegangan transien ribuan volt ke ground secara aman.', '2026-10-07 12:50:44', '2026-10-07 12:51:51'),
(240, 15, 'Laporan audit keamanan menemukan celah kerentanan kritis kategori High pada dependensi pihak ketiga yang digunakan sistem Anda. Tindakan prioritas tim adalah:', 'soft_skill', 'Manajemen Risiko Keamanan', '{\"A\":\"Menganggap celah keamanan hanya teori dan tidak mungkin diserang hacker nyata\",\"B\":\"Menunda penanganan celah keamanan selama 6 bulan sampai roadmap fitur selesai\",\"C\":\"Menghapus modul keamanan dari sistem agar audit tidak mendeteksi celah lagi\",\"D\":\"Mengevaluasi dampak, memperbarui package ke versi patch terbaru di staging, menjalankan automated test suite, dan segera rilis patch ke production\"}', 'D', 'C', 0, 'Kerentanan kritis pada dependensi harus dimitigasi segera dengan proses verifikasi regresi yang terukur.', '2026-10-07 12:50:44', '2026-10-07 12:51:51'),
(241, 15, 'Saat merakit prototipe papan sirkuit baru di laboratorium, tim mendapati salah satu IC regulator mengeluarkan asap akibat polaritas catu daya terbalik. Sikap kerja standar apa yang harus diambil?', 'soft_skill', 'Keselamatan Kerja & Prosedur Lab', '{\"A\":\"Menyiram papan sirkuit dengan air saat masih terhubung ke listrik PLN\",\"B\":\"Segera putuskan sumber daya listrik, evaluasi kerusakan, periksa skema proteksi polaritas terbalik, dan catat temuan untuk revisi PCB\",\"C\":\"Menyembunyikan komponen yang terbakar dan pura-pura tidak tahu\",\"D\":\"Terus menaikkan voltase daya untuk melihat apa yang akan terjadi selanjutnya\"}', 'B', 'C', 0, 'Keselamatan laboratorium menuntut pemutusan daya segera, identifikasi akar masalah (menambahkan dioda reverse polarity), dan dokumentasi insiden.', '2026-10-07 12:50:44', '2026-10-07 12:51:51'),
(242, 15, 'Ketika melakukan Code Review pada pull request rekan satu tim, Anda menemukan pendekatan kode yang berbeda dengan gaya Anda namun tetap benar dan efisien. Tindakan terbaik Anda adalah:', 'soft_skill', 'Kolaborasi & Code Review', '{\"A\":\"Mengabaikan PR tersebut tanpa memberikan review selama berhari-hari\",\"B\":\"Menyetujui PR jika memenuhi standar arsitektur tim dan uji unit lulus, sambil memberikan saran konstruktif opsional\",\"C\":\"Menolak PR dan memaksakan gaya koding pribadi Anda\",\"D\":\"Mengubah kode rekan kerja secara sepihak tanpa izin\"}', 'B', 'D', 0, 'Code review berfokus pada kualitas, kebenaran, dan keterbacaan kode tim, bukan preferensi gaya personal penguji.', '2026-10-07 12:50:44', '2026-10-07 12:51:51'),
(243, 15, 'Dalam aplikasi web modern berbasis React / Vue, apa tujuan utama penggunaan Virtual DOM dibandingkan langsung memanipulasi Real DOM browser?', 'hard_skill', 'Modern Frontend Architecture', '{\"A\":\"Mengamankan web dari serangan SQL Injection dan XSS secara penuh\",\"B\":\"Mempercepat transmisi data TCP antara klien dan server\",\"C\":\"Menghitung perbedaan (diffing) di memori dan meminimalkan operasi render reflow\\/repaint pada Real DOM yang mahal\",\"D\":\"Menyimpan seluruh data aplikasi ke dalam LocalStorage secara otomatis\"}', 'C', 'C', 1, 'Virtual DOM membandingkan snapshot pohon DOM sebelum dan sesudah perubahan state, lalu hanya menerapkan perubahan spesifik pada browser.', '2026-10-07 12:50:44', '2026-10-07 12:51:51'),
(244, 15, 'Seorang anggota tim junior tampak kesulitan dan frustrasi menyelesaikan tugas modul autentikasi selama 2 hari berturut-turut. Sikap empati teknis apa yang harus ditunjukkan?', 'soft_skill', 'Mentoring & Kerjasama Tim', '{\"A\":\"Mengambil alih tugasnya secara diam-diam tanpa menjelaskan apapun\",\"B\":\"Mengajak berdiskusi santai, melakukan sesi pair-programming untuk memecah masalah menjadi sub-tugas yang lebih kecil, dan memberi bimbingan\",\"C\":\"Membiarkannya sampai deadline lewat agar dia belajar sendiri\",\"D\":\"Memarahi junior tersebut di depan seluruh anggota tim saat stand-up meeting\"}', 'B', 'D', 0, 'Pair-programming dan bimbingan memecah hambatan teknis sekaligus mempercepat transfer pengetahuan dalam tim.', '2026-10-07 12:50:44', '2026-10-07 12:51:51'),
(245, 15, 'Apa keuntungan mengimplementasikan model Machine Learning berbasis TinyML terkuantisasi (INT8) langsung di tingkat edge mikrokontroler?', 'hard_skill', 'Edge AI & TinyML', '{\"A\":\"Mengubah mikrokontroler menjadi superkomputer cloud\",\"B\":\"Dapat melatih model GPT-4 dari awal di dalam chip mikrokontroler\",\"C\":\"Pengambilan keputusan real-time tanpa latensi internet, hemat bandwidth, dan data sensor sensitif tetap berada di perangkat lokal\",\"D\":\"Menghilangkan kebutuhan baterai pada alat\"}', 'C', 'C', 1, 'Inference di edge menghilangkan ketergantungan konektivitas cloud dan memungkinkan proteksi privasi serta respon milidetik.', '2026-10-07 12:50:44', '2026-10-07 12:51:51'),
(246, 15, 'Tim backend perlu merilis pembaruan endpoint API yang mengubah format payload response secara signifikan (breaking change). Apa langkah profesional terbaik sebelum perubahan di-deploy?', 'soft_skill', 'Manajemen Rilis & Kolaborasi', '{\"A\":\"Membuat API versioning baru (misal \\/api\\/v2), mengomunikasikan timeline deprecation ke tim mobile\\/frontend, dan menjaga v1 tetap berjalan sementara\",\"B\":\"Menolak melakukan pembaruan selamanya demi kompatibilitas lama\",\"C\":\"Mematikan server mobile secara tiba-tiba agar mereka sadar ada pembaruan\",\"D\":\"Langsung mengubah endpoint v1 di production tanpa pemberitahuan apapun\"}', 'A', 'A', 1, 'Versioning API dan komunikasi transparan melindungi integrasi klien dari kegagalan fungsional yang fatal.', '2026-10-07 12:50:44', '2026-10-07 12:51:51'),
(247, 15, 'Dalam proyek kolaborasi pembuatan alat IoT, terjadi ketidakcocokan antara hardware engineer dan firmware engineer terkait pin GPIO yang digunakan. Bagaimana cara pencegahan terbaik di masa depan?', 'soft_skill', 'Standardisasi Rekayasa Perangkat Keras', '{\"A\":\"Hanya mempercayai ingatan lisan tanpa membuat dokumentasi tertulis\",\"B\":\"Menyepakati dan membekukan dokumen \\\"Hardware Pinout Map & Register Specification\\\" sebelum pembuatan layout PCB dan penulisan kode dimulai\",\"C\":\"Menyerahkan pemilihan pin secara acak setiap hari\",\"D\":\"Melarang programmer dan hardware engineer saling berbicara satu sama lain\"}', 'B', 'B', 1, 'Dokumen spesifikasi pinout antarmuka adalah kontrak resmi antara tim perancang skematik dan pengembang firmware.', '2026-10-07 12:50:44', '2026-10-07 12:51:51'),
(248, 15, 'Dalam strategi caching data performa tinggi, pola \"Cache-Aside\" (Lazy Loading) bekerja dengan cara:', 'hard_skill', 'Sistem Caching (Redis/Memcached)', '{\"A\":\"Memuat seluruh tabel database ke cache saat komputer pertama kali dinyalakan\",\"B\":\"Menulis data hanya ke cache tanpa pernah menyimpannya ke database\",\"C\":\"Menghapus database utama dan hanya mengandalkan cache RAM\",\"D\":\"Aplikasi memeriksa cache terlebih dahulu; jika miss, ambil dari database lalu simpan salinannya ke cache\"}', 'D', 'D', 1, 'Cache-aside hanya menyimpan data yang benar-benar di-request pengguna, menjaga efisiensi kapasitas memori cache.', '2026-10-07 12:50:44', '2026-10-07 12:51:51'),
(249, 15, 'Dalam arsitektur RESTful API modern, metode HTTP manakah yang bersifat idempoten (idempotent) dan digunakan untuk memperbarui seluruh representasi sumber daya (resource)?', 'hard_skill', 'RESTful API Architecture', '{\"A\":\"PUT\",\"B\":\"POST\",\"C\":\"PATCH\",\"D\":\"DELETE\"}', 'A', 'C', 0, 'PUT bersifat idempoten karena pemanggilan berulang kali dengan payload yang sama akan menghasilkan status akhir sumber daya yang identik.', '2026-10-07 12:50:44', '2026-10-07 12:51:51'),
(250, 15, 'Struktur standar JSON Web Token (JWT) terdiri dari tiga bagian yang dipisahkan tanda titik (.):', 'hard_skill', 'Autentikasi & Otorisasi Modern', '{\"A\":\"User.Password.Token\",\"B\":\"Header.Payload.Signature\",\"C\":\"Encryption.Salt.Hash\",\"D\":\"Protocol.Domain.Port\"}', 'B', 'D', 0, 'Header berisi tipe token dan algoritma enkripsi, Payload berisi klaim data, dan Signature memverifikasi keaslian token.', '2026-10-07 12:50:44', '2026-10-07 12:51:51'),
(251, 15, 'Anda melihat rekan teknisi hendak mengukur terminal listrik 380V pada panel distribusi tanpa menggunakan sarung tangan isolasi dan kacamata pelindung. Tindakan Anda adalah:', 'soft_skill', 'K3 & Keselamatan Kelistrikan', '{\"A\":\"Merekam videonya untuk dijadikan lelucon di media sosial\",\"B\":\"Ikut-ikutan mengukur tanpa APD agar dinilai pemberani\",\"C\":\"Membiarkannya karena merasa itu bukan urusan pribadi Anda\",\"D\":\"Segera menegur dan menghentikannya secara tegas, mengingatkan bahaya busur api (Arc Flash), dan memastikan APD lengkap terpasang\"}', 'D', 'D', 1, 'Intervensi keselamatan kerja (K3) adalah kewajiban mutlak setiap individu demi melindungi keselamatan nyawa tim di area bertegangan tinggi.', '2026-10-07 12:50:44', '2026-10-07 12:51:51'),
(252, 15, 'Seorang stakeholder non-teknis memberikan kebutuhan aplikasi yang sangat samar: \"Buat sistem yang pintar dan otomatis\". Langkah konkret apa yang harus Anda ambil?', 'soft_skill', 'Komunikasi Kebutuhan Bisnis', '{\"A\":\"Menolak proyek dan mengatakan stakeholder tidak kompeten\",\"B\":\"Langsung menulis kode rumit berdasarkan asumsi sendiri tanpa konfirmasi\",\"C\":\"Mengajak stakeholder berdiskusi dengan membuat alur use case sederhana, kriteria keberhasilan yang terukur, dan wireframe interaktif\",\"D\":\"Menunggu sampai ada dokumen spesifikasi lengkap setebal 100 halaman\"}', 'C', 'C', 1, 'Menerjemahkan ide abstrak menjadi kriteria terukur dan prototipe visual adalah peran kunci perekayasa perangkat lunak.', '2026-10-07 12:50:44', '2026-10-07 12:51:51'),
(253, 15, 'Teknisi lapangan melaporkan bahwa sensor getaran mesin motor industri sering mengirim data yang tidak menentu. Operator menuduh firmware yang bermasalah, sementara programmer menduga sensor kendor. Solusi kolaboratif terbaik adalah:', 'soft_skill', 'Komunikasi & Diagnosa Lapangan', '{\"A\":\"Mematikan fitur alarm sensor agar tidak ada laporan gangguan lagi\",\"B\":\"Menyerahkan masalah kepada divisi keuangan perusahaan\",\"C\":\"Saling berdebat di grup chat tanpa ada yang memeriksa kondisi fisik mesin di pabrik\",\"D\":\"Bersama-sama ke lapangan, mengukur sinyal sensor dengan instrumen osiloskop portabel, memverifikasi mounting fisik, dan membaca raw data serial\"}', 'D', 'D', 1, 'Verifikasi berbasis data riil dan pengukuran instrumen langsung di lapangan memotong spekulasi dan mempercepat penyelesaian akar masalah.', '2026-10-07 12:50:44', '2026-10-07 12:51:51'),
(254, 15, 'Sebuah tim teknisi pemula kesulitan melakukan flashing firmware baru ke perangkat PLC dan modul IoT di pabrik cabang. Cara terbaik membimbing mereka dari kantor pusat adalah:', 'soft_skill', 'Knowledge Transfer & Dokumentasi', '{\"A\":\"Menyuruh mereka membaca manual teknis 500 halaman dalam bahasa asing tanpa bimbingan\",\"B\":\"Menyediakan panduan visual SOP langkah demi langkah (Standard Operating Procedure), video demonstrasi, dan mengadakan sesi remote support\",\"C\":\"Mengatakan bahwa mereka tidak kompeten sebagai teknisi\",\"D\":\"Menghapus hak akses teknisi tersebut dari sistem\"}', 'B', 'B', 1, 'Transfer keahlian yang terstruktur dengan media panduan visual dan pendampingan memperkuat kemandirian operasional tim lapangan.', '2026-10-07 12:50:44', '2026-10-07 12:51:51'),
(255, 16, 'Ketika aplikasi web mengalami lonjakan pengiriman email konfirmasi (10.000 email sekaligus), arsitektur apa yang paling tepat digunakan agar antarmuka pengguna tidak macet (non-blocking)?', 'soft_skill', 'Message Broker & Asynchronous Queue', '{\"A\":\"Menjalankan loop pengiriman email di controller utama request HTTP\",\"B\":\"Mengubah ukuran RAM komputer klien\",\"C\":\"Meminta pengguna untuk menunggu loading browser selama 15 menit\",\"D\":\"Asynchronous Message Queue (misal: Redis Queue \\/ RabbitMQ) yang diproses oleh background worker\"}', 'D', 'A', 0, 'Queue menyimpan tugas di antrean pesan dan langsung mengembalikan respon HTTP ke pengguna dalam hitungan milidetik.', '2026-10-08 01:04:06', '2026-10-08 01:05:10'),
(256, 16, 'Bagaimana strategi tim developer dalam mengelola \"Technical Debt\" (utang teknis) agar aplikasi tetap scalable dalam jangka panjang?', 'soft_skill', 'Manajemen Utang Teknis', '{\"A\":\"Menyembunyikan kode yang berantakan dengan mengabaikan peringatan linter\",\"B\":\"Tidak pernah melakukan refactoring sampai aplikasi benar-benar crash\",\"C\":\"Menulis ulang seluruh aplikasi dari nol setiap kali ada teknologi framework baru\",\"D\":\"Mendokumentasikan technical debt di backlog dan mengalokasikan persentase kapasitas tertentu di tiap sprint untuk refactoring\"}', 'D', 'D', 1, 'Mengalokasikan kapasitas berkala (misal 15-20% per sprint) menjaga keseimbangan antara rilis fitur dan kesehatan basis kode.', '2026-10-08 01:04:06', '2026-10-08 01:05:10'),
(257, 16, 'Pada sistem operasi Linux server, perintah baris apa yang paling cepat digunakan untuk memantau proses mana yang paling banyak memakan CPU dan memori secara interaktif?', 'hard_skill', 'Linux & Server Administration', '{\"A\":\"top atau htop\",\"B\":\"ping localhost\",\"C\":\"chmod 777\",\"D\":\"ls -la\"}', 'A', 'D', 0, 'Perintah top/htop menampilkan task manager interaktif di terminal dengan urutan penggunaan CPU dan RAM terkini.', '2026-10-08 01:04:06', '2026-10-08 01:05:10'),
(258, 16, 'Teknologi protokol apa yang paling efisien untuk mengimplementasikan fitur Dashboard Monitoring Real-Time dengan komunikasi dua arah (full-duplex) tanpa overhead polling berulang?', 'hard_skill', 'Komunikasi Real-time', '{\"A\":\"WebSocket\",\"B\":\"HTTP Short Polling\",\"C\":\"SMTP Mail Service\",\"D\":\"FTP Transfer\"}', 'A', 'D', 0, 'WebSocket mempertahankan koneksi TCP tunggal terbuka secara persisten, memungkinkan push data instan dari server ke klien.', '2026-10-08 01:04:06', '2026-10-08 01:05:10'),
(259, 16, 'Setelah insiden downtime sistem berhasil dipulihkan, tim mengadakan rapat \"Blameless Post-Mortem\". Apa tujuan utama dari rapat ini?', 'soft_skill', 'Budaya Teknik & Retrospektif', '{\"A\":\"Menghapus log error agar reputasi tim tidak terlihat buruk\",\"B\":\"Mengidentifikasi akar penyebab sistemik (Root Cause) dan merancang mitigasi pencegahan agar insiden serupa tidak terulang\",\"C\":\"Memperdebatkan siapa yang paling berjasa memulihkan sistem\",\"D\":\"Mencari satu orang untuk dijatuhi sanksi dan disalahkan atas insiden\"}', 'B', 'D', 0, 'Blameless post-mortem mengasumsikan kesalahan terjadi akibat kelemahan sistem dan prosedur, bukan kelalaian jahat individu.', '2026-10-08 01:04:06', '2026-10-08 01:05:10'),
(260, 16, 'Pada arsitektur sistem berbasis Microservices, pola arsitektur apa yang digunakan untuk mencegah kegagalan satu service merambat (cascading failure) ke seluruh ekosistem aplikasi?', 'hard_skill', 'Arsitektur Microservices', '{\"A\":\"Circuit Breaker Pattern\",\"B\":\"Monolithic Model\",\"C\":\"Direct Synchronous Loop\",\"D\":\"Singleton Pattern\"}', 'A', 'A', 1, 'Circuit Breaker memutus panggilan sementara ke service yang sedang down/timeout dan memberikan fallback response instan.', '2026-10-08 01:04:06', '2026-10-08 01:05:10'),
(261, 16, 'Laporan audit keamanan menemukan celah kerentanan kritis kategori High pada dependensi pihak ketiga yang digunakan sistem Anda. Tindakan prioritas tim adalah:', 'soft_skill', 'Manajemen Risiko Keamanan', '{\"A\":\"Mengevaluasi dampak, memperbarui package ke versi patch terbaru di staging, menjalankan automated test suite, dan segera rilis patch ke production\",\"B\":\"Menunda penanganan celah keamanan selama 6 bulan sampai roadmap fitur selesai\",\"C\":\"Menganggap celah keamanan hanya teori dan tidak mungkin diserang hacker nyata\",\"D\":\"Menghapus modul keamanan dari sistem agar audit tidak mendeteksi celah lagi\"}', 'A', 'D', 0, 'Kerentanan kritis pada dependensi harus dimitigasi segera dengan proses verifikasi regresi yang terukur.', '2026-10-08 01:04:06', '2026-10-08 01:05:10'),
(262, 16, 'Untuk mencegah serangan Cross-Site Scripting (Stored XSS) pada kolom komentar pengguna, mekanisme apa yang wajib diimplementasikan sebelum merender konten ke browser?', 'hard_skill', 'Keamanan Web (OWASP)', '{\"A\":\"Mengharuskan pengguna mengunggah file zip\",\"B\":\"HTML Entity Encoding \\/ Sanitasi output sehingga tag seperti <script> tidak dieksekusi browser\",\"C\":\"Menghapus session cookie setelah 5 detik\",\"D\":\"Menggunakan protokol HTTP\\/2\"}', 'B', 'B', 1, 'Encoding mengonversi karakter berbahaya seperti < dan > menjadi &lt; dan &gt; sehingga browser merendernya sebagai teks biasa.', '2026-10-08 01:04:06', '2026-10-08 01:05:10'),
(263, 16, 'Seorang anggota tim junior tampak kesulitan dan frustrasi menyelesaikan tugas modul autentikasi selama 2 hari berturut-turut. Sikap empati teknis apa yang harus ditunjukkan?', 'soft_skill', 'Mentoring & Kerjasama Tim', '{\"A\":\"Mengambil alih tugasnya secara diam-diam tanpa menjelaskan apapun\",\"B\":\"Membiarkannya sampai deadline lewat agar dia belajar sendiri\",\"C\":\"Memarahi junior tersebut di depan seluruh anggota tim saat stand-up meeting\",\"D\":\"Mengajak berdiskusi santai, melakukan sesi pair-programming untuk memecah masalah menjadi sub-tugas yang lebih kecil, dan memberi bimbingan\"}', 'D', 'D', 1, 'Pair-programming dan bimbingan memecah hambatan teknis sekaligus mempercepat transfer pengetahuan dalam tim.', '2026-10-08 01:04:06', '2026-10-08 01:05:10'),
(264, 16, 'Manakah langkah proteksi paling mendasar dan efektif untuk mencegah kerentanan SQL Injection pada aplikasi web?', 'hard_skill', 'Keamanan Perangkat Lunak', '{\"A\":\"Menyimpan data password menggunakan enkripsi Base64\",\"B\":\"Menonaktifkan firewall pada server database\",\"C\":\"Menggunakan Parameterized Queries atau Prepared Statements yang memisahkan instruksi SQL dari data masukan pengguna\",\"D\":\"Mengubah port default web server dari port 80 menjadi port 8080\"}', 'C', 'C', 1, 'Prepared statements memastikan parameter input diperlakukan murni sebagai data literal, bukan sebagai kode SQL executable.', '2026-10-08 01:04:06', '2026-10-08 01:05:10'),
(265, 16, 'Ketika melakukan Code Review pada pull request rekan satu tim, Anda menemukan pendekatan kode yang berbeda dengan gaya Anda namun tetap benar dan efisien. Tindakan terbaik Anda adalah:', 'soft_skill', 'Kolaborasi & Code Review', '{\"A\":\"Menolak PR dan memaksakan gaya koding pribadi Anda\",\"B\":\"Mengubah kode rekan kerja secara sepihak tanpa izin\",\"C\":\"Menyetujui PR jika memenuhi standar arsitektur tim dan uji unit lulus, sambil memberikan saran konstruktif opsional\",\"D\":\"Mengabaikan PR tersebut tanpa memberikan review selama berhari-hari\"}', 'C', 'C', 1, 'Code review berfokus pada kualitas, kebenaran, dan keterbacaan kode tim, bukan preferensi gaya personal penguji.', '2026-10-08 01:04:06', '2026-10-08 01:05:10'),
(266, 16, 'Struktur standar JSON Web Token (JWT) terdiri dari tiga bagian yang dipisahkan tanda titik (.):', 'hard_skill', 'Autentikasi & Otorisasi Modern', '{\"A\":\"Encryption.Salt.Hash\",\"B\":\"Protocol.Domain.Port\",\"C\":\"User.Password.Token\",\"D\":\"Header.Payload.Signature\"}', 'D', 'D', 1, 'Header berisi tipe token dan algoritma enkripsi, Payload berisi klaim data, dan Signature memverifikasi keaslian token.', '2026-10-08 01:04:06', '2026-10-08 01:05:10'),
(267, 16, 'Tim backend perlu merilis pembaruan endpoint API yang mengubah format payload response secara signifikan (breaking change). Apa langkah profesional terbaik sebelum perubahan di-deploy?', 'soft_skill', 'Manajemen Rilis & Kolaborasi', '{\"A\":\"Membuat API versioning baru (misal \\/api\\/v2), mengomunikasikan timeline deprecation ke tim mobile\\/frontend, dan menjaga v1 tetap berjalan sementara\",\"B\":\"Langsung mengubah endpoint v1 di production tanpa pemberitahuan apapun\",\"C\":\"Menolak melakukan pembaruan selamanya demi kompatibilitas lama\",\"D\":\"Mematikan server mobile secara tiba-tiba agar mereka sadar ada pembaruan\"}', 'A', 'A', 1, 'Versioning API dan komunikasi transparan melindungi integrasi klien dari kegagalan fungsional yang fatal.', '2026-10-08 01:04:06', '2026-10-08 01:05:10'),
(268, 16, 'Dalam strategi caching data performa tinggi, pola \"Cache-Aside\" (Lazy Loading) bekerja dengan cara:', 'hard_skill', 'Sistem Caching (Redis/Memcached)', '{\"A\":\"Menghapus database utama dan hanya mengandalkan cache RAM\",\"B\":\"Memuat seluruh tabel database ke cache saat komputer pertama kali dinyalakan\",\"C\":\"Aplikasi memeriksa cache terlebih dahulu; jika miss, ambil dari database lalu simpan salinannya ke cache\",\"D\":\"Menulis data hanya ke cache tanpa pernah menyimpannya ke database\"}', 'C', 'C', 1, 'Cache-aside hanya menyimpan data yang benar-benar di-request pengguna, menjaga efisiensi kapasitas memori cache.', '2026-10-08 01:04:06', '2026-10-08 01:05:10'),
(269, 16, 'Teknik apa yang digunakan oleh web browser untuk mempercepat metrik LCP (Largest Contentful Paint) pada halaman web yang memiliki banyak gambar besar?', 'hard_skill', 'Web Performance & Core Web Vitals', '{\"A\":\"Menjalankan loop JavaScript untuk mengunduh semua gambar bersamaan di thread utama\",\"B\":\"Implementasi Lazy Loading (loading=\\\"lazy\\\"), format WebP\\/AVIF modern, dan CDN aset statis\",\"C\":\"Menghapus file CSS styling utama\",\"D\":\"Mengubah gambar menjadi file audio\"}', 'B', 'A', 0, 'Lazy loading menunda download gambar off-screen hingga pengguna menggulir mendekati viewport, membebaskan bandwidth.', '2026-10-08 01:04:06', '2026-10-08 01:05:10'),
(270, 16, 'Anda menemukan bug kritis di server production tepat 30 menit sebelum jam peluncuran sistem. Sikap profesional rekayasa apa yang paling tepat dilakukan?', 'soft_skill', 'Problem Solving & Insiden Kerja', '{\"A\":\"Mengomunikasikan temuan ke tim\\/stakeholder secara transparan, menganalisis risiko, dan menerapkan hotfix teruji atau menunda peluncuran secara aman\",\"B\":\"Melakukan perubahan langsung di server live tanpa membuat cadangan kode dan database\",\"C\":\"Mengabaikan bug tersebut dengan harapan tidak ditemukan oleh pengguna\",\"D\":\"Menyalahkan rekan tim yang menulis modul tersebut di grup publik\"}', 'A', 'A', 1, 'Integritas teknis dan komunikasi risiko secara objektif merupakan soft-skill paling berharga bagi seorang profesional engineering.', '2026-10-08 01:04:06', '2026-10-08 01:05:10'),
(271, 16, 'Klien meminta penambahan 3 fitur kompleks baru di tengah sprint yang sudah berjalan dengan batas waktu deadline yang tidak bisa diundur. Bagaimana respons terbaik Anda?', 'soft_skill', 'Manajemen Ekspektasi & Agile', '{\"A\":\"Mendiskusikan trade-off secara profesional, menetapkan prioritas fitur MVP, dan memindahkan fitur tambahan ke sprint berikutnya\",\"B\":\"Memutus kontak dengan klien dan tidak masuk kerja\",\"C\":\"Langsung mengiyakan semua permintaan meskipun tahu tim tidak akan sanggup menyelesaikannya\",\"D\":\"Menghapus pengujian unit dan standar keamanan demi mengejar waktu\"}', 'A', 'D', 0, 'Pengembang profesional mengelola ruang lingkup secara transparan dengan fokus pada nilai bisnis dan viabilitas teknis.', '2026-10-08 01:04:06', '2026-10-08 01:05:10'),
(272, 16, 'Seorang stakeholder non-teknis memberikan kebutuhan aplikasi yang sangat samar: \"Buat sistem yang pintar dan otomatis\". Langkah konkret apa yang harus Anda ambil?', 'soft_skill', 'Komunikasi Kebutuhan Bisnis', '{\"A\":\"Langsung menulis kode rumit berdasarkan asumsi sendiri tanpa konfirmasi\",\"B\":\"Menolak proyek dan mengatakan stakeholder tidak kompeten\",\"C\":\"Menunggu sampai ada dokumen spesifikasi lengkap setebal 100 halaman\",\"D\":\"Mengajak stakeholder berdiskusi dengan membuat alur use case sederhana, kriteria keberhasilan yang terukur, dan wireframe interaktif\"}', 'D', 'D', 1, 'Menerjemahkan ide abstrak menjadi kriteria terukur dan prototipe visual adalah peran kunci perekayasa perangkat lunak.', '2026-10-08 01:04:06', '2026-10-08 01:05:10'),
(273, 16, 'Pada protokol HTTPS, bagaimana proses pertukaran kunci enkripsi terjadi saat proses TLS Handshake awal?', 'hard_skill', 'Jaringan & Kriptografi', '{\"A\":\"Menggunakan kriptografi asimetris (Public\\/Private Key) untuk menyepakati Symmetric Session Key yang efisien\",\"B\":\"Mengirimkan password database secara plaintext\",\"C\":\"Hanya menggunakan algoritma hashing MD5 satu arah\",\"D\":\"Mengabaikan sertifikat SSL jika domain tidak cocok\"}', 'A', 'A', 1, 'TLS menggunakan asimetris untuk autentikasi dan negosiasi kunci, kemudian menggunakan simetris untuk enkripsi data berkecepatan tinggi.', '2026-10-08 01:04:06', '2026-10-08 01:05:10'),
(274, 16, 'Dalam aplikasi web modern berbasis React / Vue, apa tujuan utama penggunaan Virtual DOM dibandingkan langsung memanipulasi Real DOM browser?', 'hard_skill', 'Modern Frontend Architecture', '{\"A\":\"Mempercepat transmisi data TCP antara klien dan server\",\"B\":\"Menghitung perbedaan (diffing) di memori dan meminimalkan operasi render reflow\\/repaint pada Real DOM yang mahal\",\"C\":\"Mengamankan web dari serangan SQL Injection dan XSS secara penuh\",\"D\":\"Menyimpan seluruh data aplikasi ke dalam LocalStorage secara otomatis\"}', 'B', 'D', 0, 'Virtual DOM membandingkan snapshot pohon DOM sebelum dan sesudah perubahan state, lalu hanya menerapkan perubahan spesifik pada browser.', '2026-10-08 01:04:06', '2026-10-08 01:05:10'),
(275, 17, 'Ketika melakukan Code Review pada pull request rekan satu tim, Anda menemukan pendekatan kode yang berbeda dengan gaya Anda namun tetap benar dan efisien. Tindakan terbaik Anda adalah:', 'soft_skill', 'Kolaborasi & Code Review', '{\"A\":\"Menyetujui PR jika memenuhi standar arsitektur tim dan uji unit lulus, sambil memberikan saran konstruktif opsional\",\"B\":\"Mengubah kode rekan kerja secara sepihak tanpa izin\",\"C\":\"Menolak PR dan memaksakan gaya koding pribadi Anda\",\"D\":\"Mengabaikan PR tersebut tanpa memberikan review selama berhari-hari\"}', 'A', 'A', 1, 'Code review berfokus pada kualitas, kebenaran, dan keterbacaan kode tim, bukan preferensi gaya personal penguji.', '2026-10-08 03:28:38', '2026-10-08 03:29:35'),
(276, 17, 'Bagaimana strategi tim developer dalam mengelola \"Technical Debt\" (utang teknis) agar aplikasi tetap scalable dalam jangka panjang?', 'soft_skill', 'Manajemen Utang Teknis', '{\"A\":\"Menulis ulang seluruh aplikasi dari nol setiap kali ada teknologi framework baru\",\"B\":\"Tidak pernah melakukan refactoring sampai aplikasi benar-benar crash\",\"C\":\"Menyembunyikan kode yang berantakan dengan mengabaikan peringatan linter\",\"D\":\"Mendokumentasikan technical debt di backlog dan mengalokasikan persentase kapasitas tertentu di tiap sprint untuk refactoring\"}', 'D', 'D', 1, 'Mengalokasikan kapasitas berkala (misal 15-20% per sprint) menjaga keseimbangan antara rilis fitur dan kesehatan basis kode.', '2026-10-08 03:28:38', '2026-10-08 03:29:35'),
(277, 17, 'Pada sistem operasi Linux server, perintah baris apa yang paling cepat digunakan untuk memantau proses mana yang paling banyak memakan CPU dan memori secara interaktif?', 'soft_skill', 'Linux & Server Administration', '{\"A\":\"ls -la\",\"B\":\"ping localhost\",\"C\":\"chmod 777\",\"D\":\"top atau htop\"}', 'D', 'B', 0, 'Perintah top/htop menampilkan task manager interaktif di terminal dengan urutan penggunaan CPU dan RAM terkini.', '2026-10-08 03:28:38', '2026-10-08 03:29:35'),
(278, 17, 'Dalam aplikasi web modern berbasis React / Vue, apa tujuan utama penggunaan Virtual DOM dibandingkan langsung memanipulasi Real DOM browser?', 'hard_skill', 'Modern Frontend Architecture', '{\"A\":\"Menghitung perbedaan (diffing) di memori dan meminimalkan operasi render reflow\\/repaint pada Real DOM yang mahal\",\"B\":\"Menyimpan seluruh data aplikasi ke dalam LocalStorage secara otomatis\",\"C\":\"Mengamankan web dari serangan SQL Injection dan XSS secara penuh\",\"D\":\"Mempercepat transmisi data TCP antara klien dan server\"}', 'A', 'A', 1, 'Virtual DOM membandingkan snapshot pohon DOM sebelum dan sesudah perubahan state, lalu hanya menerapkan perubahan spesifik pada browser.', '2026-10-08 03:28:38', '2026-10-08 03:29:35'),
(279, 17, 'Pada framework Laravel, apa solusi terbaik untuk mengatasi masalah query performa \"N+1 Problem\" ketika mengambil relasi data mahasiswa beserta daftar portofolionya?', 'hard_skill', 'ORM & Database Performance', '{\"A\":\"Menonaktifkan relasi foreign key pada migrasi database\",\"B\":\"Menggunakan Eager Loading dengan method User::with(\'portfolios\')->get()\",\"C\":\"Melakukan query di dalam perulangan foreach blade template\",\"D\":\"Mengubah tipe basis data menjadi NoSQL MongoDB\"}', 'B', 'D', 0, 'Eager Loading mengambil semua relasi terkait hanya dalam 1-2 query SQL gabungan, mencegah query berulang sebanyak N baris data.', '2026-10-08 03:28:38', '2026-10-08 03:29:35'),
(280, 17, 'Setelah insiden downtime sistem berhasil dipulihkan, tim mengadakan rapat \"Blameless Post-Mortem\". Apa tujuan utama dari rapat ini?', 'soft_skill', 'Budaya Teknik & Retrospektif', '{\"A\":\"Memperdebatkan siapa yang paling berjasa memulihkan sistem\",\"B\":\"Mencari satu orang untuk dijatuhi sanksi dan disalahkan atas insiden\",\"C\":\"Menghapus log error agar reputasi tim tidak terlihat buruk\",\"D\":\"Mengidentifikasi akar penyebab sistemik (Root Cause) dan merancang mitigasi pencegahan agar insiden serupa tidak terulang\"}', 'D', 'D', 1, 'Blameless post-mortem mengasumsikan kesalahan terjadi akibat kelemahan sistem dan prosedur, bukan kelalaian jahat individu.', '2026-10-08 03:28:38', '2026-10-08 03:29:35'),
(281, 17, 'Dalam prinsip transaksi ACID pada basis data relasional, apa yang dimaksud dengan sifat \"Atomicity\"?', 'hard_skill', 'Database Transaction (ACID)', '{\"A\":\"Setiap tabel harus memiliki minimal 10 indeks kolom\",\"B\":\"Database tidak boleh diakses oleh lebih dari satu pengguna dalam satu detik\",\"C\":\"Data disimpan dalam partisi atomik memori cache RAM\",\"D\":\"Semua operasi dalam satu transaksi harus berhasil sepenuhnya, jika satu gagal maka seluruh transaksi dibatalkan (Rollback)\"}', 'D', 'D', 1, 'Atomicity menjamin prinsip \"all or nothing\", mencegah inkonsistensi data parsial saat terjadi gangguan server.', '2026-10-08 03:28:38', '2026-10-08 03:29:35'),
(282, 17, 'Dalam prinsip SOLID, prinsip \"Dependency Inversion Principle\" (DIP) menyatakan bahwa:', 'hard_skill', 'Clean Code & Desain Perangkat Lunak', '{\"A\":\"Variabel harus dideklarasikan terbalik dari urutan eksekusi\",\"B\":\"Database tidak boleh memiliki relasi tabel antar entitas\",\"C\":\"Modul tingkat tinggi tidak boleh bergantung pada modul tingkat rendah; keduanya harus bergantung pada abstraksi (interface)\",\"D\":\"Semua fungsi harus ditulis dalam satu file class besar\"}', 'C', 'C', 1, 'DIP memisahkan implementasi konkret melalui interface sehingga kode mudah diuji (mocking) dan fleksibel diubah.', '2026-10-08 03:28:38', '2026-10-08 03:29:35'),
(283, 17, 'Pada protokol HTTPS, bagaimana proses pertukaran kunci enkripsi terjadi saat proses TLS Handshake awal?', 'hard_skill', 'Jaringan & Kriptografi', '{\"A\":\"Mengabaikan sertifikat SSL jika domain tidak cocok\",\"B\":\"Hanya menggunakan algoritma hashing MD5 satu arah\",\"C\":\"Mengirimkan password database secara plaintext\",\"D\":\"Menggunakan kriptografi asimetris (Public\\/Private Key) untuk menyepakati Symmetric Session Key yang efisien\"}', 'D', 'D', 1, 'TLS menggunakan asimetris untuk autentikasi dan negosiasi kunci, kemudian menggunakan simetris untuk enkripsi data berkecepatan tinggi.', '2026-10-08 03:28:38', '2026-10-08 03:29:35'),
(284, 17, 'Kapan arsitektur basis data NoSQL tipe Dokumen (seperti MongoDB) lebih diutamakan dibandingkan SQL Relasional tradisional?', 'hard_skill', 'Database Architecture', '{\"A\":\"Saat tidak diperbolehkan menggunakan memori RAM di server\",\"B\":\"Saat skema data bersifat dinamis, tidak terstruktur ketat, dan membutuhkan skalabilitas horizontal cepat\",\"C\":\"Saat membutuhkan integritas transaksi multi-tabel perbankan yang ketat\",\"D\":\"Saat data hanya berjumlah kurang dari 100 baris\"}', 'B', 'B', 1, 'NoSQL dokumen menyimpan data JSON-like polimorfik tanpa perlu migrasi DDL kaku setiap perubahan struktur kolom.', '2026-10-08 03:28:38', '2026-10-08 03:29:35'),
(285, 17, 'Tim backend perlu merilis pembaruan endpoint API yang mengubah format payload response secara signifikan (breaking change). Apa langkah profesional terbaik sebelum perubahan di-deploy?', 'soft_skill', 'Manajemen Rilis & Kolaborasi', '{\"A\":\"Mematikan server mobile secara tiba-tiba agar mereka sadar ada pembaruan\",\"B\":\"Langsung mengubah endpoint v1 di production tanpa pemberitahuan apapun\",\"C\":\"Membuat API versioning baru (misal \\/api\\/v2), mengomunikasikan timeline deprecation ke tim mobile\\/frontend, dan menjaga v1 tetap berjalan sementara\",\"D\":\"Menolak melakukan pembaruan selamanya demi kompatibilitas lama\"}', 'C', 'D', 0, 'Versioning API dan komunikasi transparan melindungi integrasi klien dari kegagalan fungsional yang fatal.', '2026-10-08 03:28:38', '2026-10-08 03:29:35'),
(286, 17, 'Ketika query laporan tracer study pada basis data MySQL yang memiliki 500.000 baris data terasa lambat, optimasi indeks apa yang paling tepat dipasang?', 'hard_skill', 'Database Indexing & Optimization', '{\"A\":\"Menambahkan B-Tree Index pada kolom yang sering digunakan di klausa WHERE dan JOIN\",\"B\":\"Menghapus primary key pada tabel\",\"C\":\"Mengubah semua tipe data VARCHAR menjadi TEXT\",\"D\":\"Melakukan query SELECT * tanpa klausa limit\"}', 'A', 'D', 0, 'Index B-Tree mempercepat pencarian data dari kompleksitas O(N) full table scan menjadi O(log N).', '2026-10-08 03:28:38', '2026-10-08 03:29:35'),
(287, 17, 'Seorang stakeholder non-teknis memberikan kebutuhan aplikasi yang sangat samar: \"Buat sistem yang pintar dan otomatis\". Langkah konkret apa yang harus Anda ambil?', 'soft_skill', 'Komunikasi Kebutuhan Bisnis', '{\"A\":\"Menunggu sampai ada dokumen spesifikasi lengkap setebal 100 halaman\",\"B\":\"Mengajak stakeholder berdiskusi dengan membuat alur use case sederhana, kriteria keberhasilan yang terukur, dan wireframe interaktif\",\"C\":\"Langsung menulis kode rumit berdasarkan asumsi sendiri tanpa konfirmasi\",\"D\":\"Menolak proyek dan mengatakan stakeholder tidak kompeten\"}', 'B', 'D', 0, 'Menerjemahkan ide abstrak menjadi kriteria terukur dan prototipe visual adalah peran kunci perekayasa perangkat lunak.', '2026-10-08 03:28:38', '2026-10-08 03:29:35'),
(288, 17, 'Klien meminta penambahan 3 fitur kompleks baru di tengah sprint yang sudah berjalan dengan batas waktu deadline yang tidak bisa diundur. Bagaimana respons terbaik Anda?', 'soft_skill', 'Manajemen Ekspektasi & Agile', '{\"A\":\"Menghapus pengujian unit dan standar keamanan demi mengejar waktu\",\"B\":\"Mendiskusikan trade-off secara profesional, menetapkan prioritas fitur MVP, dan memindahkan fitur tambahan ke sprint berikutnya\",\"C\":\"Langsung mengiyakan semua permintaan meskipun tahu tim tidak akan sanggup menyelesaikannya\",\"D\":\"Memutus kontak dengan klien dan tidak masuk kerja\"}', 'B', 'D', 0, 'Pengembang profesional mengelola ruang lingkup secara transparan dengan fokus pada nilai bisnis dan viabilitas teknis.', '2026-10-08 03:28:38', '2026-10-08 03:29:35'),
(289, 17, 'Anda menemukan bug kritis di server production tepat 30 menit sebelum jam peluncuran sistem. Sikap profesional rekayasa apa yang paling tepat dilakukan?', 'soft_skill', 'Problem Solving & Insiden Kerja', '{\"A\":\"Mengabaikan bug tersebut dengan harapan tidak ditemukan oleh pengguna\",\"B\":\"Melakukan perubahan langsung di server live tanpa membuat cadangan kode dan database\",\"C\":\"Mengomunikasikan temuan ke tim\\/stakeholder secara transparan, menganalisis risiko, dan menerapkan hotfix teruji atau menunda peluncuran secara aman\",\"D\":\"Menyalahkan rekan tim yang menulis modul tersebut di grup publik\"}', 'C', 'C', 1, 'Integritas teknis dan komunikasi risiko secara objektif merupakan soft-skill paling berharga bagi seorang profesional engineering.', '2026-10-08 03:28:38', '2026-10-08 03:29:35'),
(290, 17, 'Laporan audit keamanan menemukan celah kerentanan kritis kategori High pada dependensi pihak ketiga yang digunakan sistem Anda. Tindakan prioritas tim adalah:', 'soft_skill', 'Manajemen Risiko Keamanan', '{\"A\":\"Menganggap celah keamanan hanya teori dan tidak mungkin diserang hacker nyata\",\"B\":\"Menghapus modul keamanan dari sistem agar audit tidak mendeteksi celah lagi\",\"C\":\"Menunda penanganan celah keamanan selama 6 bulan sampai roadmap fitur selesai\",\"D\":\"Mengevaluasi dampak, memperbarui package ke versi patch terbaru di staging, menjalankan automated test suite, dan segera rilis patch ke production\"}', 'D', 'D', 1, 'Kerentanan kritis pada dependensi harus dimitigasi segera dengan proses verifikasi regresi yang terukur.', '2026-10-08 03:28:38', '2026-10-08 03:29:35'),
(291, 17, 'Berapa kompleksitas waktu rata-rata algoritma Binary Search untuk mencari suatu data pada larik (array) yang sudah terurut sepanjang N elemen?', 'hard_skill', 'Struktur Data & Algoritma', '{\"A\":\"O(N)\",\"B\":\"O(log N)\",\"C\":\"O(N^2)\",\"D\":\"O(1)\"}', 'B', 'D', 0, 'Binary Search membagi ruang pencarian menjadi separuh pada setiap iterasi, menghasilkan kompleksitas logaritmik O(log N).', '2026-10-08 03:28:38', '2026-10-08 03:29:35'),
(292, 17, 'Teknologi protokol apa yang paling efisien untuk mengimplementasikan fitur Dashboard Monitoring Real-Time dengan komunikasi dua arah (full-duplex) tanpa overhead polling berulang?', 'hard_skill', 'Komunikasi Real-time', '{\"A\":\"HTTP Short Polling\",\"B\":\"WebSocket\",\"C\":\"FTP Transfer\",\"D\":\"SMTP Mail Service\"}', 'B', 'D', 0, 'WebSocket mempertahankan koneksi TCP tunggal terbuka secara persisten, memungkinkan push data instan dari server ke klien.', '2026-10-08 03:28:38', '2026-10-08 03:29:35'),
(293, 17, 'Seorang anggota tim junior tampak kesulitan dan frustrasi menyelesaikan tugas modul autentikasi selama 2 hari berturut-turut. Sikap empati teknis apa yang harus ditunjukkan?', 'soft_skill', 'Mentoring & Kerjasama Tim', '{\"A\":\"Memarahi junior tersebut di depan seluruh anggota tim saat stand-up meeting\",\"B\":\"Mengajak berdiskusi santai, melakukan sesi pair-programming untuk memecah masalah menjadi sub-tugas yang lebih kecil, dan memberi bimbingan\",\"C\":\"Membiarkannya sampai deadline lewat agar dia belajar sendiri\",\"D\":\"Mengambil alih tugasnya secara diam-diam tanpa menjelaskan apapun\"}', 'B', 'D', 0, 'Pair-programming dan bimbingan memecah hambatan teknis sekaligus mempercepat transfer pengetahuan dalam tim.', '2026-10-08 03:28:38', '2026-10-08 03:29:35');
INSERT INTO `assessment_questions` (`id`, `assessment_id`, `question_text`, `type`, `topic`, `options`, `correct_option`, `user_answer`, `is_correct`, `explanation`, `created_at`, `updated_at`) VALUES
(294, 17, 'Dalam alur kerja Git kolaboratif tim industri, perintah apa yang digunakan untuk mengambil perubahan terbaru dari remote server sekaligus menggabungkannya ke branch kerja saat ini?', 'hard_skill', 'Git Version Control', '{\"A\":\"git pull\",\"B\":\"git reset --hard\",\"C\":\"git stash drop\",\"D\":\"git push --force\"}', 'A', 'D', 0, 'git pull menjalankan kombinasi git fetch (mengambil data dari remote) dan git merge (menggabungkan ke branch lokal).', '2026-10-08 03:28:38', '2026-10-08 03:29:35'),
(295, 18, 'Seorang anggota tim junior tampak kesulitan dan frustrasi menyelesaikan tugas modul autentikasi selama 2 hari berturut-turut. Sikap empati teknis apa yang harus ditunjukkan?', 'soft_skill', 'Mentoring & Kerjasama Tim', '{\"A\":\"Membiarkannya sampai deadline lewat agar dia belajar sendiri\",\"B\":\"Memarahi junior tersebut di depan seluruh anggota tim saat stand-up meeting\",\"C\":\"Mengajak berdiskusi santai, melakukan sesi pair-programming untuk memecah masalah menjadi sub-tugas yang lebih kecil, dan memberi bimbingan\",\"D\":\"Mengambil alih tugasnya secara diam-diam tanpa menjelaskan apapun\"}', 'C', 'C', 1, 'Pair-programming dan bimbingan memecah hambatan teknis sekaligus mempercepat transfer pengetahuan dalam tim.', '2026-10-09 04:33:10', '2026-10-09 04:34:08'),
(296, 18, 'Ketika query laporan tracer study pada basis data MySQL yang memiliki 500.000 baris data terasa lambat, optimasi indeks apa yang paling tepat dipasang?', 'soft_skill', 'Database Indexing & Optimization', '{\"A\":\"Melakukan query SELECT * tanpa klausa limit\",\"B\":\"Mengubah semua tipe data VARCHAR menjadi TEXT\",\"C\":\"Menambahkan B-Tree Index pada kolom yang sering digunakan di klausa WHERE dan JOIN\",\"D\":\"Menghapus primary key pada tabel\"}', 'C', 'C', 1, 'Index B-Tree mempercepat pencarian data dari kompleksitas O(N) full table scan menjadi O(log N).', '2026-10-09 04:33:10', '2026-10-09 04:34:08'),
(297, 18, 'Seorang stakeholder non-teknis memberikan kebutuhan aplikasi yang sangat samar: \"Buat sistem yang pintar dan otomatis\". Langkah konkret apa yang harus Anda ambil?', 'soft_skill', 'Komunikasi Kebutuhan Bisnis', '{\"A\":\"Menunggu sampai ada dokumen spesifikasi lengkap setebal 100 halaman\",\"B\":\"Mengajak stakeholder berdiskusi dengan membuat alur use case sederhana, kriteria keberhasilan yang terukur, dan wireframe interaktif\",\"C\":\"Langsung menulis kode rumit berdasarkan asumsi sendiri tanpa konfirmasi\",\"D\":\"Menolak proyek dan mengatakan stakeholder tidak kompeten\"}', 'B', 'C', 0, 'Menerjemahkan ide abstrak menjadi kriteria terukur dan prototipe visual adalah peran kunci perekayasa perangkat lunak.', '2026-10-09 04:33:10', '2026-10-09 04:34:08'),
(298, 18, 'Bagaimana strategi tim developer dalam mengelola \"Technical Debt\" (utang teknis) agar aplikasi tetap scalable dalam jangka panjang?', 'soft_skill', 'Manajemen Utang Teknis', '{\"A\":\"Mendokumentasikan technical debt di backlog dan mengalokasikan persentase kapasitas tertentu di tiap sprint untuk refactoring\",\"B\":\"Tidak pernah melakukan refactoring sampai aplikasi benar-benar crash\",\"C\":\"Menyembunyikan kode yang berantakan dengan mengabaikan peringatan linter\",\"D\":\"Menulis ulang seluruh aplikasi dari nol setiap kali ada teknologi framework baru\"}', 'A', 'A', 1, 'Mengalokasikan kapasitas berkala (misal 15-20% per sprint) menjaga keseimbangan antara rilis fitur dan kesehatan basis kode.', '2026-10-09 04:33:10', '2026-10-09 04:34:08'),
(299, 18, 'Dalam prinsip transaksi ACID pada basis data relasional, apa yang dimaksud dengan sifat \"Atomicity\"?', 'hard_skill', 'Database Transaction (ACID)', '{\"A\":\"Setiap tabel harus memiliki minimal 10 indeks kolom\",\"B\":\"Semua operasi dalam satu transaksi harus berhasil sepenuhnya, jika satu gagal maka seluruh transaksi dibatalkan (Rollback)\",\"C\":\"Data disimpan dalam partisi atomik memori cache RAM\",\"D\":\"Database tidak boleh diakses oleh lebih dari satu pengguna dalam satu detik\"}', 'B', 'C', 0, 'Atomicity menjamin prinsip \"all or nothing\", mencegah inkonsistensi data parsial saat terjadi gangguan server.', '2026-10-09 04:33:10', '2026-10-09 04:34:08'),
(300, 18, 'Anda menemukan bug kritis di server production tepat 30 menit sebelum jam peluncuran sistem. Sikap profesional rekayasa apa yang paling tepat dilakukan?', 'soft_skill', 'Problem Solving & Insiden Kerja', '{\"A\":\"Melakukan perubahan langsung di server live tanpa membuat cadangan kode dan database\",\"B\":\"Mengomunikasikan temuan ke tim\\/stakeholder secara transparan, menganalisis risiko, dan menerapkan hotfix teruji atau menunda peluncuran secara aman\",\"C\":\"Menyalahkan rekan tim yang menulis modul tersebut di grup publik\",\"D\":\"Mengabaikan bug tersebut dengan harapan tidak ditemukan oleh pengguna\"}', 'B', 'D', 0, 'Integritas teknis dan komunikasi risiko secara objektif merupakan soft-skill paling berharga bagi seorang profesional engineering.', '2026-10-09 04:33:10', '2026-10-09 04:34:08'),
(301, 18, 'Dalam arsitektur container Docker, apa fungsi utama dari file Dockerfile dalam siklus deployment aplikasi web?', 'hard_skill', 'DevOps & Containerization', '{\"A\":\"Sebagai pengganti compiler bahasa pemrograman\",\"B\":\"Menggantikan fungsi web server Nginx dan Apache\",\"C\":\"Menyimpan password database production secara plaintext\",\"D\":\"Berisi instruksi deklaratif untuk membangun Image aplikasi yang terisolasi dan konsisten di berbagai lingkungan\"}', 'D', 'D', 1, 'Dockerfile mendefinisikan layer sistem operasi dasar, dependensi library, dan konfigurasi runtime untuk menghasilkan Docker Image.', '2026-10-09 04:33:10', '2026-10-09 04:34:08'),
(302, 18, 'Klien meminta penambahan 3 fitur kompleks baru di tengah sprint yang sudah berjalan dengan batas waktu deadline yang tidak bisa diundur. Bagaimana respons terbaik Anda?', 'soft_skill', 'Manajemen Ekspektasi & Agile', '{\"A\":\"Langsung mengiyakan semua permintaan meskipun tahu tim tidak akan sanggup menyelesaikannya\",\"B\":\"Memutus kontak dengan klien dan tidak masuk kerja\",\"C\":\"Mendiskusikan trade-off secara profesional, menetapkan prioritas fitur MVP, dan memindahkan fitur tambahan ke sprint berikutnya\",\"D\":\"Menghapus pengujian unit dan standar keamanan demi mengejar waktu\"}', 'C', 'C', 1, 'Pengembang profesional mengelola ruang lingkup secara transparan dengan fokus pada nilai bisnis dan viabilitas teknis.', '2026-10-09 04:33:10', '2026-10-09 04:34:08'),
(303, 18, 'Berapa kompleksitas waktu rata-rata algoritma Binary Search untuk mencari suatu data pada larik (array) yang sudah terurut sepanjang N elemen?', 'hard_skill', 'Struktur Data & Algoritma', '{\"A\":\"O(N)\",\"B\":\"O(log N)\",\"C\":\"O(1)\",\"D\":\"O(N^2)\"}', 'B', 'A', 0, 'Binary Search membagi ruang pencarian menjadi separuh pada setiap iterasi, menghasilkan kompleksitas logaritmik O(log N).', '2026-10-09 04:33:10', '2026-10-09 04:34:08'),
(304, 18, 'Pada arsitektur sistem berbasis Microservices, pola arsitektur apa yang digunakan untuk mencegah kegagalan satu service merambat (cascading failure) ke seluruh ekosistem aplikasi?', 'hard_skill', 'Arsitektur Microservices', '{\"A\":\"Monolithic Model\",\"B\":\"Circuit Breaker Pattern\",\"C\":\"Direct Synchronous Loop\",\"D\":\"Singleton Pattern\"}', 'B', 'C', 0, 'Circuit Breaker memutus panggilan sementara ke service yang sedang down/timeout dan memberikan fallback response instan.', '2026-10-09 04:33:10', '2026-10-09 04:34:08'),
(305, 18, 'Laporan audit keamanan menemukan celah kerentanan kritis kategori High pada dependensi pihak ketiga yang digunakan sistem Anda. Tindakan prioritas tim adalah:', 'soft_skill', 'Manajemen Risiko Keamanan', '{\"A\":\"Menghapus modul keamanan dari sistem agar audit tidak mendeteksi celah lagi\",\"B\":\"Mengevaluasi dampak, memperbarui package ke versi patch terbaru di staging, menjalankan automated test suite, dan segera rilis patch ke production\",\"C\":\"Menganggap celah keamanan hanya teori dan tidak mungkin diserang hacker nyata\",\"D\":\"Menunda penanganan celah keamanan selama 6 bulan sampai roadmap fitur selesai\"}', 'B', 'D', 0, 'Kerentanan kritis pada dependensi harus dimitigasi segera dengan proses verifikasi regresi yang terukur.', '2026-10-09 04:33:10', '2026-10-09 04:34:08'),
(306, 18, 'Untuk mencegah serangan Cross-Site Scripting (Stored XSS) pada kolom komentar pengguna, mekanisme apa yang wajib diimplementasikan sebelum merender konten ke browser?', 'hard_skill', 'Keamanan Web (OWASP)', '{\"A\":\"Menghapus session cookie setelah 5 detik\",\"B\":\"Mengharuskan pengguna mengunggah file zip\",\"C\":\"Menggunakan protokol HTTP\\/2\",\"D\":\"HTML Entity Encoding \\/ Sanitasi output sehingga tag seperti <script> tidak dieksekusi browser\"}', 'D', 'D', 1, 'Encoding mengonversi karakter berbahaya seperti < dan > menjadi &lt; dan &gt; sehingga browser merendernya sebagai teks biasa.', '2026-10-09 04:33:10', '2026-10-09 04:34:08'),
(307, 18, 'Dalam aplikasi web modern berbasis React / Vue, apa tujuan utama penggunaan Virtual DOM dibandingkan langsung memanipulasi Real DOM browser?', 'hard_skill', 'Modern Frontend Architecture', '{\"A\":\"Mengamankan web dari serangan SQL Injection dan XSS secara penuh\",\"B\":\"Menghitung perbedaan (diffing) di memori dan meminimalkan operasi render reflow\\/repaint pada Real DOM yang mahal\",\"C\":\"Mempercepat transmisi data TCP antara klien dan server\",\"D\":\"Menyimpan seluruh data aplikasi ke dalam LocalStorage secara otomatis\"}', 'B', 'B', 1, 'Virtual DOM membandingkan snapshot pohon DOM sebelum dan sesudah perubahan state, lalu hanya menerapkan perubahan spesifik pada browser.', '2026-10-09 04:33:10', '2026-10-09 04:34:08'),
(308, 18, 'Tim backend perlu merilis pembaruan endpoint API yang mengubah format payload response secara signifikan (breaking change). Apa langkah profesional terbaik sebelum perubahan di-deploy?', 'soft_skill', 'Manajemen Rilis & Kolaborasi', '{\"A\":\"Mematikan server mobile secara tiba-tiba agar mereka sadar ada pembaruan\",\"B\":\"Langsung mengubah endpoint v1 di production tanpa pemberitahuan apapun\",\"C\":\"Menolak melakukan pembaruan selamanya demi kompatibilitas lama\",\"D\":\"Membuat API versioning baru (misal \\/api\\/v2), mengomunikasikan timeline deprecation ke tim mobile\\/frontend, dan menjaga v1 tetap berjalan sementara\"}', 'D', 'D', 1, 'Versioning API dan komunikasi transparan melindungi integrasi klien dari kegagalan fungsional yang fatal.', '2026-10-09 04:33:10', '2026-10-09 04:34:08'),
(309, 18, 'Teknologi protokol apa yang paling efisien untuk mengimplementasikan fitur Dashboard Monitoring Real-Time dengan komunikasi dua arah (full-duplex) tanpa overhead polling berulang?', 'hard_skill', 'Komunikasi Real-time', '{\"A\":\"FTP Transfer\",\"B\":\"HTTP Short Polling\",\"C\":\"WebSocket\",\"D\":\"SMTP Mail Service\"}', 'C', 'D', 0, 'WebSocket mempertahankan koneksi TCP tunggal terbuka secara persisten, memungkinkan push data instan dari server ke klien.', '2026-10-09 04:33:10', '2026-10-09 04:34:08'),
(310, 18, 'Struktur standar JSON Web Token (JWT) terdiri dari tiga bagian yang dipisahkan tanda titik (.):', 'hard_skill', 'Autentikasi & Otorisasi Modern', '{\"A\":\"Protocol.Domain.Port\",\"B\":\"Encryption.Salt.Hash\",\"C\":\"Header.Payload.Signature\",\"D\":\"User.Password.Token\"}', 'C', 'D', 0, 'Header berisi tipe token dan algoritma enkripsi, Payload berisi klaim data, dan Signature memverifikasi keaslian token.', '2026-10-09 04:33:10', '2026-10-09 04:34:08'),
(311, 18, 'Kapan arsitektur basis data NoSQL tipe Dokumen (seperti MongoDB) lebih diutamakan dibandingkan SQL Relasional tradisional?', 'hard_skill', 'Database Architecture', '{\"A\":\"Saat skema data bersifat dinamis, tidak terstruktur ketat, dan membutuhkan skalabilitas horizontal cepat\",\"B\":\"Saat tidak diperbolehkan menggunakan memori RAM di server\",\"C\":\"Saat data hanya berjumlah kurang dari 100 baris\",\"D\":\"Saat membutuhkan integritas transaksi multi-tabel perbankan yang ketat\"}', 'A', 'A', 1, 'NoSQL dokumen menyimpan data JSON-like polimorfik tanpa perlu migrasi DDL kaku setiap perubahan struktur kolom.', '2026-10-09 04:33:10', '2026-10-09 04:34:08'),
(312, 18, 'Setelah insiden downtime sistem berhasil dipulihkan, tim mengadakan rapat \"Blameless Post-Mortem\". Apa tujuan utama dari rapat ini?', 'soft_skill', 'Budaya Teknik & Retrospektif', '{\"A\":\"Memperdebatkan siapa yang paling berjasa memulihkan sistem\",\"B\":\"Menghapus log error agar reputasi tim tidak terlihat buruk\",\"C\":\"Mencari satu orang untuk dijatuhi sanksi dan disalahkan atas insiden\",\"D\":\"Mengidentifikasi akar penyebab sistemik (Root Cause) dan merancang mitigasi pencegahan agar insiden serupa tidak terulang\"}', 'D', 'D', 1, 'Blameless post-mortem mengasumsikan kesalahan terjadi akibat kelemahan sistem dan prosedur, bukan kelalaian jahat individu.', '2026-10-09 04:33:10', '2026-10-09 04:34:08'),
(313, 18, 'Pada framework Laravel, apa solusi terbaik untuk mengatasi masalah query performa \"N+1 Problem\" ketika mengambil relasi data mahasiswa beserta daftar portofolionya?', 'hard_skill', 'ORM & Database Performance', '{\"A\":\"Menggunakan Eager Loading dengan method User::with(\'portfolios\')->get()\",\"B\":\"Melakukan query di dalam perulangan foreach blade template\",\"C\":\"Menonaktifkan relasi foreign key pada migrasi database\",\"D\":\"Mengubah tipe basis data menjadi NoSQL MongoDB\"}', 'A', 'D', 0, 'Eager Loading mengambil semua relasi terkait hanya dalam 1-2 query SQL gabungan, mencegah query berulang sebanyak N baris data.', '2026-10-09 04:33:10', '2026-10-09 04:34:08'),
(314, 18, 'Ketika melakukan Code Review pada pull request rekan satu tim, Anda menemukan pendekatan kode yang berbeda dengan gaya Anda namun tetap benar dan efisien. Tindakan terbaik Anda adalah:', 'soft_skill', 'Kolaborasi & Code Review', '{\"A\":\"Mengubah kode rekan kerja secara sepihak tanpa izin\",\"B\":\"Menolak PR dan memaksakan gaya koding pribadi Anda\",\"C\":\"Mengabaikan PR tersebut tanpa memberikan review selama berhari-hari\",\"D\":\"Menyetujui PR jika memenuhi standar arsitektur tim dan uji unit lulus, sambil memberikan saran konstruktif opsional\"}', 'D', 'D', 1, 'Code review berfokus pada kualitas, kebenaran, dan keterbacaan kode tim, bukan preferensi gaya personal penguji.', '2026-10-09 04:33:10', '2026-10-09 04:34:08'),
(315, 19, 'Dalam perancangan catu daya sistem elektronika, apa keunggulan utama regulator switching tipe Buck Converter dibandingkan regulator linier seri LM7805 saat menurunkan tegangan dari 24V DC ke 5V DC?', 'hard_skill', 'Elektronika Daya & Regulator', '{\"A\":\"Buck converter sama sekali tidak menghasilkan noise switching\",\"B\":\"Efisiensi konversi daya sangat tinggi (85-95%) sehingga disipasi panas minimal tanpa perlu pendingin besar\",\"C\":\"Buck converter hanya bisa digunakan untuk arus di bawah 1 miliampere\",\"D\":\"Buck converter menghasilkan biaya komponen yang selalu lebih murah\"}', 'B', 'B', 1, 'Regulator linier mendisipasikan kelebihan tegangan (24V - 5V = 19V) sebagai panas murni, sementara buck converter bekerja dengan efisiensi tinggi.', '2026-11-03 00:02:25', '2026-11-03 00:03:54'),
(316, 19, 'Saat merakit prototipe papan sirkuit baru di laboratorium, tim mendapati salah satu IC regulator mengeluarkan asap akibat polaritas catu daya terbalik. Sikap kerja standar apa yang harus diambil?', 'soft_skill', 'Keselamatan Kerja & Prosedur Lab', '{\"A\":\"Menyiram papan sirkuit dengan air saat masih terhubung ke listrik PLN\",\"B\":\"Menyembunyikan komponen yang terbakar dan pura-pura tidak tahu\",\"C\":\"Terus menaikkan voltase daya untuk melihat apa yang akan terjadi selanjutnya\",\"D\":\"Segera putuskan sumber daya listrik, evaluasi kerusakan, periksa skema proteksi polaritas terbalik, dan catat temuan untuk revisi PCB\"}', 'D', 'D', 1, 'Keselamatan laboratorium menuntut pemutusan daya segera, identifikasi akar masalah (menambahkan dioda reverse polarity), dan dokumentasi insiden.', '2026-11-03 00:02:25', '2026-11-03 00:03:54'),
(317, 19, 'Kapan arsitektur basis data NoSQL tipe Dokumen (seperti MongoDB) lebih diutamakan dibandingkan SQL Relasional tradisional?', 'hard_skill', 'Database Architecture', '{\"A\":\"Saat skema data bersifat dinamis, tidak terstruktur ketat, dan membutuhkan skalabilitas horizontal cepat\",\"B\":\"Saat tidak diperbolehkan menggunakan memori RAM di server\",\"C\":\"Saat data hanya berjumlah kurang dari 100 baris\",\"D\":\"Saat membutuhkan integritas transaksi multi-tabel perbankan yang ketat\"}', 'A', 'A', 1, 'NoSQL dokumen menyimpan data JSON-like polimorfik tanpa perlu migrasi DDL kaku setiap perubahan struktur kolom.', '2026-11-03 00:02:25', '2026-11-03 00:03:54'),
(318, 19, 'Dalam aplikasi web modern berbasis React / Vue, apa tujuan utama penggunaan Virtual DOM dibandingkan langsung memanipulasi Real DOM browser?', 'hard_skill', 'Modern Frontend Architecture', '{\"A\":\"Mempercepat transmisi data TCP antara klien dan server\",\"B\":\"Menghitung perbedaan (diffing) di memori dan meminimalkan operasi render reflow\\/repaint pada Real DOM yang mahal\",\"C\":\"Menyimpan seluruh data aplikasi ke dalam LocalStorage secara otomatis\",\"D\":\"Mengamankan web dari serangan SQL Injection dan XSS secara penuh\"}', 'B', 'B', 1, 'Virtual DOM membandingkan snapshot pohon DOM sebelum dan sesudah perubahan state, lalu hanya menerapkan perubahan spesifik pada browser.', '2026-11-03 00:02:25', '2026-11-03 00:03:54'),
(319, 19, 'Dalam protokol komunikasi MQTT yang sering digunakan pada IoT, peran apa yang berfungsi sebagai perantara penerima dan penyalur pesan antara publisher dan subscriber?', 'hard_skill', 'Protokol Komunikasi IoT', '{\"A\":\"Payload Serializer\",\"B\":\"MQTT Broker\",\"C\":\"Edge Gateway Node\",\"D\":\"DNS Server\"}', 'B', 'B', 1, 'MQTT Broker bertanggung jawab menerima semua pesan dari publisher, menyaring berdasarkan topik, dan mengirimkan ke semua subscriber yang berlangganan.', '2026-11-03 00:02:25', '2026-11-03 00:03:54'),
(320, 19, 'Setelah insiden downtime sistem berhasil dipulihkan, tim mengadakan rapat \"Blameless Post-Mortem\". Apa tujuan utama dari rapat ini?', 'soft_skill', 'Budaya Teknik & Retrospektif', '{\"A\":\"Mencari satu orang untuk dijatuhi sanksi dan disalahkan atas insiden\",\"B\":\"Memperdebatkan siapa yang paling berjasa memulihkan sistem\",\"C\":\"Menghapus log error agar reputasi tim tidak terlihat buruk\",\"D\":\"Mengidentifikasi akar penyebab sistemik (Root Cause) dan merancang mitigasi pencegahan agar insiden serupa tidak terulang\"}', 'D', 'D', 1, 'Blameless post-mortem mengasumsikan kesalahan terjadi akibat kelemahan sistem dan prosedur, bukan kelalaian jahat individu.', '2026-11-03 00:02:25', '2026-11-03 00:03:54'),
(321, 19, 'Apa keuntungan mengimplementasikan model Machine Learning berbasis TinyML terkuantisasi (INT8) langsung di tingkat edge mikrokontroler?', 'hard_skill', 'Edge AI & TinyML', '{\"A\":\"Dapat melatih model GPT-4 dari awal di dalam chip mikrokontroler\",\"B\":\"Menghilangkan kebutuhan baterai pada alat\",\"C\":\"Pengambilan keputusan real-time tanpa latensi internet, hemat bandwidth, dan data sensor sensitif tetap berada di perangkat lokal\",\"D\":\"Mengubah mikrokontroler menjadi superkomputer cloud\"}', 'C', 'C', 1, 'Inference di edge menghilangkan ketergantungan konektivitas cloud dan memungkinkan proteksi privasi serta respon milidetik.', '2026-11-03 00:02:25', '2026-11-03 00:03:54'),
(322, 19, 'Pada protokol HTTPS, bagaimana proses pertukaran kunci enkripsi terjadi saat proses TLS Handshake awal?', 'hard_skill', 'Jaringan & Kriptografi', '{\"A\":\"Mengirimkan password database secara plaintext\",\"B\":\"Mengabaikan sertifikat SSL jika domain tidak cocok\",\"C\":\"Menggunakan kriptografi asimetris (Public\\/Private Key) untuk menyepakati Symmetric Session Key yang efisien\",\"D\":\"Hanya menggunakan algoritma hashing MD5 satu arah\"}', 'C', 'C', 1, 'TLS menggunakan asimetris untuk autentikasi dan negosiasi kunci, kemudian menggunakan simetris untuk enkripsi data berkecepatan tinggi.', '2026-11-03 00:02:25', '2026-11-03 00:03:54'),
(323, 19, 'Di tengah proses produksi massal perangkat otomasi, pabrik komponen mengumumkan bahwa chip mikrokontroler utama discontinue (EOL). Bagaimana keputusan rekayasa terbaik tim?', 'soft_skill', 'Manajemen Rantai Pasok Hardware', '{\"A\":\"Mengabaikan kabar tersebut dan berharap pabrik membuat pengecualian\",\"B\":\"Membeli komponen bekas rusak dari sumber tidak jelas tanpa verifikasi datasheet\",\"C\":\"Menghentikan seluruh bisnis perusahaan dan membatalkan pesanan klien secara permanen\",\"D\":\"Mencari chip alternatif pin-to-pin compatible atau merancang ulang layout PCB minimal dengan chip yang memiliki ketersediaan pasokan jangka panjang\"}', 'D', 'D', 1, 'Ketahanan desain perangkat keras dinilai dari kemampuan rekayasawan beradaptasi terhadap ketersediaan komponen rantai pasok global.', '2026-11-03 00:02:25', '2026-11-03 00:03:54'),
(324, 19, 'Klien meminta penambahan 3 fitur kompleks baru di tengah sprint yang sudah berjalan dengan batas waktu deadline yang tidak bisa diundur. Bagaimana respons terbaik Anda?', 'soft_skill', 'Manajemen Ekspektasi & Agile', '{\"A\":\"Memutus kontak dengan klien dan tidak masuk kerja\",\"B\":\"Menghapus pengujian unit dan standar keamanan demi mengejar waktu\",\"C\":\"Mendiskusikan trade-off secara profesional, menetapkan prioritas fitur MVP, dan memindahkan fitur tambahan ke sprint berikutnya\",\"D\":\"Langsung mengiyakan semua permintaan meskipun tahu tim tidak akan sanggup menyelesaikannya\"}', 'C', 'C', 1, 'Pengembang profesional mengelola ruang lingkup secara transparan dengan fokus pada nilai bisnis dan viabilitas teknis.', '2026-11-03 00:02:25', '2026-11-03 00:03:54'),
(325, 19, 'Setelah terjadi insiden konveyor otomatis pabrik berhenti mendadak akibat sensor photo-electric tertutup debu tebal, rekomendasi preventif menyeluruh apa yang perlu diberikan ke manajemen pabrik?', 'soft_skill', 'Pemeliharaan Preventif & SOP', '{\"A\":\"Tidak melakukan apapun karena mesin sudah berjalan normal kembali\",\"B\":\"Melepas semua sensor keselamatan dan mengoperasikan mesin secara manual dengan risiko tinggi\",\"C\":\"Menetapkan jadwal rutin pembersihan sensor pada checklist harian operator dan menambahkan sensor redundan dengan logika peringatan dini degradasi sinyal\",\"D\":\"Menyalahkan debu pabrik dan menuntut agar seluruh pabrik beroperasi tanpa debu sama sekali\"}', 'C', 'C', 1, 'Pencegahan jangka panjang melibatkan pemeliharaan preventif berjadwal serta perancangan sistem peringatan dini (predictive maintenance).', '2026-11-03 00:02:25', '2026-11-03 00:03:54'),
(326, 19, 'Sebuah tim teknisi pemula kesulitan melakukan flashing firmware baru ke perangkat PLC dan modul IoT di pabrik cabang. Cara terbaik membimbing mereka dari kantor pusat adalah:', 'soft_skill', 'Knowledge Transfer & Dokumentasi', '{\"A\":\"Menyediakan panduan visual SOP langkah demi langkah (Standard Operating Procedure), video demonstrasi, dan mengadakan sesi remote support\",\"B\":\"Menyuruh mereka membaca manual teknis 500 halaman dalam bahasa asing tanpa bimbingan\",\"C\":\"Mengatakan bahwa mereka tidak kompeten sebagai teknisi\",\"D\":\"Menghapus hak akses teknisi tersebut dari sistem\"}', 'A', 'A', 1, 'Transfer keahlian yang terstruktur dengan media panduan visual dan pendampingan memperkuat kemandirian operasional tim lapangan.', '2026-11-03 00:02:25', '2026-11-03 00:03:54'),
(327, 19, 'Pada sistem otomasi industri berbasis PLC (Programmable Logic Controller), instruksi Ladder Diagram apa yang digunakan untuk mengunci output agar tetap aktif meskipun tombol push-button start telah dilepas?', 'hard_skill', 'Logika PLC & Otomasi', '{\"A\":\"Timer On-Delay (TON)\",\"B\":\"Comparator EQU\",\"C\":\"Counter Up (CTU)\",\"D\":\"Rangkaian Latching (Self-Holding Contact)\"}', 'D', 'D', 1, 'Latching memasang kontak normally-open milik coil output secara paralel dengan tombol start untuk menjaga loop sinyal tetap tertutup.', '2026-11-03 00:02:25', '2026-11-03 00:03:54'),
(328, 19, 'Klien menginginkan perangkat pelacak hewan ternak berbasis baterai koin kecil dapat menyala selama 5 tahun terus-menerus sambil mengirim data GPS setiap 1 detik. Bagaimana cara menjelaskan realitas teknis kepadanya?', 'soft_skill', 'Manajemen Ekspektasi Klien', '{\"A\":\"Menyetujui permintaan klien dan berjanji palsu alat akan tahan 5 tahun\",\"B\":\"Mengatakan klien bodoh karena tidak mengerti hukum fisika\",\"C\":\"Menyajikan lembar kalkulasi power budget (kapasitas baterai mAh vs konsumsi arus modul GPS\\/transmisi) dan menawarkan kompromi duty cycle interval transmisi\",\"D\":\"Membeli baterai biasa dan menempelkan stiker \\\"Baterai 5 Tahun\\\"\"}', 'C', 'C', 1, 'Edukasi klien dengan kalkulasi ilmiah dan penawaran opsi kompromi (misal: deep sleep dengan transmisi tiap 30 menit) adalah tanda profesionalisme.', '2026-11-03 00:02:25', '2026-11-03 00:03:54'),
(329, 19, 'Anda menemukan bug kritis di server production tepat 30 menit sebelum jam peluncuran sistem. Sikap profesional rekayasa apa yang paling tepat dilakukan?', 'soft_skill', 'Problem Solving & Insiden Kerja', '{\"A\":\"Menyalahkan rekan tim yang menulis modul tersebut di grup publik\",\"B\":\"Mengomunikasikan temuan ke tim\\/stakeholder secara transparan, menganalisis risiko, dan menerapkan hotfix teruji atau menunda peluncuran secara aman\",\"C\":\"Mengabaikan bug tersebut dengan harapan tidak ditemukan oleh pengguna\",\"D\":\"Melakukan perubahan langsung di server live tanpa membuat cadangan kode dan database\"}', 'B', 'B', 1, 'Integritas teknis dan komunikasi risiko secara objektif merupakan soft-skill paling berharga bagi seorang profesional engineering.', '2026-11-03 00:02:25', '2026-11-03 00:03:54'),
(330, 19, 'Manakah langkah proteksi paling mendasar dan efektif untuk mencegah kerentanan SQL Injection pada aplikasi web?', 'hard_skill', 'Keamanan Perangkat Lunak', '{\"A\":\"Menonaktifkan firewall pada server database\",\"B\":\"Menggunakan Parameterized Queries atau Prepared Statements yang memisahkan instruksi SQL dari data masukan pengguna\",\"C\":\"Menyimpan data password menggunakan enkripsi Base64\",\"D\":\"Mengubah port default web server dari port 80 menjadi port 8080\"}', 'B', 'B', 1, 'Prepared statements memastikan parameter input diperlakukan murni sebagai data literal, bukan sebagai kode SQL executable.', '2026-11-03 00:02:25', '2026-11-03 00:03:54'),
(331, 19, 'Tim backend perlu merilis pembaruan endpoint API yang mengubah format payload response secara signifikan (breaking change). Apa langkah profesional terbaik sebelum perubahan di-deploy?', 'soft_skill', 'Manajemen Rilis & Kolaborasi', '{\"A\":\"Membuat API versioning baru (misal \\/api\\/v2), mengomunikasikan timeline deprecation ke tim mobile\\/frontend, dan menjaga v1 tetap berjalan sementara\",\"B\":\"Langsung mengubah endpoint v1 di production tanpa pemberitahuan apapun\",\"C\":\"Menolak melakukan pembaruan selamanya demi kompatibilitas lama\",\"D\":\"Mematikan server mobile secara tiba-tiba agar mereka sadar ada pembaruan\"}', 'A', 'A', 1, 'Versioning API dan komunikasi transparan melindungi integrasi klien dari kegagalan fungsional yang fatal.', '2026-11-03 00:02:25', '2026-11-03 00:03:54'),
(332, 19, 'Laporan audit keamanan menemukan celah kerentanan kritis kategori High pada dependensi pihak ketiga yang digunakan sistem Anda. Tindakan prioritas tim adalah:', 'soft_skill', 'Manajemen Risiko Keamanan', '{\"A\":\"Menghapus modul keamanan dari sistem agar audit tidak mendeteksi celah lagi\",\"B\":\"Menunda penanganan celah keamanan selama 6 bulan sampai roadmap fitur selesai\",\"C\":\"Mengevaluasi dampak, memperbarui package ke versi patch terbaru di staging, menjalankan automated test suite, dan segera rilis patch ke production\",\"D\":\"Menganggap celah keamanan hanya teori dan tidak mungkin diserang hacker nyata\"}', 'C', 'C', 1, 'Kerentanan kritis pada dependensi harus dimitigasi segera dengan proses verifikasi regresi yang terukur.', '2026-11-03 00:02:25', '2026-11-03 00:03:54'),
(333, 19, 'Untuk mencegah serangan Cross-Site Scripting (Stored XSS) pada kolom komentar pengguna, mekanisme apa yang wajib diimplementasikan sebelum merender konten ke browser?', 'hard_skill', 'Keamanan Web (OWASP)', '{\"A\":\"Menghapus session cookie setelah 5 detik\",\"B\":\"Mengharuskan pengguna mengunggah file zip\",\"C\":\"Menggunakan protokol HTTP\\/2\",\"D\":\"HTML Entity Encoding \\/ Sanitasi output sehingga tag seperti <script> tidak dieksekusi browser\"}', 'D', 'D', 1, 'Encoding mengonversi karakter berbahaya seperti < dan > menjadi &lt; dan &gt; sehingga browser merendernya sebagai teks biasa.', '2026-11-03 00:02:25', '2026-11-03 00:03:54'),
(334, 19, 'Dalam perancangan osilator mikrokontroler, mengapa kristal osilator eksternal lebih disukai dibandingkan osilator RC internal untuk komunikasi UART berkecepatan tinggi?', 'hard_skill', 'Pewaktuan & Osilator Mikrokontroler', '{\"A\":\"Kristal memiliki toleransi frekuensi sangat presisi (ppm) dan stabil terhadap fluktuasi suhu sehingga baud rate tidak melenceng\",\"B\":\"Kristal dapat menyimpan data firmware saat listrik mati\",\"C\":\"Osilator internal tidak bisa menghasilkan frekuensi lebih dari 10 Hz\",\"D\":\"Kristal menghasilkan tegangan listrik sendiri tanpa konsumsi arus\"}', 'A', 'A', 1, 'Pergeseran frekuensi pada RC internal akibat suhu dapat memicu framing error pada komunikasi serial asinkron (UART).', '2026-11-03 00:02:25', '2026-11-03 00:03:54');
