INSERT INTO `career_roadmaps` (`id`, `user_id`, `occupation_id`, `milestone_title`, `stage_order`, `description`, `action_items`, `is_completed`, `created_at`, `updated_at`) VALUES
(1, 2, 1, 'Tahap 1: Penguatan Fundamental & Standar Industri', 1, 'Fokus menutup celah kompetensi utama pada modul Laravel & RESTful API Architecture.', '[{\"task\":\"Pelajari materi kurikulum standar tentang Laravel & RESTful API Architecture\",\"status\":\"completed\"},{\"task\":\"Selesaikan latihan studi kasus praktis di lab kampus\",\"status\":\"pending\"},{\"task\":\"Ikuti kuis pemahaman topik fundamental\",\"status\":\"pending\"}]', 0, '2026-09-20 07:56:18', '2026-09-30 12:42:34'),
(2, 2, 1, 'Tahap 2: Implementasi Proyek Portofolio Terpandu', 2, 'Membangun proyek nyata berstandar industri untuk posisi Full Stack Web Developer.', '[{\"task\":\"Rancang arsitektur aplikasi\\/sistem portofolio baru\",\"status\":\"pending\"},{\"task\":\"Unggah kode sumber ke GitHub dengan dokumentasi README rapi\",\"status\":\"pending\"},{\"task\":\"Daftarkan proyek baru ke menu Portofolio platform\",\"status\":\"pending\"}]', 0, '2026-09-20 07:56:18', '2026-09-20 07:56:18'),
