INSERT INTO `occupations` (`id`, `title`, `field`, `category`, `description`, `average_salary`, `demand_level`, `created_at`, `updated_at`) VALUES
(1, 'Full Stack Web Developer', 'it', 'Software Engineering', 'Merancang dan mengembangkan aplikasi web modern dari antarmuka pengguna responsif hingga arsitektur backend, basis data, dan API yang skalabel.', 'Rp 8.000.000 - Rp 16.000.000', 'Sangat Tinggi', '2026-09-20 07:39:31', '2026-09-20 07:39:31'),
(2, 'Data Analyst & Business Intelligence', 'it', 'Data & Analytics', 'Mengolah big data, membangun model analitik, dan menyajikan visualisasi dashboard interaktif untuk mendukung keputusan strategis bisnis.', 'Rp 8.000.000 - Rp 15.000.000', 'Sangat Tinggi', '2026-09-20 07:39:31', '2026-09-20 07:39:31'),
(3, 'Cloud & DevOps Infrastructure Engineer', 'it', 'Infrastructure & Cloud', 'Mengotomatisasi pipeline CI/CD, mengelola arsitektur cloud server, dan memastikan ketersediaan tinggi sistem 24/7.', 'Rp 9.000.000 - Rp 18.000.000', 'Sangat Tinggi', '2026-09-20 07:39:32', '2026-09-20 10:24:46'),
(4, 'Embedded Systems & Firmware Engineer', 'elektro', 'Sistem Tertanam', 'Merancang perangkat keras mikrokontroler dan menulis kode firmware efisien tingkat rendah untuk sistem otomasi, otomotif, dan perangkat pintar.', 'Rp 8.500.000 - Rp 16.500.000', 'Sangat Tinggi', '2026-09-20 07:39:32', '2026-09-20 07:39:32'),
(5, 'IoT & Smart Device Solutions Specialist', 'elektro', 'Internet of Things', 'Mengintegrasikan sensor fisik, modul komunikasi nirkabel jarak jauh, dan platform cloud untuk monitoring telemetri dan smart instrumentation.', 'Rp 8.000.000 - Rp 15.500.000', 'Sangat Tinggi', '2026-09-20 07:39:32', '2026-09-20 10:24:47'),
(6, 'PLC & Industrial Automation Specialist', 'elektro', 'Otomasi Industri', 'Mengembangkan program kontrol mesin industri menggunakan PLC, sistem kendali terdistribusi, serta perancangan antarmuka visual HMI/SCADA.', 'Rp 8.500.000 - Rp 17.000.000', 'Sangat Tinggi', '2026-09-20 07:39:32', '2026-09-20 10:24:47'),
(7, 'Frontend Web & Mobile Engineer', 'it', 'Frontend Development', 'Membangun pengalaman antarmuka web interaktif berkinerja tinggi, ramah SEO, dan adaptif untuk perangkat desktop maupun seluler.', 'Rp 7.500.000 - Rp 15.000.000', 'Sangat Tinggi', '2026-09-20 10:24:46', '2026-09-20 10:24:46'),
(8, 'Backend & API Systems Engineer', 'it', 'Backend Engineering', 'Fokus pada keandalan logika bisnis server, pemrosesan transaksi data berskala besar, caching, dan arsitektur microservices berkecepatan tinggi.', 'Rp 8.500.000 - Rp 17.000.000', 'Sangat Tinggi', '2026-09-20 10:24:46', '2026-09-20 10:24:46'),
(9, 'Mobile Application Developer (Flutter & Android)', 'it', 'Mobile Development', 'Mengembangkan aplikasi seluler native dan cross-platform yang mulus, stabil, dan terintegrasi dengan berbagai layanan cloud API.', 'Rp 8.000.000 - Rp 16.000.000', 'Tinggi', '2026-09-20 10:24:46', '2026-09-20 10:24:46'),
(10, 'Data Engineer & Big Data Specialist', 'it', 'Data Engineering', 'Merancang arsitektur pipeline data terdistribusi (ETL), data warehouse, dan streaming data real-time untuk kebutuhan AI & Business Intelligence.', 'Rp 9.500.000 - Rp 19.000.000', 'Sangat Tinggi', '2026-09-20 10:24:46', '2026-09-20 10:24:46'),
(11, 'Cyber Security & Penetration Tester', 'it', 'Keamanan Informasi', 'Mengevaluasi kerentanan keamanan infrastruktur web & jaringan, melakukan penetration testing etis, dan merancang mitigasi insiden siber.', 'Rp 9.500.000 - Rp 19.500.000', 'Sangat Tinggi', '2026-09-20 10:24:46', '2026-09-20 10:24:46'),
(12, 'UI/UX Designer & Product Specialist', 'it', 'Product Design', 'Riset kebutuhan pengguna, merancang wireframe, user flow interaktif, dan Design System standar industri dengan Figma.', 'Rp 7.000.000 - Rp 14.000.000', 'Tinggi', '2026-09-20 10:24:47', '2026-09-20 10:24:47'),
(13, 'Machine Learning & AI Solutions Engineer', 'it', 'Artificial Intelligence', 'Mengembangkan model pembelajaran mesin, pemrosesan bahasa alami (NLP), integrasi LLM (Gemini/OpenAI), dan pipeline inferensi AI.', 'Rp 10.000.000 - Rp 22.000.000', 'Sangat Tinggi', '2026-09-20 10:24:47', '2026-09-20 10:24:47'),
(14, 'Quality Assurance (QA) & Automation Tester', 'it', 'Software Quality', 'Menulis skenario pengujian otomatis, memverifikasi fungsionalitas end-to-end, dan memastikan keandalan produk sebelum rilis ke pengguna.', 'Rp 7.000.000 - Rp 14.500.000', 'Tinggi', '2026-09-20 10:24:47', '2026-09-20 10:24:47'),
(15, 'Network Engineer & Systems Administrator', 'it', 'Jaringan & Infrastruktur', 'Mengonfigurasi perangkat router/switch jaringan enterprise, merancang topologi LAN/WAN/VLAN aman, dan mengelola server virtual.', 'Rp 7.500.000 - Rp 15.000.000', 'Tinggi', '2026-09-20 10:24:47', '2026-09-20 10:24:47'),
(16, 'Hardware & PCB Design Engineer', 'elektro', 'Desain Perangkat Keras', 'Merancang skematik sirkuit elektronika, tata letak multi-layer PCB dengan Altium/KiCad, routing sinyal frekuensi tinggi, dan verifikasi prototipe.', 'Rp 8.000.000 - Rp 16.500.000', 'Tinggi', '2026-09-20 10:24:47', '2026-09-20 10:24:47'),
(17, 'Robotics & Mechatronics Systems Engineer', 'elektro', 'Robotika & Mekatronika', 'Mengintegrasikan mekanisme mekanik, motor servo/stepper presisi tinggi, sensor vision, dan algoritma kontrol navigasi robotika otonom.', 'Rp 9.000.000 - Rp 18.500.000', 'Tinggi', '2026-09-20 10:24:47', '2026-09-20 10:24:47'),
(18, 'Electrical Power & Renewable Energy Engineer', 'elektro', 'Tenaga Listrik & EBT', 'Merancang sistem pembangkit listrik tenaga surya (PLTS), sistem penyimpanan energi baterai (BESS), dan manajemen beban gardu distribusi.', 'Rp 8.500.000 - Rp 17.500.000', 'Tinggi', '2026-09-20 10:24:47', '2026-09-20 10:24:47'),
(19, 'Instrumentation & Process Control Specialist', 'elektro', 'Instrumentasi & Kontrol', 'Mengalibrasi transmitter instrumen cerdas (suhu, tekanan, laju aliran), kontrol katup pneumatik, dan sistem keselamatan pabrik kimia/minyak.', 'Rp 8.500.000 - Rp 18.000.000', 'Tinggi', '2026-09-20 10:24:47', '2026-09-20 10:24:47'),
(20, 'Telecommunication & RF Network Specialist', 'elektro', 'Telekomunikasi', 'Mengoptimalkan jaringan transmisi nirkabel seluler (4G/5G), penyambungan kabel fiber optik (splicing), dan instalasi microwave radio link.', 'Rp 8.000.000 - Rp 16.000.000', 'Menengah', '2026-09-20 10:24:47', '2026-09-20 10:24:47'),
(21, 'Edge AI & TinyML Hardware Specialist', 'elektro', 'Edge AI & Microcontrollers', 'Menerapkan model deep learning terkuantisasi (INT8) ke chip mikrokontroler hemat daya untuk klasifikasi audio, getaran, dan computer vision.', 'Rp 9.500.000 - Rp 20.000.000', 'Sangat Tinggi', '2026-09-20 10:24:47', '2026-09-20 10:24:47'),
(22, 'Industrial Electrical Maintenance & Safety Engineer', 'elektro', 'Pemeliharaan Listrik & K3', 'Memastikan keandalan sistem kelistrikan gardu pabrik 380V, perawatan preventif transformator, proteksi panel, dan penerapan standar K3 listrik.', 'Rp 8.000.000 - Rp 15.500.000', 'Tinggi', '2026-09-20 10:24:47', '2026-09-20 10:24:47'),
(23, 'Cloud Solutions Architect', 'it', 'Cloud & Infrastructure', 'Merancang arsitektur cloud terukur (scalable) dan aman menggunakan layanan AWS, GCP, atau Azure untuk enterprise.', 'Rp 12.000.000 - Rp 25.000.000', 'Sangat Tinggi', '2026-10-07 13:06:04', '2026-10-07 13:06:04'),
(24, 'IoT & Edge AI Engineer', 'elektro', 'Hardware & AI', 'Merancang dan mengimplementasikan model AI pada perangkat edge (ESP32, Jetson Nano) untuk sistem otomatisasi.', 'Rp 9.000.000 - Rp 18.000.000', 'Tinggi', '2026-10-07 13:06:13', '2026-10-07 13:06:13');
